// Contactos IG ya intentados enriquecer (username+foto). Antes era un Set de
// por-vida-del-proceso: si un intento NO devolvía foto (usuario fuera de la ventana
// de 24h, o permiso instagram_manage_messages sin aprobar en App Review), el contacto
// quedaba sin avatar PARA SIEMPRE. Ahora es un Map con TTL → se reintenta pasado el
// tiempo (cuando el contacto vuelva a escribir/entre en ventana o se aprueben permisos),
// sin martillear Graph en cada poll del inbox.
const igEnrichAttempted = new Map<string, number>();
const IG_ENRICH_TTL_MS = 24 * 60 * 60 * 1000; // 24 h (antes 6 h: IG-LLAMADAS-1)
const igEnrichRecently = (phone: string): boolean => {
  const t = igEnrichAttempted.get(phone);
  return t != null && Date.now() - t < IG_ENRICH_TTL_MS;
};
// IG-LLAMADAS-1 · un contacto cuya foto YA está guardada como bytes en BD (avatar_url
// apunta a nuestra ruta /admin/api/inbox/avatar/, no a la URL firmada de Meta que caduca)
// y cuyo nombre ya no es el IGSID crudo no necesita volver a consultarse a Meta: esas
// ~4.000 llamadas/día (IGBusinessScopedID + ShadowIGUser) agotaban el rate-limit de la
// app y dejaban sin cuota a los flujos. El nombre manual ya se respetaba.
const igEnrichNotNeeded = (stored: boolean, name?: string): boolean =>
  stored && !!name && !/^\d{10,}$/.test(String(name));
const igEnrichMark = (phone: string): void => { igEnrichAttempted.set(phone, Date.now()); };

// Cache in-memory de Open Graph (1h TTL). Key = URL absoluta normalizada.
type OgEntry = { ok: true; title: string; description: string; image: string; siteName: string; url: string } | { ok: false };
const ogCache = new Map<string, { t: number; v: OgEntry }>();

// Decodifica entidades HTML básicas (&amp; &lt; &gt; &quot; &#39; &#xNN; &#NN;)
// para que los OG tags lleguen al cliente como texto legible.
function decodeHtmlEntities(s: string): string {
  if (!s) return "";
  return s
    .replace(/&#x([0-9a-f]+);/gi, (_, h) => {
      try { return String.fromCodePoint(parseInt(h, 16)); } catch { return ""; }
    })
    .replace(/&#(\d+);/g, (_, n) => {
      try { return String.fromCodePoint(parseInt(n, 10)); } catch { return ""; }
    })
    .replace(/&amp;/g, "&")
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">")
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/&apos;/g, "'")
    .replace(/&nbsp;/g, " ");
}

// BANDEJA-LEIDOS-1 · ¿esta fila de la Bandeja tiene algo que esta persona no ha visto?
// «Sin leer» = el cliente escribió DESPUÉS de la última vez que se abrió ese chat (o de
// un «marcar como leídas» de su canal, de su número o de todo). Antes el punto era
// «el último mensaje es del cliente»: se apagaba en cuanto contestaba el bot y el
// contador del menú era el TOTAL de conversaciones, que sólo sabía crecer.
// Lo anterior a 'base' (el primer cálculo para esa persona) sólo cuenta si sigue
// esperando respuesta: así el primer día no aparecen miles de chats viejos sin leer.
function inboxSinLeer(reads: Record<string, number>, phone: string, account: string, channel: string, lastUserAt: number, lastRole: string, acctEf = "", negocio = ""): boolean {
  if (!lastUserAt) return false;
  const leido = Math.max(
    reads["*"] || 0,
    reads["ch:" + channel] || 0,
    // NEGOCIOS-BANDEJA-1 · «marcar como leídas» lo que se ve con UN negocio (y, si acaso,
    // unos canales) alcanza a TODAS sus filas, también las antiguas sin cuenta que la
    // Bandeja le atribuye al principal: una lista de cuentas se las dejaba encendidas.
    negocio ? reads["ng:" + negocio] || 0 : 0,
    negocio ? reads["nc:" + negocio + "|" + channel] || 0 : 0,
    account ? reads["ac:" + account] || 0 : 0,
    // NEGOCIOS-BANDEJA-1 · «marcar como leídas» una cuenta alcanza también a sus hilos
    // antiguos sin cuenta guardada, que la Bandeja ya le atribuye (cuenta efectiva).
    acctEf && acctEf !== account ? reads["ac:" + acctEf] || 0 : 0,
    reads["c:" + phone + "|" + account] || 0,
    reads["c:" + phone + "|*"] || 0,
  );
  if (lastUserAt <= leido) return false;
  return lastUserAt > (reads.base || 0) || lastRole === "user";
}
// Helpers de presentación compartidos (inbox, contactos, pipeline).
// R4-BANDEJA-CRM-1 · channelAccount ('wa:<pnid>' / 'ig:<igId>' / 'fb:<pageId>', lo
// escribe touchContact) es la MISMA cuenta que enruta el mensaje: más fiable que
// cualquier heurística sobre `source` o la longitud del id, así que decide antes
// que la heurística por longitud y antes del fallback a whatsapp — pero un source
// social EXPLÍCITO sigue mandando primero (ya se usa para corregir el propio
// channel_account en otros sitios, así que invertir el orden crearía un ciclo).
function chFor(source: string, id: string, channelAccount?: string): string {
  // Orden: un source social EXPLÍCITO (no whatsapp) manda — instagram/tiktok/
  // linkedin/facebook. Luego channel_account (cuenta real por la que entró el
  // mensaje). Luego la longitud del id (un IGSID de 16-17 díg es IG aunque el
  // source quedara mal puesto a "whatsapp" por el default de touchContact). Solo
  // al final el source "whatsapp" / patrón corto E.164.
  const s = (source || "").toLowerCase();
  if (s.includes("instagram")) return "instagram";
  if (s.includes("tiktok")) return "tiktok";
  if (s.includes("linkedin")) return "linkedin";
  if (s.includes("facebook") || s.includes("messenger")) return "facebook";
  const ca = channelAccount || "";
  if (ca.startsWith("ig:")) return "instagram";
  if (ca.startsWith("fb:")) return "facebook";
  if (ca.startsWith("wa:")) return "whatsapp";
  const numeric = /^\d+$/.test(id);
  if (numeric && id.length >= 15) return "instagram"; // IGSID 16-17 díg (gana a source=whatsapp erróneo)
  if (s.includes("whatsapp")) return "whatsapp";
  if (numeric && id.length >= 8 && id.length <= 14) return "whatsapp";
  return "unknown";
}
function initialsFor(nameOrId: string, id: string): string {
  return (
    nameOrId.split(/[\s.@]+/).filter(Boolean).slice(0, 2)
      .map((s) => s.charAt(0).toUpperCase()).join("") || id.slice(-2) || "?"
  );
}
function seedFor(id: string): number {
  let s = 0;
  for (let i = 0; i < id.length; i++) s = (s * 31 + id.charCodeAt(i)) % 360;
  return s;
}

// Pipelines (lista y paso de etapa con su etiqueta «📍»): viven en pipelines.ts, que
// comparten el panel y los formularios (FORMULARIOS-2).

// ESPERA-HM-1 · Las esperas de flujo se guardan en minutos pero se MUESTRAN en horas y
// minutos legibles («2 h 10 min»), en todas las vistas del servidor que resumen un paso.
// ESPERA-SEG-1 · delega en el motor: una sola forma de decir una espera en humano.
function esperaLbl(minutes: unknown, seconds?: unknown): string {
  return esperaHumana(minutes, seconds);
}

/** Catálogo de etiquetas definidas a mano (setting tags.catalog, array JSON). */
function tagCatalog(): string[] {
  try {
    const a = JSON.parse(getSetting("tags.catalog") || "[]");
    return Array.isArray(a) ? a.map((t) => String(t).trim()).filter(Boolean) : [];
  } catch {
    return [];
  }
}

/** Enriquece contactos IG (username + foto) que aún no lo tienen. Síncrono,
 *  1 intento por contacto/proceso. Compartido por inbox y contactos.
 *
 *  IG-PERFIL-1: antes esto metía TODOS los contactos por el token de la cuenta
 *  PRINCIPAL (meta.igAccessToken). Un DM que entró por una cuenta SECUNDARIA
 *  (p.ej. @ingenierobinario) no se puede resolver con el page token de la
 *  principal → Graph no devuelve nada y el contacto se quedaba para siempre con
 *  el IGSID crudo y un avatar con dos dígitos. Ahora se agrupa por
 *  `channel_account` ('ig:<igId>', lo escribe touchContact) y cada grupo se
 *  resuelve CON SU PROPIA cuenta. */
async function lazyEnrichIg(
  all: { phone: string; name: string; source: string; avatar_url?: string; channel_account?: string }[],
): Promise<void> {
  // Enriquece TODO contacto IG no intentado en este proceso: refresca username Y
  // foto. Clave para la foto: las URLs de perfil de IG son CDN firmado que CADUCA,
  // así que aunque ya tengamos una avatar_url, la re-pedimos fresca (una vez por
  // proceso, dedupe + slice(20) limitan el coste).
  if (igGraphPaused()) return; // IG-LLAMADAS-1: Meta limita la app → no gastar cuota en fotos
  const need = all.filter(
    (c) => chFor(c.source, c.phone, c.channel_account) === "instagram" && !igEnrichRecently(c.phone)
      && !igEnrichNotNeeded(String(c.avatar_url || "").startsWith("/admin/api/inbox/avatar/"), c.name),
  );
  if (!need.length) return;
  // ORDEN DE ATENCIÓN. Solo caben 20 por vuelta, así que el orden decide quién se
  // salva. Primero los que NO tienen foto (nunca la han tenido) y los que apuntan
  // a una URL del CDN de Meta — esas están FIRMADAS y caducan en horas, así que
  // son las que van a desaparecer solas. Los que ya están en nuestra caché no
  // corren prisa: su foto son bytes nuestros y no caduca.
  const riesgo = (c: { avatar_url?: string }): number => {
    const a = String(c.avatar_url || "");
    if (!a) return 0;                       // sin foto: lo más urgente
    if (/^https?:/i.test(a)) return 1;      // CDN de Meta: caduca
    return 2;                               // ya en nuestra caché: a salvo
  };
  need.sort((a, b) => riesgo(a) - riesgo(b));

  const mainToken = getSetting("meta.igAccessToken");
  const mainIgId = getSetting("meta.igBusinessId");
  const mainAcct = mainToken && mainIgId ? { token: mainToken, igId: mainIgId } : null;

  // Agrupa por la cuenta de Instagram POR LA QUE ENTRÓ cada conversación.
  const groups = new Map<string, typeof need>();
  for (const c of need) {
    const ca = String(c.channel_account || "");
    const igId = ca.startsWith("ig:") ? ca.slice(3) : "";
    const key = igId || "__main__";
    const g = groups.get(key);
    if (g) g.push(c);
    else groups.set(key, [c]);
  }

  for (const [key, group] of groups) {
    const acct = key === "__main__" ? mainAcct : resolveAccount(key) || mainAcct;
    if (!acct) continue; // sin credenciales para esa cuenta: no inventamos nada
    await runWithAccount(acct, async () => {
      await Promise.all(
        group.slice(0, 20).map(async (c) => {
          igEnrichMark(c.phone);
          // Pasa el @username ya guardado (del comentario) como pista → habilita el
          // fallback Business Discovery para sacar la foto aunque el user esté fuera
          // de la ventana de 24h. Solo si el nombre es un @handle (no el IGSID crudo).
          const hint = c.name && c.name.startsWith("@") ? c.name : undefined;
          const prof = await fetchIgUserProfile(c.phone, hint);
          if (!prof) return;
          const upd: { name?: string; avatar_url?: string } = {};
          // Si el nombre actual NO es un @handle ni el IGSID numérico crudo, es un
          // rename manual del usuario → no pisarlo (el refresco de la foto sigue).
          // Antes esta pasada revertía renombres cada 6h; con el enrich en segundo
          // plano la carrera con la sesión interactiva lo hacía más visible.
          const curName = String(c.name || "");
          const manualName = !!curName && !curName.startsWith("@") && !/^\d{10,}$/.test(curName);
          if (!manualName) {
            if (prof.username) upd.name = "@" + prof.username;
            else if (prof.name) upd.name = prof.name;
          }
          // FOTO-PERFIL-1 · nos quedamos los BYTES (la URL de Meta caduca) y
          // apuntamos el avatar a nuestra propia ruta, que ya no se rompe.
          if (prof.profilePic) {
            const yaTengo = await dbAvatarAge(c.phone).catch(() => null);
            const caducada = yaTengo == null || yaTengo > 7 * 24 * 3600 * 1000;
            if (caducada) {
              try {
                const res = await fetch(prof.profilePic);
                if (res.ok) {
                  const buf = Buffer.from(await res.arrayBuffer());
                  if (buf.length && buf.length < 3 * 1024 * 1024) {
                    await dbPutAvatar(c.phone, buf, String(res.headers.get("content-type") || "image/jpeg"));
                  }
                }
              } catch { /* si la descarga falla nos quedamos con lo que hubiera */ }
            }
            const propia = "/admin/api/inbox/avatar/" + encodeURIComponent(c.phone);
            // FOTO-CONTACTO-1 · la foto puesta a mano (edad 0) lleva su propia versión en la URL: no se toca.
            if (yaTengo !== 0) upd.avatar_url = (await dbGetAvatar(c.phone).catch(() => null)) ? propia : prof.profilePic;
          }
          if (Object.keys(upd).length) {
            await updateContact(c.phone, upd);
            Object.assign(c, upd);
          }
        }),
      );
    });
  }
}
