const PASSWORD = process.env.ADMIN_PASSWORD || "";
// SECRETOS-ARRANQUE-1 · con SESSION_SECRET definida las sesiones se firman con ella (rotar
// ADMIN_PASSWORD o APP_ENC_KEY ya no cierra todas las sesiones). Sin ella, como siempre:
// derivada de las dos. En producción comprobarSecretosDeArranque() (crypto.ts) avisa si falta.
const SESSION_SECRET = (process.env.SESSION_SECRET || "").trim();
const SECRET = crypto
  .createHash("sha256")
  .update(SESSION_SECRET ? "session-secret:" + SESSION_SECRET : `${PASSWORD}:${process.env.APP_ENC_KEY || crypto.randomBytes(32).toString("hex")}`)
  .digest("hex");

// Credenciales efectivas: settings (panel) > env > default. Login = email + contraseña.
const adminUser = (): string =>
  getSetting("admin.user") || process.env.ADMIN_USER || "admin";
const adminPass = (): string =>
  getSetting("admin.pass") || process.env.ADMIN_PASSWORD || "";

// ES-PRECARGA-1 · datos del negocio que el panel precarga en la ventana de alta de
// WhatsApp (Embedded Signup, extras.setup) para que el cliente solo tenga que
// confirmar, como en ManyChat. Se guardan por workspace en «whatsapp.setup» (JSON,
// sin secretos) y caen al nombre del negocio y a la zona horaria ya configurados.
const WA_SETUP_CAMPOS: ReadonlyArray<[string, number]> = [
  ["name", 100], ["email", 128], ["website", 256], ["country", 2],
  ["phoneCode", 4], ["phone", 20], ["displayName", 60], ["category", 32], ["description", 512],
];
function leerWaSetupPrecarga(): Record<string, string> {
  let s: Record<string, unknown> = {};
  try { const raw = getSetting("whatsapp.setup"); if (raw) s = JSON.parse(raw) || {}; } catch { s = {}; }
  const out: Record<string, string> = {};
  for (const [k, max] of WA_SETUP_CAMPOS) out[k] = String(s[k] ?? "").trim().slice(0, max);
  if (!out.name) out.name = (getSetting("brand.name") || "").trim().slice(0, 100);
  if (!out.displayName) out.displayName = out.name;
  out.timezone = getSetting("biz.timezone") || "";
  return out;
}
// Claves visibles/editables en la pestaña Ajustes.
/** REVISION-PREMIUM-3 · nombre en castellano de un ajuste, para el registro de Actividad: se leía
 *  «Ajuste «legal.entityRegAgent» actualizado» y a 390 px la clave partía a mitad de palabra. Lo que
 *  no esté en el mapa cae a su última parte separada en palabras, que ya se lee mucho mejor. */
const NOMBRES_DE_AJUSTE: Record<string, string> = {
  "brand.name": "Nombre del negocio",
  "menu.ocultas": "Secciones ocultas del menú",
  // MARCA-BLANCA-2 · el nombre del panel, el que se ve en la pestaña del navegador.
  "brand.product_name": "Nombre del panel",
  "legal.entityRegAgent": "Representante legal",
  "legal.entityName": "Nombre de la empresa",
  "legal.entityId": "Identificación fiscal",
  "legal.entityAddress": "Dirección de la empresa",
  "legal.contactEmail": "Correo de contacto legal",
  "ai.generatedContentLabel": "Sello en las respuestas con IA",
  "ai.transparencyNotice": "Aviso de que responde una IA",
  "links.preview_no_image": "Vista previa de enlaces sin imagen",
  "links.preview_square_og": "Vista previa de enlaces con imagen cuadrada",
  "links.preview_square_img": "Imagen cuadrada de tu marca para las vistas previas",
  "meetings.notify": "Avisos de reuniones",
  "autoReply.whatsapp": "Respuestas automáticas de WhatsApp",
  "autoReply.instagram": "Respuestas automáticas de Instagram",
  "autoReply.facebook": "Respuestas automáticas de Facebook",
  "autoReply.youtube": "Respuestas automáticas de YouTube",
  "systemeio.stopTag": "Etiqueta que marca una compra",
  // DISENO-1 · apps de Meta, LinkedIn Ads y Google Ads (las guarda el operador desde las vistas de Ads con ajusteRapido).
  "meta.appId": "Identificador de la app de Meta",
  "meta.appSecret": "Secreto de la app de Meta",
  "linkedin.clientId": "Identificador de la app de LinkedIn",
  "linkedin.clientSecret": "Secreto de la app de LinkedIn",
  "googleads.clientId": "Identificador de la app de Google",
  "googleads.clientSecret": "Secreto de la app de Google",
  "googleads.developerToken": "Clave de desarrollador de Google Ads",
  // DISENO-1 · R2-METRI-08 · la app de Google que activa YouTube, con el mismo par
  // identificador/secreto que LinkedIn y Google Ads.
  "youtube.clientId": "Identificador de la app de Google para YouTube",
  "youtube.clientSecret": "Secreto de la app de Google para YouTube",
};
function nombreDeAjuste(key: string): string {
  const k = String(key || "");
  if (NOMBRES_DE_AJUSTE[k]) return NOMBRES_DE_AJUSTE[k];
  const ultima = k.split(".").pop() || k;
  const palabras = ultima.replace(/([a-z0-9])([A-Z])/g, "$1 $2").replace(/[_-]+/g, " ").toLowerCase().trim();
  return palabras ? palabras.charAt(0).toUpperCase() + palabras.slice(1) : k;
}
