    const t = PAGE_TEMPLATES.find((x) => x.id === b.template_id);
    if (!t) return reply.code(404).send({ error: "template no encontrado" });
    const data = (b.data ?? {}) as Record<string, string>;
    const rendered = renderTemplate(t, data);
    // Mismo helper que saveDraft → el preview muestra CSS/JS/HTML propios tal cual
