  // Saneo: colapsa mensajes REPETIDOS CONSECUTIVOS (mismo rol + mismo texto) en las
  // conversaciones. Limpia los dobles que dejó el eco de Instagram antes del arreglo.
  // Solo toca duplicados pegados (no borra un mensaje legítimo repetido más tarde).
  // BANDEJA-LEIDOS-1 · marcar como leído: un chat al abrirlo, o de golpe un canal, un
  // número o todo («Marcar como leídas»). Las marcas son de la PERSONA que lo hace.
  app.post("/admin/api/inbox/read", async (req, reply) => {
    if (!(await guard(req, reply))) return;
    const actor = await resolveActor(req);
    if (!actor) return reply.code(401).send({ ok: false, error: "Sesión caducada" });
    const meKey = actor.kind === "env" ? "env-admin" : "u:" + actor.user.id;
    const b = (json(req) ?? {}) as { phone?: unknown; acct?: unknown; channel?: unknown; account?: unknown; all?: unknown; accounts?: unknown; channels?: unknown; negocios?: unknown };
    const keys: string[] = [];
    if (b.all === true) keys.push("*");
    if (typeof b.phone === "string" && b.phone) keys.push("c:" + b.phone + "|" + (typeof b.acct === "string" ? b.acct : "*"));
    // NEGOCIOS-BANDEJA-1 · con una selección de negocios y canales se marcan VARIAS cuentas
    // (o varios canales) de una vez: lo que la usuaria está viendo, ni más ni menos.
    const cuentas = [b.account, ...(Array.isArray(b.accounts) ? b.accounts.slice(0, 50) : [])];
    for (const a of cuentas) if (typeof a === "string" && /^(wa|ig|fb):[\w.-]{1,80}$/.test(a)) keys.push("ac:" + a);
    const canales = [...new Set([b.channel, ...(Array.isArray(b.channels) ? b.channels : [])])].filter((c): c is string => typeof c === "string" && /^(whatsapp|instagram|facebook|tiktok|linkedin)$/.test(c));
    const negocios = [...new Set((Array.isArray(b.negocios) ? b.negocios : []).filter((n): n is string => typeof n === "string" && /^[\w.@-]{1,80}$/.test(n)))].slice(0, 20); // BAN-03-TOPE-1: sin repetidos y con tope, o negocios × canales crece sin límite
    // Con negocios, los canales acotan DENTRO de ellos (negocio × canal); sin negocios, el canal entero.
    if (negocios.length) for (const n of negocios) { if (canales.length) for (const c of canales) keys.push("nc:" + n + "|" + c); else keys.push("ng:" + n); }
    else for (const c of canales) keys.push("ch:" + c);
    if (!keys.length) return reply.code(400).send({ ok: false, error: "Falta qué marcar como leído" });
    const at = await dbSetInboxReads(meKey, keys);
    inboxUnreadMemo.clear();
    dbTocarBandeja(); // UNREAD-PROPIO-1 · un cálculo en vuelo de antes de marcar no se guarda
    return { ok: true, at };
  });
  // BANDEJA-LEIDOS-1 · número del menú lateral fuera de la Bandeja: chats sin leer
  // (el mismo número que la pestaña «Todos»). Sale del PROPIO listado (misma sesión, mismo workspace) y no de una copia
  // de su lógica: partir el chat por número y fundir el mismo teléfono por dos vías es
  // delicado, y una réplica acabaría dando un número distinto al de la Bandeja.
  // UNREAD-PROPIO-1 · caché de 20 s por workspace+persona+selección, invalidada por la versión de la
  // Bandeja (sube con cada conversación guardada/borrada y con cada NOTIFY bstack_inbox) y al marcar
  // leído. Las peticiones simultáneas comparten un solo cálculo.
  const inboxUnreadMemo = new Map<string, { at: number; v: number; n: number; w: number }>();
  const inboxUnreadVuelo = new Map<string, Promise<{ code: number; n: number; w: number }>>();
  app.get("/admin/api/inbox/unread", async (req, reply) => {
    if (!(await guard(req, reply))) return;
    const actor = await resolveActor(req);
    if (!actor) return { unread: 0 };
    const meKey = actor.kind === "env" ? "env-admin" : "u:" + actor.user.id;
    // NEGOCIOS-BANDEJA-1 · el número del menú respeta la selección de la Bandeja.
    const qu = req.query as Record<string, string>;
    const sel = new URLSearchParams();
    for (const k of ["negocios", "channels"]) if (typeof qu[k] === "string" && qu[k] && qu[k].length <= 400) sel.set(k, qu[k]);
    const mk = currentWorkspaceId() + "|" + meKey + "|" + sel.toString();
    const hit = inboxUnreadMemo.get(mk);
    const ver = dbVersionBandeja();
    if (hit && hit.v === ver && Date.now() - hit.at < 20000) return { unread: hit.n, ventana: hit.w };
    let vuelo = inboxUnreadVuelo.get(mk);
    if (!vuelo) {
      const headers: Record<string, string> = {};
      for (const h of ["cookie", "x-workspace-id", "authorization"]) {
        const v = req.headers[h];
        if (typeof v === "string" && v) headers[h] = v;
      }
      vuelo = app.inject({ method: "GET", url: "/admin/api/inbox?countsOnly=1" + (sel.toString() ? "&" + sel.toString() : ""), headers })
        .then((r) => {
          if (r.statusCode !== 200) return { code: r.statusCode, n: 0, w: 0 };
          const cs = (r.json() as { counts?: { unreadAll?: number; unreadWin?: number } }).counts;
          const n = Number(cs?.unreadAll || 0), w = Number(cs?.unreadWin || 0);
          if (inboxUnreadMemo.size > 500) inboxUnreadMemo.clear();
          inboxUnreadMemo.set(mk, { at: Date.now(), v: ver, n, w });
          return { code: 200, n, w };
        })
        .finally(() => inboxUnreadVuelo.delete(mk));
      inboxUnreadVuelo.set(mk, vuelo);
    }
    const res = await vuelo;
    if (res.code !== 200) return reply.code(res.code).send({ unread: 0 });
    return { unread: res.n, ventana: res.w };
  });
  app.post("/admin/api/inbox/dedup", async (req, reply) => {
    if (!(await guard(req, reply))) return;
    const convs = await dbRecentConversations(1000);
    let cleaned = 0;
    let removed = 0;
    for (const c of convs) {
      const turns = Array.isArray((c as { turns?: unknown }).turns) ? ((c as { turns: { role?: string; content?: string }[] }).turns) : [];
      const out: typeof turns = [];
      for (const t of turns) {
        const prev = out[out.length - 1];
        if (prev && prev.role === t.role && String(prev.content || "") === String(t.content || "")) { removed++; continue; }
        out.push(t);
      }
      if (out.length !== turns.length) {
        try { await dbSaveConversation((c as { user_id: string }).user_id, (c as { bot_id?: string }).bot_id || "", out); cleaned++; } catch { /* sigue con la siguiente */ }
      }
    }
    return { ok: true, conversaciones_revisadas: convs.length, conversaciones_saneadas: cleaned, mensajes_duplicados_eliminados: removed };
  });
  // Pool de leads: "Reclamar" → el closer logueado se hace dueño (si nadie lo tiene aún).
