      const mime = String(rawMedia.mime || "application/octet-stream").toLowerCase();
      const name = String(rawMedia.name || "archivo").slice(0, 200);
      const b64 = String(rawMedia.dataB64 || rawMedia.data || "").replace(/^data:[^;]+;base64,/, "");
      if (!b64) return reply.code(400).send({ error: "Adjunto sin datos." });
      let buf: Buffer;
