      app.log.warn({ phone, canal: isFb ? "facebook" : isIg ? "instagram" : "whatsapp", err: (e as Error)?.message, causa: (e as { causa?: string })?.causa, code: (e as { code?: string })?.code }, "Envío desde la Bandeja fallido");
      return reply.code(502).send({ error: errorEnvioLegible(isFb ? "facebook" : isIg ? "instagram" : "whatsapp", e), detalle: (e as { causa?: string })?.causa || undefined });
