  // Respuestas (de un formulario o de todos), la más reciente primero.
  app.get("/admin/api/formularios/respuestas", async (req, reply) => {
    if (!(await guard(req, reply))) return;
    const q = req.query as Record<string, string>;
    const rows = await dbListFormResponses({ formId: String(q.form || "") || undefined, limit: 2000 });
    return { rows: await foSyncLegible(rows) };
  });
  app.get("/admin/api/formularios/exportar", async (req, reply) => {
    if (!(await guard(req, reply))) return;
    const q = req.query as Record<string, string>;
    const rows = await dbListFormResponses({ formId: String(q.form || "") || undefined, limit: 10000 });
    // Una columna por pregunta (en el orden en que aparecen); celdas que empiezan por
    // = + - @ se neutralizan para que la hoja de cálculo no las ejecute.
    const preguntas: string[] = [];
    for (const r of rows) for (const a of r.answers) if (!preguntas.includes(a.label)) preguntas.push(a.label);
    const cel = (s: unknown) => { let t = String(s ?? "").replace(/\r?\n/g, " "); if (/^[=+\-@]/.test(t)) t = "'" + t; return `"${t.replace(/"/g, '""')}"`; };
    const lines = [
      ["Fecha", "Formulario", "Origen", "Nombre", "Correo", "Teléfono", ...preguntas].map(cel).join(","),
      ...rows.map((r) => [
        new Date(r.created_at).toLocaleString("es-ES", { timeZone: "Europe/Madrid" }), r.form_title, r.source === "typeform" ? "Typeform" : "Tu formulario", r.name, r.email, r.phone,
        ...preguntas.map((p) => r.answers.find((a) => a.label === p)?.v || ""),
      ].map(cel).join(",")),
    ];
    const nombre = (String(q.form || "") ? slugDireccion(rows[0]?.form_title || "formulario") : "formularios") + "-respuestas.csv";
    return reply
      .header("Content-Type", "text/csv; charset=utf-8")
      .header("Content-Disposition", `attachment; filename="${nombre}"`)
      .send("﻿" + lines.join("\n"));
  });
