  app.post("/admin/api/li-autoreply", async (req, reply) => {
    if (!(await guard(req, reply))) return;
    const b = (json(req) ?? {}) as { enabled?: boolean; dailyCap?: number; pollSec?: number };
    if (typeof b.dailyCap === "number" && Number.isFinite(b.dailyCap)) {
      await setSetting("linkedin.autoreply.dailyCap", String(Math.max(0, Math.min(200, Math.floor(b.dailyCap)))));
    }
    // POLL-CONFIG-1 · cada cuánto mira comentarios (segundos; suelo 5 min, techo 24 h).
    if (typeof b.pollSec === "number" && Number.isFinite(b.pollSec)) {
      await setSetting("linkedin.autoreply.pollSec", String(Math.max(300, Math.min(86400, Math.floor(b.pollSec)))));
    }
    if (typeof b.enabled === "boolean") {
      const was = getSetting("linkedin.autoreply.enabled") === "true";
      await setSetting("linkedin.autoreply.enabled", b.enabled ? "true" : "false");
      if (b.enabled && !was) await linkedinAutoreplyArm();
    }
    return { ok: true, autoreply: await liAutoreplyEstado() };
  });
  // Página(s) conectadas + selección/desconexión (tarjeta de Conexiones).
