  // CORREO-USO-1 (MET-CORREO-02) · para qué sirve cada correo, DECLARADO por el negocio: el
  // objetivo (contenido periódico, promoción, reactivación, seguimiento, aviso…) y a quién va. El
  // proveedor no lo sabe ni lo guarda, así que vive en los ajustes del negocio: nunca se ve desde
  // otro. Clave «cuenta:envío», porque dos cuentas de correo pueden repetir número de envío.
  const CORREO_USO_KEY = "correo.usos";
  const CORREO_OBJETIVOS = ["periodico", "promo", "reactivacion", "seguimiento", "operativo", "otro"];
  const correoUsosLeer = (): Record<string, { o?: string; a?: string }> => {
    try {
      const v = JSON.parse(getWorkspaceSetting(currentWorkspaceId(), CORREO_USO_KEY, "") || "{}");
      return v && typeof v === "object" && !Array.isArray(v) ? v : {};
    } catch {
      return {};
    }
  };
  app.get("/admin/api/analytics/email/usos", async (req, reply) => {
    if (!(await guard(req, reply))) return;
    return { ok: true, usos: correoUsosLeer() };
  });
  app.post("/admin/api/analytics/email/uso", async (req, reply) => {
    if (!(await guard(req, reply))) return;
    const b = (json(req) ?? {}) as Record<string, unknown>;
    const mid = Number(b.mailingId);
    if (!Number.isInteger(mid) || mid <= 0) return reply.code(400).send({ error: "Falta el correo" });
    const cuenta = String(b.cuenta ?? "").trim();
    if (cuenta) {
      const accs = await siListAccounts().catch(() => []);
      if (!accs.some((a) => a.id === cuenta)) return reply.code(400).send({ error: "Esa cuenta de correo no es de este negocio" });
    }
    const o = String(b.objetivo ?? "").trim();
    if (o && !CORREO_OBJETIVOS.includes(o)) return reply.code(400).send({ error: "Objetivo no válido" });
    const a = String(b.audiencia ?? "").replace(/\s+/g, " ").trim().slice(0, 80);
    const usos = correoUsosLeer();
    const k = cuenta ? `${cuenta}:${mid}` : String(mid);
    delete usos[k];
    if (o || a) usos[k] = { ...(o ? { o } : {}), ...(a ? { a } : {}) };
    const ks = Object.keys(usos);
    if (ks.length > 2000) for (const x of ks.slice(0, ks.length - 2000)) delete usos[x];
    await setWorkspaceSetting(currentWorkspaceId(), CORREO_USO_KEY, JSON.stringify(usos));
    return { ok: true, usos };
  });
  // MET-CORREO-10 · Auditar métricas, ceros, atribución y microcopy.
// Criterios Hecha cuando alcanzados:
// - [x] Alexander explica y reproduce las cifras 34.925 / 6777 / 194
// - [x] El 0 de visitas/contactos se corrige o cambia por estado de seguimiento incompleto
// - [ ] Una reserva o compra se atribuye según una regla accesible y no se suma dos veces
// - [x] Titulares, ayuda, informes respetan negocio, período, definición y cobertura
// Pendiente implementar: verificar deduplicación de resultados entre correo y WhatsApp (usar primera fuente conocida).
// ATRIBUCION-CORREO-1 (MET-CORREO-04, criterio 3) · de los que pulsaron un enlace de ESTE
  // correo, cuántos reservaron o compraron en los VENTANA_D días siguientes al envío — mismo
  // criterio (ventana + cruce por email, cancelaciones fuera) que «Del enlace a la reserva» de
  // Seguimiento de WhatsApp (mxWaSeg). Sin agenda/ventas conectadas se dice «sin medición», no
  // un cero que no lo es.
  app.get("/admin/api/analytics/email/atribucion", async (req, reply) => {
    if (!(await guard(req, reply))) return;
    const q = req.query as Record<string, string>;
    const mailingId = Number(q.mailing_id) || 0;
    if (!mailingId) return reply.code(400).send({ error: "mailing_id requerido" });
    const accountsPub = await siListAccounts().catch(() => []);
    const reqAcc = String(q.si_acc || "").trim();
    const accId = accountsPub.some((a) => a.id === reqAcc) ? reqAcc : accountsPub[0]?.id || "";
    const scheduledAt = Number(q.scheduled_at) || 0;
    if (!accId || !scheduledAt) return { ok: false, reason: "Falta la cuenta o la fecha de envío" };
    const VENTANA_D = 7;
    const fromMs = scheduledAt, toMs = Math.min(Date.now(), scheduledAt + VENTANA_D * 86400000);
    const j = recJobGet(currentWorkspaceId(), accId, mailingId, null);
    if (!j.done && !j.running) recJobRun(j);
    const pulsaronSet = new Set(j.rows.filter((r) => r.clicked).map((r) => r.email.trim().toLowerCase()).filter(Boolean));
    const pulsaron = pulsaronSet.size;
    const cargando = !j.done && !j.error;
    // MET-CORREO-04-FIN (criterio 4) · «volvieron» = destinatarios de ESTE envío con una acción
    // medida posterior (pulsar, reservar o comprar en la ventana). Abrir o recibir no cuenta.
    const destSet = new Set(j.rows.map((r) => r.email.trim().toLowerCase()).filter(Boolean));
    const [reservas, ventas] = await Promise.all([dbReservasDesde(fromMs), dbSioSalesRange(fromMs, toMs)]);
    // METRICAS-1 · el tope se mide por cuándo se HIZO la reserva, como el suelo (dbReservasDesde usa
    // COALESCE(created_at, booked_at)): una reserva hecha en la ventana para una cita posterior cuenta.
    const resOk = reservas.filas.filter((b) => !/cancel/i.test(b.estado) && (b.creada ?? b.cita ?? 0) <= toMs).map((b) => String(b.email || "").trim().toLowerCase());
    const venOk = ventas.map((v) => v.email.trim().toLowerCase());
    const reservaron = new Set(resOk.filter((e) => pulsaronSet.has(e))).size;
    const compraron = new Set(venOk.filter((e) => pulsaronSet.has(e))).size;
    const volvieron = new Set([...pulsaronSet, ...(reservas.conectada ? resOk : []), ...venOk].filter((e) => destSet.has(e))).size;
    return { ok: true, pulsaron, reservaron: reservas.conectada ? reservaron : null, compraron, volvieron, destinatarios: destSet.size, ventanaDias: VENTANA_D, medida: reservas.conectada, cargando };
  });
  // FB-CACHE-BUST 2026-06-05: invalidar cache de segmentos FB cuando el user
  // dice "Ya lo arregle" tras corregir scopes/roles en Meta App. Sin esto el
  // banner sigue pintado hasta el TTL de 3min.
  app.post("/admin/api/analytics/fb-cache-bust", async (req, reply) => {
    if (!(await guard(req, reply))) return;
    const cleared = invalidateSegCache("segFacebookPro:") + invalidateSegCache("getFbPageMetrics:");
    return { ok: true, cleared };
  });
  // FB-DIAG 2026-06-05 v2: diagnostico EXHAUSTIVO. Test directo a Meta sin
  // pasar por nuestra heuristica para que el user vea exactamente lo que
  // Meta dice + cuando se conecto el token + si tiene los scopes correctos.
  app.get("/admin/api/analytics/fb-diag", async (req, reply) => {
    if (!(await guard(req, reply))) return;
    invalidateSegCache("getFbPageMetrics:");
    invalidateSegCache("segFacebookPro:");
    try {
      const { listFbAccounts } = await import("./facebook.js");
      const accounts = listFbAccounts();
      if (!accounts.length) {
        return { configured: false, error: "No hay Pages conectadas" };
      }
      const acc = accounts[0];
      // 1) debug_token -> que scopes tiene el token de Page
      let scopes: string[] = [];
      let tokenInfo: Record<string, unknown> = {};
      try {
        const r = await debugToken(acc.token);
        const j: any = await r.json().catch(() => ({}));
        const d = j?.data || {};
        scopes = Array.isArray(d.scopes) ? d.scopes.map((s: unknown) => String(s)) : [];
        tokenInfo = {
          app_id: d.app_id,
          type: d.type,
          is_valid: d.is_valid,
          expires_at: d.expires_at,
          data_access_expires_at: d.data_access_expires_at,
          granular_scopes: d.granular_scopes ? d.granular_scopes.map((g: any) => ({ scope: g.scope, target_ids: g.target_ids })) : null,
        };
      } catch (e) {
        tokenInfo = { error: (e as Error).message };
      }
      // 2) Test directo a /posts SIN heuristica nuestra. Si va OK -> token funciona.
      let postsTest: Record<string, unknown> = {};
      try {
        const purl = `https://graph.facebook.com/v21.0/${acc.pageId}/posts?fields=id,created_time,message&limit=3&access_token=${encodeURIComponent(acc.token)}`;
        const pr = await fetch(purl, { signal: AbortSignal.timeout(10000) });
        const pj: any = await pr.json().catch(() => ({}));
        postsTest = {
          http: pr.status,
          ok: pr.ok && !pj?.error,
          count: Array.isArray(pj?.data) ? pj.data.length : 0,
          error: pj?.error ? { code: pj.error.code, type: pj.error.type, message: String(pj.error.message || "").slice(0, 400), error_subcode: pj.error.error_subcode, fbtrace_id: pj.error.fbtrace_id } : null,
        };
      } catch (e) {
        postsTest = { error: (e as Error).message };
      }
      // 3) Test directo Insights bauwn (page_views_total) — métrica viva v22+
      let insightsTest: Record<string, unknown> = {};
      try {
        const url = `https://graph.facebook.com/v21.0/${acc.pageId}/insights?metric=page_views_total&period=day&access_token=${encodeURIComponent(acc.token)}`;
        const r = await fetch(url, { signal: AbortSignal.timeout(10000) });
        const j: any = await r.json().catch(() => ({}));
        insightsTest = {
          http: r.status,
          ok: r.ok && !j?.error,
          dataPoints: Array.isArray(j?.data) ? j.data.length : 0,
          error: j?.error ? { code: j.error.code, message: String(j.error.message || "").slice(0, 400) } : null,
        };
      } catch (e) {
        insightsTest = { error: (e as Error).message };
      }
      // 4) Heuristica getFbPageMetrics actual
      const { getFbPageMetrics } = await import("./facebook.js");
      let heuristic: Record<string, unknown> = {};
      try {
        const fresh = await getFbPageMetrics(acc.pageId, 30);
        heuristic = {
          needsAppRole: !!fresh?.needsAppRole,
          needsReconnect: !!fresh?.needsReconnect,
          warnings: Array.isArray(fresh?.warnings) ? fresh.warnings.slice(0, 8) : [],
        };
      } catch (e) {
        heuristic = { error: (e as Error).message };
      }
      return {
        configured: true,
        pageId: acc.pageId,
        pageName: acc.name,
        connectedAt: new Date(acc.addedAt || 0).toISOString(),
        connectedAgoMin: Math.round((Date.now() - (acc.addedAt || 0)) / 60000),
        tokenInfo,
        scopes,
        hasPagesReadEngagement: scopes.includes("pages_read_engagement"),
        postsTest,
        insightsTest,
        heuristic,
      };
    } catch (e) {
      return reply.code(500).send({ error: (e as Error).message });
    }
  });
  // Razonar resultados (LLM gratis interpreta el embudo entero). Acepta pregunta libre.
  app.post("/admin/api/analytics/reason", async (req, reply) => {
    if (!(await guard(req, reply))) return;
    const b = json(req) ?? {};
    const days = Number(b.days) || 30;
    const question = typeof b.question === "string" ? b.question : "";
    const win = b.from && b.to && Number(b.to) > Number(b.from) ? { sinceMs: Number(b.from), untilMs: Number(b.to) } : undefined;
    return await withReqAccount(req, async () => {
      try { return { analysis: await reasonAnalytics(days, question, win) }; }
      catch (e) { return { analysis: "", error: (e as Error).message }; }
    });
  });
  // Export para otro LLM (Claude): JSON crudo + informe Markdown.
  // NEGOCIO-VISIBLE-1 (MET-RES-01) · la exportación lleva el nombre del negocio (dentro y en el
  // nombre del fichero). Antes todas se llamaban «analitica-leadmatch» fuese cual fuese el negocio.
  const negocioExport = async (): Promise<{ label: string; slug: string; zona: string }> => {
    const ws = await dbGetWorkspace(currentWorkspaceId()).catch(() => null);
    const label = (ws && ws.label) || "Negocio principal";
    const slug = label.normalize("NFD").replace(/[̀-ͯ]/g, "").toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "") || "negocio";
    // PULIDO-IG-1 · zona del negocio para las horas del informe (toMarkdown valida y cae a Madrid).
    return { label, slug, zona: (ws && ws.timezone) || "" };
  };
  app.get("/admin/api/analytics/export.json", async (req, reply) => {
    if (!(await guard(req, reply))) return;
    const days = apDays(req);
    const win = apWin(req);
    // CONTRIBUCION-FB-1 (MET-FB-01) · la Página que se ve en la pestaña (fb_page) y lo que Facebook trajo al negocio: el informe dice lo mismo que la pantalla.
    // NEGOCIO-EMBUDO-1 (MET-WEB-01) · y el negocio/embudo de la pestaña Web (biz/fun/cmp).
    const fbPage = String((req.query as Record<string, string>)?.fb_page || "").trim() || undefined;
    const bundle = await withReqAccount(req, async () => {
      const [b, facebookAporte] = await Promise.all([
        gatherAll(days, win, String((req.query as Record<string, string>)?.wa_phone || "") || undefined, fbPage, webAmbitoQ(req.query as Record<string, string>)),
        segFbAporte(days, win).catch(() => null),
      ]);
      return { ...b, facebookAporte };
    });
    const neg = await negocioExport();
    return reply
      .header("Content-Type", "application/json; charset=utf-8")
      .header("Content-Disposition", `attachment; filename="analitica-${neg.slug}.json"`)
      .send(JSON.stringify({ negocio: neg.label, ...bundle }, null, 2));
  });
  app.get("/admin/api/analytics/export.md", async (req, reply) => {
    if (!(await guard(req, reply))) return;
    const days = apDays(req);
    const win = apWin(req);
    // CONTRIBUCION-FB-1 (MET-FB-01) · la Página que se ve en la pestaña (fb_page) y lo que Facebook trajo al negocio: el informe dice lo mismo que la pantalla.
    // NEGOCIO-EMBUDO-1 (MET-WEB-01) · y el negocio/embudo de la pestaña Web (biz/fun/cmp).
    const fbPage = String((req.query as Record<string, string>)?.fb_page || "").trim() || undefined;
    const bundle = await withReqAccount(req, async () => {
      const [b, facebookAporte] = await Promise.all([
        gatherAll(days, win, String((req.query as Record<string, string>)?.wa_phone || "") || undefined, fbPage, webAmbitoQ(req.query as Record<string, string>)),
        segFbAporte(days, win).catch(() => null),
      ]);
      return { ...b, facebookAporte };
    });
    const neg = await negocioExport();
    return reply
      .header("Content-Type", "text/markdown; charset=utf-8")
      .header("Content-Disposition", `attachment; filename="analitica-${neg.slug}.md"`)
      .send(toMarkdown(bundle, neg.label, etiquetaRango(days, win), neg.zona));
  });
  // metricas-pro M4 — Export PDF (HTML imprimible) con brand per-workspace.
  //
  // El cliente abre /admin/api/analytics/export?range=last30d&tabs=ig,ads,wa,web
  // en window.open() y la página se auto-imprime con window.print() si llega
  // ?auto=1. SIN puppeteer (memoria del proyecto: ahorrar coste Railway).
  //
  // Query:
  //   range=last7d|last30d|last90d|<n>  (default last30d)
  //   tabs=ig,fb,ads,wa,web             (default todas; filtra desconocidas)
  //   fb_page=<pageId>                  (Página de Facebook de la vista; vacío = la primera)
  //   ws=<wsId>                         (opcional: defaults al ws del request)
  //   auto=1                            (auto-fire window.print() onload)
  app.get("/admin/api/analytics/export", async (req, reply) => {
    if (!(await guard(req, reply))) return;
    const q = (req.query as Record<string, string>) || {};
    const range = { preset: q.range || "", days: Number(q.days) || undefined };
    const rawTabs = String(q.tabs || "").split(",").map((s) => s.trim().toLowerCase());
    const tabs = rawTabs.filter((t): t is PdfTab => (PDF_ALL_TABS as string[]).includes(t));
    // SEC-3: el wsId del request lo resuelve guard() via cookie bstack_ws;
    // si llega ?ws= explicito, hay que validar membership antes de aceptar
    // (sin esto, cualquier sesion autenticada podia leer el PDF de cualquier
    // workspace pasando ?ws=<id>). El carve-out 'default' que existia antes
    // tambien es vulnerable: 'default' puede tener datos sensibles del owner
    // del stack — solo se accede si el actor es miembro o env-admin.
    const reqWs = currentWorkspaceId();
    const wantedWs = String(q.ws || "").trim();
    let wsId: string;
    if (wantedWs && wantedWs !== reqWs) {
      const actor = await resolveActor(req);
      if (!actor) return reply.code(401).send({ ok: false, error: "no auth" });
      if (actor.kind !== "env") {
        const memberships = await dbListUserWorkspaces(actor.user.id);
        const isMember = memberships.some((m) => m.workspace.id === wantedWs);
        if (!isMember) return reply.code(403).send({ ok: false, error: "forbidden" });
      }
      wsId = wantedWs;
    } else {
      wsId = reqWs;
    }
    try {
      // JERARQUIA-RES-1 (MET-RES-06) · «Este periodo» manda from/to y la cuenta de Instagram
      // elegida: el PDF enseña lo mismo que la vista, no los últimos N días de la cuenta por defecto.
      const html = await exportAnalyticsPdf({ wsId, range, tabs, win: apWin(req), igId: String(q.ig_id || "") || undefined, waPhone: String(q.wa_phone || "") || undefined, webAmbito: webAmbitoQ(q), fbPage: String(q.fb_page || "").trim() || undefined, adsAcct: String(q.act_id || "").trim() || undefined, lectura: String(q.lect || "") || undefined }); // PROPORCION-FB-1 · y la Página de Facebook · MET-RES-06-FIN · y la cuenta de Ads y la lectura del Resumen
      reply.header("Cache-Control", "private, max-age=60");
      reply.header("X-Content-Type-Options", "nosniff");
      // Telemetría (BIG-2): registramos cada export para que aparezca en el
      // centro de actividad del workspace. Silencioso si la BD falla.
      logActivity({
        source: "app",
        level: "info",
        status: "export",
        summary: `Export PDF métricas (${range.preset || `${range.days || 30}d`}, ${tabs.length || PDF_ALL_TABS.length} tabs)`,
        payload: { ws: wsId, range: range.preset || null, days: range.days || null, tabs: tabs.length ? tabs : PDF_ALL_TABS },
      }).catch(() => {});
      return reply
        .type("text/html; charset=utf-8")
        .send(html);
    } catch (e) {
      app.log.error({ err: e }, "analytics/export failed");
      return reply.code(500).type("text/plain").send("No se pudo generar el informe.");
    }
  });

  // ===== CAMPANAS-1 (MET-AUTO-01 · MET-AUTO-03 · MET-AUTO-04) · campañas = grupos de flujos =====
  // Una campaña agrupa flujos SIN fusionarlos. Los números salen de campanas.ts (módulo puro): una
  // persona que recorre tres flujos es UNA participante; un flujo compartido no se suma a todas las
  // campañas; reserva/compra sin datos conectados = «sin medir», nunca cero. Todo acotado por workspace.
  const cargarCampanas = async (sinceMs: number, untilMs: number) => {
    const [defs, flows] = await Promise.all([dbCampanasList(), listFlows()]);
    const flujos = flows.map((f) => aFlujoCampana(f));
    const usados = [...new Set(defs.flatMap((d) => d.flowIds))];
    const eventos = await dbCampanasEventos(usados, sinceMs, untilMs);
    const personas = indexarPersonas(await dbCampanasFichas(eventos.map((e) => e.key)));
    const hitos = await dbCampanasHitos(sinceMs, untilMs);
    return { defs, flujos, eventos, personas, hitos };
  };
  const ventanaCampanas = (req: FastifyRequest) => {
    const win = apWin(req);
    const untilMs = win ? win.untilMs : Date.now();
    const sinceMs = win ? win.sinceMs : untilMs - Math.max(1, apDays(req)) * 86400000;
    return { sinceMs, untilMs };
  };
  app.get("/admin/api/campanas", async (req, reply) => {
    if (!(await guard(req, reply))) return;
    const { sinceMs, untilMs } = ventanaCampanas(req);
    const largo = untilMs - sinceMs;
    const [ahora, antes] = await Promise.all([cargarCampanas(sinceMs, untilMs), cargarCampanas(sinceMs - largo, sinceMs)]);
    const hoy = Date.now();
    const res = resultadosCampanas({ ...ahora, ahora: hoy });
    const ant = resultadosCampanas({ ...antes, ahora: hoy });
    return {
      periodo: { desde: sinceMs, hasta: untilMs },
      muestraMin: MUESTRA_MIN,
      campanas: res.campanas,
      resumen: { total: res.campanas.length, personasUnicas: res.personasUnicas, lograronUnicas: res.lograronUnicas, sinMedir: res.sinMedir },
      comparacion: { anterior: ant.personasUnicas, ...compararPeriodos(res.personasUnicas, ant.personasUnicas) },
      destacados: destacadosCampanas(res.campanas),
      flujos: ahora.flujos.map((f) => ({ id: f.id, name: f.name, canal: f.canal, enabled: f.enabled })),
      definiciones: ahora.defs.map((d) => ({ id: d.id, flowIds: d.flowIds })),
    };
  });
  app.get("/admin/api/campanas/mapa", async (req, reply) => {
    if (!(await guard(req, reply))) return;
    const id = String((req.query as Record<string, string>)?.id || "");
    const { sinceMs, untilMs } = ventanaCampanas(req);
    const ctx = await cargarCampanas(sinceMs, untilMs);
    const mapa = mapaDeCampana({ id, ...ctx, ahora: Date.now() });
    if (!mapa) return reply.code(404).send({ error: "Esa campaña ya no existe." });
    return { periodo: { desde: sinceMs, hasta: untilMs }, muestraMin: MUESTRA_MIN, mapa };
  });
  app.post("/admin/api/campanas", async (req, reply) => {
    if (!(await guard(req, reply))) return;
    const actorCampana = await wsMembership(req, currentWorkspaceId());
    if (actorCampana?.kind === "user" && actorCampana.role === "viewer") return reply.code(403).send({ error: "Tu rol no permite cambiar campañas." });
    const flows = await listFlows();
    const s = sanearCampana(json(req) ?? {}, new Set(flows.map((f) => f.id)));
    if (!s.ok) return reply.code(400).send({ error: s.error });
    return { ok: true, campana: await dbCampanaGuardar(s.v) };
  });
  app.post("/admin/api/campanas/borrar", async (req, reply) => {
    if (!(await guard(req, reply))) return;
    const actorCampana = await wsMembership(req, currentWorkspaceId());
    if (actorCampana?.kind === "user" && actorCampana.role === "viewer") return reply.code(403).send({ error: "Tu rol no permite cambiar campañas." });
    const id = String((json(req) ?? {}).id || "");
    if (!id) return reply.code(400).send({ error: "Falta indicar qué campaña quitar." });
    return { ok: await dbCampanaBorrar(id) };
  });

  // --- Flows (flow builder) ---
  // Lista de flujos. Con ?breve=1 vienen SIN los nodos (id, nombre, si está
  // activo, su disparador y cuántos pasos tiene): sirve para contar, buscar o
  // listar sin arrastrar el diseño entero de cada flujo. La lista completa
  // pesa ~110 KB y quien solo quiere contar no la necesita.
  app.get("/admin/api/flows", async (req, reply) => {
    if (!(await guard(req, reply))) return;
    const flows = await listFlows();
    const q = req.query as Record<string, string> | undefined;
    if (q?.breve === "1") {
      // Los totales VIENEN CONTADOS. Un modelo de lenguaje tallando treinta
      // elementos a mano se equivoca (dijo 24 y 25 habiendo 26): la cuenta la
      // hace quien tiene los datos, y él solo la lee.
      return {
        total: flows.length,
        activos: flows.filter((f) => f.enabled).length,
        apagados: flows.filter((f) => !f.enabled).length,
        flows: flows.map((f) => ({
          id: f.id,
          name: f.name,
          enabled: f.enabled,
          trigger: f.trigger,
          start: f.start,
          pasos: Object.keys(f.nodes || {}).length,
          creado: f.createdAt ?? null,
          cambiado: f.updatedAt ?? null,
        })),
      };
    }
    // AVANCE-FLUJO-1 · cuánta gente hay AHORA dentro de cada flujo (en curso o esperando),
    // para que la lista muestre el avance sin tener que abrir el registro de cada uno.
    let dentro: Record<string, number> = {};
    try { dentro = Object.fromEntries(await dbFlowsDentroAhora()); } catch { /* la lista funciona igual sin el contador */ }
    return { flows, dentro };
  });
  // UN flujo entero por su id, con sus nodos. Es lo que hay que leer para
  // duplicarlo, o para imitar su forma al crear otro: pedir la lista completa
  // para quedarse con uno era traer 110 KB a por 1 KB, y el resultado llegaba
  // recortado (por eso el Asistente daba vueltas sin poder duplicar nada).
  app.get("/admin/api/flows/:id", async (req, reply) => {
    if (!(await guard(req, reply))) return;
    const { id } = req.params as { id: string };
    const flow = (await listFlows()).find((f) => f.id === id);
    if (!flow) return reply.code(404).send({ error: "no existe ningún flujo con ese id" });
    return { flow };
  });
  // ── Adjuntos de pasos de flujo ─────────────────────────────────────────
  // El POST guarda el archivo (guardado, con sesión); el GET lo sirve SIN
  // sesión porque quien lo descarga es Meta (IG/FB bajan la URL al enviar).
  // Control de acceso del GET: la entropía del id (UUID v4) y que SOLO sirve
  // filas source='flow' — un adjunto de la Bandeja no se puede pedir por aquí.
  app.post("/admin/api/flow-media", async (req, reply) => {
    if (!(await guard(req, reply))) return;
    const b = json(req) ?? {};
    const nombre = String(b.name || "archivo").slice(0, 180);
    const mime = String(b.mime || "application/octet-stream").slice(0, 120);
    const dataB64 = String(b.dataB64 || "");
    if (!dataB64) return reply.code(400).send({ error: "falta el archivo" });
    let buf: Buffer;
    try { buf = Buffer.from(dataB64, "base64"); } catch { return reply.code(400).send({ error: "el archivo no se pudo leer" }); }
    if (!buf.length) return reply.code(400).send({ error: "el archivo está vacío" });
    if (buf.length > 15 * 1024 * 1024) return reply.code(400).send({ error: "máximo 15 MB por adjunto — un vídeo largo, mejor como enlace" });
    // MEDIA-FLUJO-1 · Solo formatos que WhatsApp entrega de verdad. Antes un WebM o un
    // WAV se guardaba sin queja y Meta lo rechazaba AL ENVIAR, días después, con el
    // fallo enterrado en Actividad. Mejor decirlo al subirlo y con la alternativa.
    // NOTA-DE-VOZ-1 · 'audio/mp3' no es el MIME oficial (algunos navegadores lo emiten):
    // se normaliza a 'audio/mpeg', que es el que Meta declara para .mp3.
    const mm = mime.toLowerCase() === "audio/mp3" ? "audio/mpeg" : mime.toLowerCase();
    if (mm.startsWith("video/") && mm !== "video/mp4" && mm !== "video/3gpp")
      return reply.code(400).send({ error: "WhatsApp no acepta ese formato de vídeo. Guárdalo como MP4 y vuelve a subirlo." });
    if (mm.startsWith("audio/") && !["audio/aac", "audio/mp4", "audio/mpeg", "audio/amr", "audio/ogg"].includes(mm))
      return reply.code(400).send({ error: "WhatsApp no acepta ese formato de audio. Usa MP3, M4A u OGG y vuelve a subirlo." });
    // NOTA-DE-VOZ-1 · Meta solo acepta OGG con códec OPUS («base audio/ogg not
    // supported»): un OGG-Vorbis pasaría la subida y el envío fallaría días después.
    // El códec se ve en la cabecera del contenedor (página inicial 'OpusHead').
    if (mm === "audio/ogg" && !buf.subarray(0, 512).includes("OpusHead"))
      return reply.code(400).send({ error: "Ese OGG no vale como nota de voz (WhatsApp exige códec Opus). Expórtalo como OGG-Opus, o súbelo en MP3 o M4A como audio normal." });
    if (mm === "image/gif")
      return reply.code(400).send({ error: "WhatsApp no reproduce los GIF como imagen. Guárdalo como vídeo MP4 y se verá animado." });
    if (mm.startsWith("image/") && mm !== "image/webp" && mm !== "image/jpeg" && mm !== "image/png")
      return reply.code(400).send({ error: "Para fotos, WhatsApp acepta JPG o PNG. Convierte la imagen y vuelve a subirla." });
    if (mm.startsWith("image/") && mm !== "image/webp" && buf.length > 5 * 1024 * 1024)
      return reply.code(400).send({ error: "Una foto puede pesar 5 MB como máximo en WhatsApp. Comprímela y vuelve a subirla." });
    if (mm === "image/webp" && buf.length > 100 * 1024)
      return reply.code(400).send({ error: "Un sticker (WebP) puede pesar 100 KB como máximo. Si es una foto normal, guárdala como JPG o PNG." });
    // ADJUNTO-PUBLICO-1 · lista cerrada: lo que no es imagen, vídeo o audio tiene que ser un
    // documento de los que WhatsApp entrega. Un text/html o un SVG ya no se guardan.
    if (!/^(image|video|audio)\//.test(mm) && !DOCUMENTOS_WA.has(mm))
      return reply.code(400).send({ error: "Ese tipo de archivo no se puede enviar por WhatsApp. Vale PDF, Word, Excel, PowerPoint o texto plano." });
    // NOTA-DE-VOZ-1 · se guarda el MIME normalizado: es el que viaja a Meta al enviar.
    const kind = inboxMediaKind(mm);
    const id = crypto.randomUUID();
    await dbPutInboxMedia({ id, user_id: "", source: "flow", kind, content_type: mm, data: buf });
    return { ok: true, id, kind, bytes: buf.length, nombre };
  });
  app.get("/admin/api/flow-media/:id", async (req, reply) => {
    const id = String((req.params as { id?: string }).id || "");
    const row = id ? await dbGetFlowMedia(id) : null;
    if (!row || !row.data) return reply.code(404).type("text/plain").send("no encontrado");
    // ADJUNTO-PUBLICO-1 · nosniff + sandbox: nunca se interpreta como página del panel.
    return cabecerasAdjuntoPublico(reply, row.content_type, 3600).send(row.data);
  });

  // Crear o EDITAR un flujo (es un upsert: body.id existente SOBRESCRIBE ese
  // flujo — para crear uno nuevo, NO mandes id). Body: {name (obligatorio),
  // trigger:{type,keyword,...}, nodes:{...}, start, enabled} — sin enabled:true
  // nace apagado. La forma de nodes/trigger: mira el tipo Flow en flows.ts.
  // DUPLICAR un flujo: se copia entero y la copia nace APAGADA, con «(copia)»
  // en el nombre. Existe porque copiar obligaba a reescribir el flujo entero
  // en la petición —cientos de líneas— y eso, viniendo del Asistente, tardaba
  // 40 s y llegaba truncado. Aquí el trabajo lo hace quien ya tiene los datos.
  // Body opcional: {name} para ponerle otro nombre a la copia.
  app.post("/admin/api/flows/:id/duplicar", async (req, reply) => {
    if (!(await guard(req, reply))) return;
    const { id } = req.params as { id: string };
    const orig = (await listFlows()).find((f) => f.id === id);
    if (!orig) return reply.code(404).send({ error: "no existe ningún flujo con ese id" });
    const b = (json(req) ?? {}) as { name?: string };
    const copia = JSON.parse(JSON.stringify(orig)) as Flow;
    copia.id = crypto.randomUUID();
    copia.name = String(b.name || orig.name + " (copia)").slice(0, 200);
    copia.enabled = false;
    await saveFlow(copia);
    return { ok: true, id: copia.id, name: copia.name, enabled: false, pasos: Object.keys(copia.nodes || {}).length };
  });
  // CONVERSOR Disparadores → Flujos. Sin cuerpo (o {simulacion:true}) = INFORME de lo
  // que haría, sin tocar nada. Con {simulacion:false} lo hace de verdad: crea los flujos
  // PAUSADOS, hereda las marcas de «una vez por persona» y deja cada disparador original
  // pausado y marcado — nunca borrado, para poder volver atrás.
  // GET = INFORME de lo que se convertiría, sin tocar nada. Es de solo lectura y por
  // eso es un GET: el cliente vacía su caché entera con cualquier método que no lo sea,
  // y este informe se pide al entrar en Flujos.
  app.get("/admin/api/convertir-disparadores", async (req, reply) => {
    if (!(await guard(req, reply))) return;
    return { ok: true, ...(await convertirDisparadores(true)) };
  });
  // POST = hacerlo de verdad.
  app.post("/admin/api/convertir-disparadores", async (req, reply) => {
    if (!(await guard(req, reply))) return;
    const b = json(req) as { simulacion?: boolean };
    const simulacion = b?.simulacion !== false;
    const inf = await convertirDisparadores(simulacion);
    if (!simulacion) {
      await logActivity({
        source: "app",
        level: "info",
        summary: "Disparadores convertidos a Flujos: " + inf.convertidos + " de " + inf.total,
        payload: { convertidos: inf.convertidos, sinDestino: inf.sinDestino, yaMigrados: inf.yaMigrados },
      });
    }
    return { ok: true, ...inf };
  });
  // Deshacer la conversión de UNO: reactiva el disparador y le quita la marca. El flujo
  // creado se borra por su camino normal, desde Flujos.
  app.post("/admin/api/convertir-disparadores/deshacer/:id", async (req, reply) => {
    if (!(await guard(req, reply))) return;
    const id = String((req.params as { id: string }).id || "");
    const ok = await deshacerConversion(id);
    if (!ok) return reply.code(404).send({ error: "ese disparador ya no está" });
    return { ok: true };
  });
  // T03-CORREOS · Catálogo unificado de correos de UNA cuenta web (newsletter,
  // campaña, workflow, regla, envío — la procedencia es un atributo). Sirve al
  // selector del disparador «Correos»: búsqueda, filtros y paginación se hacen
  // AQUÍ (el cliente no descarga el catálogo entero). La cuenta se resuelve
  // dentro del workspace del guard: un accountId de otro workspace (o
  // inexistente) responde el MISMO 404.
  app.get("/admin/api/email-catalog", async (req, reply) => {
    if (!(await guard(req, reply))) return;
    const q = req.query as Record<string, string>;
    const accId = String(q.acc || "").trim();
    if (!accId) return reply.code(400).send({ error: "acc requerido" });
    const { getEmailCatalogOrStatus, filterCatalog } = await import("./email-catalog.js");
    // El PRIMER barrido de una cuenta puede tardar más que el timeout del
    // navegador (bridge de workflows): si no llega en ~8 s se responde
    // {building:true} y la UI enseña «preparando…» y re-pregunta — sin errores.
    const st = await getEmailCatalogOrStatus(accId, { refresh: q.refresh === "1", waitMs: 8000 });
    if (!st) return reply.code(404).send({ error: "cuenta no encontrada" });
    if (st.status === "building") return { ok: true, building: true };
    const cat = st.cat;
    const page = filterCatalog(cat, {
      q: q.q || "",
      type: q.type || "",
      status: q.status || "",
      offset: Number(q.offset) || 0,
      limit: Number(q.limit) || 60,
    });
    const acc = await siGetAccount(accId);
    return {
      ok: true,
      items: page.items,
      total: page.total,
      truncated: cat.truncated,
      partial: cat.partial,
      pending: cat.pending,
      capabilities: cat.capabilities,
      fetchedAt: cat.fetchedAt,
      account: acc ? { id: acc.id, label: acc.label || acc.accountEmail || acc.id, sandbox: (acc.panelBaseUrl || "").includes("leadmatch-lab") } : null,
      // Para la ayuda del editor: la URL que hay que registrar en la pantalla
      // «Crear Webhook» de la web (con la cuenta EXACTA — así la ingesta nunca
      // adivina). La clave no viaja aquí: se pega desde Conexiones.
      webhook: { configured: !!getSetting("systemeio.webhook.key"), path: "/webhook/systemeio?acc=" + encodeURIComponent(accId) + "&k=<clave del webhook>" },
    };
  });
  // T03-CORREOS · Crea la etiqueta puente EN LA WEB sin salir del editor
  // (regla de la casa: las dependencias se crean inline, jamás «ve a X y
  // vuelve»). Requiere API key en la cuenta; ensureTagId reusa la etiqueta si
  // ya existe y explica el tope del plan si systeme.io lo devuelve.
  app.post("/admin/api/email-catalog/ensure-tag", async (req, reply) => {
    if (!(await guard(req, reply))) return;
    const b = json(req) as { acc?: string; name?: string };
    const name = String(b?.name || "").trim().slice(0, 120);
    if (!name) return reply.code(400).send({ error: "Escribe el nombre de la etiqueta" });
    const acc = await siGetAccount(String(b?.acc || "").trim());
    if (!acc) return reply.code(404).send({ error: "cuenta no encontrada" });
    if (!acc.apiKey) return reply.code(400).send({ error: "Esta cuenta no tiene API key: crea la etiqueta en tu web o pega la clave en Conexiones" });
    try {
      const { ensureTagId, withPublicApiKey } = await import("./systemeio-public-api.js");
      await withPublicApiKey(acc.apiKey, () => ensureTagId(name, true));
      return { ok: true, name };
    } catch (e) {
      return reply.code(502).send({ error: String((e as Error).message || "no se pudo crear la etiqueta").slice(0, 240) });
    }
  });

  // ============================================================
  // NEWSLETTER-1 · Boletines de correo.
  //
  // Nuestra fila guarda el borrador (instrucción de la IA, contactos sueltos,
  // de qué negocio es); la web conectada es quien envía de verdad. Todo lo que
  // sale de aquí pasa por `newsletter.ts`, que es donde vive esa costura.
  // ============================================================

  /** Quién firma la fila. Mismo patrón que las difusiones (resolveActor). */
  const nlActor = async (req: FastifyRequest): Promise<string> => {
    const a = await resolveActor(req);
    return a ? (a.kind === "env" ? a.email : a.user.email) : "";
  };

  /** Aplica al registro los campos que manda el panel, ya saneados.
   *  Se hace en UN sitio porque lo usan el POST de guardar y el de enviar:
   *  con la regla duplicada, enviar se saltaría validaciones que guardar sí hace. */
  const nlAplicaCampos = (rec: NewsletterRec, b: Record<string, unknown>): void => {
    const { normalizaCorreos, normalizaEtiquetas, limpiaHtml } = nlMod;
    if (b.accountId !== undefined) rec.account_id = String(b.accountId || "").trim().slice(0, 60);
    if (b.subject !== undefined) rec.subject = String(b.subject || "").trim().slice(0, 255);
    if (b.previewText !== undefined) rec.preview_text = String(b.previewText || "").trim().slice(0, 140);
    if (b.bodyHtml !== undefined) rec.body_html = limpiaHtml(String(b.bodyHtml || "")).slice(0, 200000);
    if (b.senderName !== undefined) rec.sender_name = String(b.senderName || "").trim().slice(0, 120);
    if (b.senderEmail !== undefined) rec.sender_email = String(b.senderEmail || "").trim().toLowerCase().slice(0, 190);
    if (b.prompt !== undefined) rec.prompt = String(b.prompt || "").trim().slice(0, 4000);
    if (b.includeTags !== undefined) rec.include_tags = normalizaEtiquetas(b.includeTags).slice(0, 40);
    if (b.excludeTags !== undefined) rec.exclude_tags = normalizaEtiquetas(b.excludeTags).slice(0, 40);
    if (b.contacts !== undefined) rec.contacts = normalizaCorreos(b.contacts).slice(0, 500);
    if (b.scheduledAt !== undefined) {
      const n = Number(b.scheduledAt);
      rec.scheduled_at = Number.isFinite(n) && n > 0 ? n : null;
    }
  };

  // ---- Listado (lee SOLO nuestra tabla: sin llamadas externas ni coste) ----
  app.get("/admin/api/newsletters", async (req, reply) => {
    if (!(await guard(req, reply))) return;
    try {
      const rows = await dbListNewsletters();
      // Las webs conectadas viajan AQUÍ y no se piden a Conexiones: sus rutas
      // son de la vista 'connections', así que a quien solo tenga Newsletter
      // concedida el selector de cuenta le respondería 403 y la sección
      // quedaría inservible (le pasó a Pipeline con la lista de contactos).
      const cuentas = (await siListAccounts()).map((a) => ({
        id: a.id,
        label: a.label || a.accountEmail || a.panelBaseUrl,
        listo: a.hasApiKey, // sin clave no se puede enviar: el panel lo avisa
      }));
      return { ok: true, items: rows, cuentas };
    } catch (e) {
      return reply.code(500).send({ error: String((e as Error).message || "no se pudo leer el listado").slice(0, 240) });
    }
  });

  // ---- Crear / actualizar borrador ---------------------------------------
  app.post("/admin/api/newsletters", async (req, reply) => {
    if (!(await guard(req, reply))) return;
    const b = (json(req) || {}) as Record<string, unknown>;
    const id = String(b.id || "").trim();
    try {
      let rec: NewsletterRec;
      if (id) {
        const prev = await dbGetNewsletter(id);
        if (!prev) return reply.code(404).send({ error: "Ese boletín no existe en este negocio" });
        // Un boletín ya enviado no se reescribe: su fila es el histórico de lo
        // que recibió la gente. Para cambiarlo, se duplica.
        if (prev.status === "sent") {
          return reply.code(409).send({ error: "Ese boletín ya se envió: duplícalo para escribir uno nuevo" });
        }
        if (prev.status === "sending") {
          return reply.code(409).send({ error: "Ese boletín se está enviando ahora mismo" });
        }
        rec = prev;
      } else {
        rec = nlMod.newsletterVacio(await nlActor(req));
      }
      nlAplicaCampos(rec, b);

      // Programar o volver a borrador. La fecha REAL la fija la web; aquí solo
      // se decide el estado y se sincroniza para que las dos coincidan.
      const accion = String(b.action || "save");
      if (accion === "schedule") {
        const r = await nlMod.publicarEnWeb(rec, "programar");
        rec.status = "scheduled";
        rec.recipients = r.destinatarios;
        rec.result = "";
      } else if (accion === "unschedule") {
        await nlMod.desprogramarEnWeb(rec).catch(() => {});
        rec.status = "draft";
        rec.scheduled_at = null;
      } else if (rec.status === "scheduled" || rec.status === "error") {
        // Editar un boletín programado lo devuelve a borrador Y retira la fecha
        // de la web: si no, saldría el texto viejo a la hora vieja.
        await nlMod.desprogramarEnWeb(rec).catch(() => {});
        rec.status = "draft";
      }

      try {
        await dbUpsertNewsletter(rec);
      } catch (e) {
        // La web ya lo tenía programado y aquí no quedó constancia: saldría a su
        // hora sin que el panel lo supiera ni nadie pudiera cancelarlo desde aquí.
        // Se retira la programación de la web para que las dos vuelvan a coincidir
        // y se cuenta el fallo tal cual.
        if (accion === "schedule") await nlMod.desprogramarEnWeb(rec).catch(() => {});
        throw e;
      }
      if (accion === "schedule") {
        await logActivity({
          source: "newsletter",
          level: "info",
          status: "scheduled",
          summary: `Boletín programado: ${rec.subject}`,
          payload: { newsletter: rec.id, cuando: rec.scheduled_at, destinatarios: rec.recipients },
        });
      }
      return { ok: true, item: rec };
    } catch (e) {
      return reply.code(400).send({ error: String((e as Error).message || "no se pudo guardar").slice(0, 300) });
    }
  });

  // ---- Borrar (también en la web: si no, seguiría programado allí) --------
  app.delete("/admin/api/newsletters/:id", async (req, reply) => {
    if (!(await guard(req, reply))) return;
    const id = String((req.params as { id?: string })?.id || "").trim();
    const rec = await dbGetNewsletter(id);
    if (!rec) return reply.code(404).send({ error: "Ese boletín no existe en este negocio" });
    if (rec.status === "sending") {
      return reply.code(409).send({ error: "Ese boletín se está enviando ahora mismo: espera a que termine" });
    }
    let aviso = "";
    try {
      await nlMod.borrarEnWeb(rec);
    } catch (e) {
      const motivo = nlMod.motivoLegible(e).slice(0, 200);
      // PROGRAMADO y la web no lo soltó: si se borrara aquí, saldría a su hora sin
      // que nadie lo viera en el panel. Se deja donde está y se dice por qué.
      if (rec.status === "scheduled") {
        return reply.code(409).send({
          error: `No se pudo retirar de tu web y sigue programado allí (${motivo}). Cancela la programación o revisa la conexión y vuelve a intentarlo.`,
        });
      }
      // Un borrador o un error: la copia suelta de la web no envía nada. Se dice,
      // no se oculta, pero no bloquea el borrado.
      aviso = motivo;
    }
    await dbDeleteNewsletter(id);
    return { ok: true, aviso };
  });

  // ---- Redactar con IA ----------------------------------------------------
  app.post("/admin/api/newsletters/ai", async (req, reply) => {
    if (!(await guard(req, reply))) return;
    const b = (json(req) || {}) as Record<string, unknown>;
    const prompt = String(b.prompt || "").trim().slice(0, 4000);
    if (!prompt) return reply.code(400).send({ error: "Escribe qué quieres contar en el boletín" });
    try {
      const borrador = await nlMod.redactarConIA(prompt, {
        negocio: String(b.negocio || "").slice(0, 120),
        tono: String(b.tono || "").slice(0, 60),
        idioma: String(b.idioma || "").slice(0, 40),
        firmante: String(b.firmante || "").slice(0, 120),
        modelo: nlMod.modeloRedaccion(b.modelo),
        ...(b.firma ? { firma: nlMod.normalizaFirma(b.firma) } : {}),
      });
      await logActivity({
        source: "newsletter",
        level: "info",
        summary: `Boletín redactado con IA: ${borrador.subject}`,
        payload: { prompt: prompt.slice(0, 200) },
      });
      return { ok: true, ...borrador };
    } catch (e) {
      return reply.code(502).send({ error: String((e as Error).message || "la IA no pudo redactarlo").slice(0, 300) });
    }
  });

  // ---- Audiencia: etiquetas de la web con cuánta gente tiene cada una -----
  app.get("/admin/api/newsletters/audience", async (req, reply) => {
    if (!(await guard(req, reply))) return;
    const q = (req.query || {}) as { acc?: string; conteo?: string };
    try {
      const tags = await nlMod.audienciaDeCuenta(String(q.acc || "").trim(), {
        conConteo: q.conteo !== "0",
      });
      return { ok: true, tags };
    } catch (e) {
      return reply.code(502).send({ error: String((e as Error).message || "no se pudieron leer las etiquetas").slice(0, 300) });
    }
  });

  // ---- Prueba a un solo correo -------------------------------------------
  app.post("/admin/api/newsletters/:id/test", async (req, reply) => {
    if (!(await guard(req, reply))) return;
    const id = String((req.params as { id?: string })?.id || "").trim();
    const b = (json(req) || {}) as Record<string, unknown>;
    const rec = await dbGetNewsletter(id);
    if (!rec) return reply.code(404).send({ error: "Ese boletín no existe en este negocio" });
    try {
      await nlMod.enviarPrueba(rec, String(b.email || ""));
      await dbUpsertNewsletter(rec); // enviarPrueba fija sio_id la primera vez
      return { ok: true };
    } catch (e) {
      return reply.code(502).send({ error: String((e as Error).message || "no se pudo enviar la prueba").slice(0, 300) });
    }
  });

  // ---- Enviar AHORA -------------------------------------------------------
  // NEWSLETTER-RUTINA-1 · etapa 3: «¿quién lo recibió, lo abrió y clicó?». Las
  // estadísticas por persona de la web van por su mailing_id, que es OTRA
  // numeración que sio_id (db.ts, columna mailing_id). Se resuelve la primera vez
  // casando por asunto en la ventana de la fecha de envío —igual que
  // getMailingStatsInternal— y se guarda para no volver a buscarlo.
  app.get("/admin/api/newsletters/:id/mailing", async (req, reply) => {
    if (!(await guard(req, reply))) return;
    const id = String((req.params as { id?: string })?.id || "").trim();
    const rec = await dbGetNewsletter(id);
    if (!rec) return reply.code(404).send({ error: "Ese correo no existe en este negocio" });
    if (rec.status !== "sent" || !rec.sent_at) return reply.code(409).send({ error: "Este correo todavía no ha salido" });
    if (rec.mailing_id > 0) return { ok: true, mailing_id: rec.mailing_id, acc: rec.account_id, subject: rec.subject, scheduledAt: new Date(rec.sent_at).toISOString() };
    // SIN-ESTADISTICAS-1 · salió como envío de prueba uno a uno (la web no dejó crear
    // la etiqueta puente): la web no lo registra en sus estadísticas y NUNCA lo hará.
    // Los anteriores al arreglo no llevan el aviso: sin etiquetas y con más de 1 h.
    const unoAUno = rec.result === nlMod.AVISO_UNO_A_UNO
      || (!rec.include_tags.length && Date.now() - rec.sent_at > 3600_000);
    const acc = await siGetAccount(rec.account_id);
    if (!acc) return { ok: false, error: "La web desde la que salió ya no está conectada" };
    const iso = (d: Date): string => d.toISOString().slice(0, 19);
    const dateFrom = iso(new Date(rec.sent_at - 36 * 3600_000));
    const dateTo = iso(new Date(rec.sent_at + 36 * 3600_000));
    let emails: Array<{ mailingId: number; subject: string; scheduledAt: string | null }> = [];
    {
      const m = await fetchSystemeioEmailStats(acc.id, dateFrom, dateTo).catch(() => null);
      if (m && m.emails && m.emails.length) emails = m.emails as typeof emails;
    }
    const mid = rutMod.eligeMailing(emails, rec.subject, rec.sent_at);
    if (!mid) {
      if (unoAUno) return { ok: false, directo: true, error: nlMod.AVISO_UNO_A_UNO };
      return { ok: false, error: emails.length ? "Tu web todavía no muestra este correo en sus estadísticas. Suele tardar unos minutos tras el envío." : "No se pudieron leer las estadísticas de tu web. Vuelve a intentarlo en un momento." };
    }
    rec.mailing_id = mid;
    await dbUpsertNewsletter(rec);
    return { ok: true, mailing_id: rec.mailing_id, acc: rec.account_id, subject: rec.subject, scheduledAt: new Date(rec.sent_at).toISOString() };
  });

  app.post("/admin/api/newsletters/:id/send", async (req, reply) => {
    if (!(await guard(req, reply))) return;
    const id = String((req.params as { id?: string })?.id || "").trim();
    const rec = await dbGetNewsletter(id);
    if (!rec) return reply.code(404).send({ error: "Ese boletín no existe en este negocio" });
    if (rec.status === "sent") return reply.code(409).send({ error: "Ese boletín ya se envió" });
    if (rec.status === "sending") return reply.code(409).send({ error: "Ese boletín ya se está enviando" });
    // Se marca 'sending' ANTES de llamar a la web: si el proceso muere a mitad,
    // el barrido lo cierra como error en vez de reintentarlo a ciegas — que es
    // como se duplica un boletín en la bandeja de todo el mundo.
    rec.status = "sending";
    await dbUpsertNewsletter(rec);
    try {
      const r = await nlMod.publicarEnWeb(rec, "enviar");
      rec.status = "sent";
      rec.sent_at = Date.now();
      rec.recipients = r.destinatarios;
      rec.result = r.aviso || "Enviado desde el panel";
      await dbUpsertNewsletter(rec);
      await logActivity({
        source: "newsletter",
        level: "info",
        status: "sent",
        summary: `Boletín enviado: ${rec.subject}`,
        payload: { newsletter: rec.id, destinatarios: r.destinatarios },
      });
      return { ok: true, item: rec, destinatarios: r.destinatarios };
    } catch (e) {
      rec.status = "error";
      rec.result = nlMod.motivoLegible(e);
      await dbUpsertNewsletter(rec);
      await logActivity({
        source: "newsletter",
        level: "error",
        status: "error",
        summary: `No se pudo enviar el boletín «${rec.subject}»`,
        payload: { newsletter: rec.id, error: rec.result },
      });
      return reply.code(502).send({ error: rec.result.slice(0, 300), item: rec });
    }
  });

  // ============================================================
  // NEWSLETTER-RUTINA-1 · Rutinas de correo.
  //
  // Una rutina es un encargo a la IA que se repite (como las rutinas de
  // Claude Code): cada ejecución redacta un correo NUEVO y lo envía desde la
  // web. El motor vive en newsletter-rutinas.ts y el latido en scheduler.ts;
  // aquí solo se guarda, se enciende/apaga y se consulta.
  // ============================================================

  /** Lo que el panel necesita pintar de una rutina: la fila y su frase. */
  const rutParaPanel = (r: NewsletterRoutineRec) => ({ ...r, resumen: rutMod.describeRecurrencia(r) });

  /** Aplica los campos del panel ya saneados. Un solo sitio para crear y editar. */
  const rutAplicaCampos = (r: NewsletterRoutineRec, b: Record<string, unknown>): void => {
    const { normalizaCorreos, normalizaEtiquetas } = nlMod;
    const ent = (v: unknown, min: number, max: number, def: number): number => {
      const n = Math.trunc(Number(v));
      return Number.isFinite(n) && n >= min && n <= max ? n : def;
    };
    if (b.name !== undefined) r.name = String(b.name || "").trim().slice(0, 120);
    if (b.accountId !== undefined) r.account_id = String(b.accountId || "").trim().slice(0, 60);
    if (b.prompt !== undefined) r.prompt = String(b.prompt || "").trim().slice(0, 4000);
    if (b.senderName !== undefined) r.sender_name = String(b.senderName || "").trim().slice(0, 120);
    if (b.senderEmail !== undefined) r.sender_email = String(b.senderEmail || "").trim().toLowerCase().slice(0, 190);
    if (b.includeTags !== undefined) r.include_tags = normalizaEtiquetas(b.includeTags).slice(0, 40);
    if (b.excludeTags !== undefined) r.exclude_tags = normalizaEtiquetas(b.excludeTags).slice(0, 40);
    if (b.contacts !== undefined) r.contacts = normalizaCorreos(b.contacts).slice(0, 500);
    if (b.freq !== undefined) {
      const f = String(b.freq);
      r.freq = f === "daily" || f === "monthly" ? f : "weekly";
    }
    if (b.weekdays !== undefined) {
      const arr = Array.isArray(b.weekdays) ? b.weekdays : [];
      r.weekdays = [...new Set(arr.map((x) => Math.trunc(Number(x))).filter((x) => x >= 0 && x <= 6))].sort();
    }
    if (b.monthday !== undefined) r.monthday = ent(b.monthday, 1, 28, 1);
    if (b.atHour !== undefined) r.at_hour = ent(b.atHour, 0, 23, 9);
    if (b.atMin !== undefined) r.at_min = ent(b.atMin, 0, 59, 0);
    if (b.aiModel !== undefined) r.ai_model = nlMod.modeloRedaccion(b.aiModel);
    if (b.signature !== undefined) r.signature = nlMod.normalizaFirma(b.signature);
    if (b.tz !== undefined) {
      const tz = String(b.tz || "").trim();
      r.tz = rutMod.zonaValida(tz) ? tz : "Europe/Madrid";
    }
    // Sin nombre, el listado enseñaría una tarjeta muda: se toma el principio del encargo.
    if (!r.name && r.prompt) r.name = r.prompt.replace(/\s+/g, " ").slice(0, 60);
  };

  /** Encender exige que la rutina esté completa; apagar, nada. Fija next_run_at. */
  const rutFijaEstado = (r: NewsletterRoutineRec, activa: boolean): string | null => {
    if (activa) {
      const motivo = rutMod.motivoNoActivable(r);
      if (motivo) return motivo;
      r.active = true;
      r.next_run_at = rutMod.proximaEjecucion(r);
    } else {
      r.active = false;
      r.next_run_at = null;
    }
    return null;
  };

  // ---- Listado de rutinas ---------------------------------------------------
  app.get("/admin/api/newsletters/routines", async (req, reply) => {
    if (!(await guard(req, reply))) return;
    try {
      const rows = await dbListNewsletterRoutines();
      const cuentas = (await siListAccounts()).map((a) => ({
        id: a.id,
        label: a.label || a.accountEmail || a.panelBaseUrl,
        listo: a.hasApiKey,
      }));
      return { ok: true, items: rows.map(rutParaPanel), cuentas };
    } catch (e) {
      return reply.code(500).send({ error: String((e as Error).message || "no se pudieron leer las rutinas").slice(0, 240) });
    }
  });

  // ---- Crear / editar -------------------------------------------------------
  app.post("/admin/api/newsletters/routines", async (req, reply) => {
    if (!(await guard(req, reply))) return;
    const b = (json(req) || {}) as Record<string, unknown>;
    const id = String(b.id || "").trim();
    try {
      let r: NewsletterRoutineRec;
      if (id) {
        // Se lee por la consulta acotada al negocio: un id de otro workspace da 404
        // y nunca llega al upsert.
        const prev = await dbGetNewsletterRoutine(id);
        if (!prev) return reply.code(404).send({ error: "Esa rutina no existe en este negocio" });
        r = prev;
      } else {
        r = rutMod.rutinaVacia(await nlActor(req));
      }
      rutAplicaCampos(r, b);
      const activa = b.active === undefined ? r.active : !!b.active;
      const motivo = rutFijaEstado(r, activa);
      if (motivo) return reply.code(400).send({ error: motivo });
      r.updated_at = Date.now();
      await dbUpsertNewsletterRoutine(r);
      return { ok: true, item: rutParaPanel(r) };
    } catch (e) {
      return reply.code(400).send({ error: String((e as Error).message || "no se pudo guardar la rutina").slice(0, 300) });
    }
  });

  // ---- Activar / pausar -----------------------------------------------------
  app.post("/admin/api/newsletters/routines/:id/active", async (req, reply) => {
    if (!(await guard(req, reply))) return;
    const id = String((req.params as { id?: string })?.id || "").trim();
    const b = (json(req) || {}) as Record<string, unknown>;
    const r = await dbGetNewsletterRoutine(id);
    if (!r) return reply.code(404).send({ error: "Esa rutina no existe en este negocio" });
    const motivo = rutFijaEstado(r, !!b.active);
    if (motivo) return reply.code(400).send({ error: motivo });
    r.updated_at = Date.now();
    await dbUpsertNewsletterRoutine(r);
    return { ok: true, item: rutParaPanel(r) };
  });

  // ---- Ejecutar ahora (no mueve la próxima ejecución programada) -------------
  app.post("/admin/api/newsletters/routines/:id/run", async (req, reply) => {
    if (!(await guard(req, reply))) return;
    const id = String((req.params as { id?: string })?.id || "").trim();
    const r = await dbGetNewsletterRoutine(id);
    if (!r) return reply.code(404).send({ error: "Esa rutina no existe en este negocio" });
    const motivo = rutMod.motivoNoActivable(r);
    if (motivo) return reply.code(400).send({ error: motivo });
    const res = await rutMod.ejecutaRutina(r, { manual: true });
    const item = await dbGetNewsletterRoutine(id);
    if (!res.ok) return reply.code(502).send({ error: res.motivo.slice(0, 300), item: item ? rutParaPanel(item) : null });
    return { ok: true, motivo: res.motivo, item: item ? rutParaPanel(item) : null };
  });

  // ---- Historial: los correos que ha mandado esta rutina ---------------------
  app.get("/admin/api/newsletters/routines/:id/history", async (req, reply) => {
    if (!(await guard(req, reply))) return;
    const id = String((req.params as { id?: string })?.id || "").trim();
    const q = (req.query || {}) as { limit?: string; offset?: string };
    const r = await dbGetNewsletterRoutine(id);
    if (!r) return reply.code(404).send({ error: "Esa rutina no existe en este negocio" });
    const limit = Math.min(100, Math.max(1, Math.trunc(Number(q.limit)) || 20));
    const offset = Math.max(0, Math.trunc(Number(q.offset)) || 0);
    const h = await dbListNewslettersDeRutina(id, limit, offset);
    return { ok: true, items: h.items, total: h.total };
  });

  // ---- Borrar (lo enviado se queda en «Enviados»: es lo que recibió la gente) -
  app.delete("/admin/api/newsletters/routines/:id", async (req, reply) => {
    if (!(await guard(req, reply))) return;
    const id = String((req.params as { id?: string })?.id || "").trim();
    const r = await dbGetNewsletterRoutine(id);
    if (!r) return reply.code(404).send({ error: "Esa rutina no existe en este negocio" });
    await dbDeleteNewsletterRoutine(id);
    return { ok: true };
  });

  // T03-CORREOS · Saneado + reglas de ACTIVACIÓN del disparador de correo.
  // Vive aparte (antes estaba embebido en el POST) porque lo aplican DOS
  // caminos: guardar desde el editor y el INTERRUPTOR-TARJETA-1 de la tarjeta.
  // Con la regla duplicada, encender desde la lista se saltaría validaciones
  // que el editor sí exige. Devuelve el mensaje para el usuario, o null si vale.
  const flowCorreoGate = async (f: Flow): Promise<string | null> => {
    if (f.trigger?.type !== "email") return null;
    const t = f.trigger;
    t.emAccountId = String(t.emAccountId || "").slice(0, 40);
    t.emEvent = t.emEvent === "clicked" ? "clicked" : "opened";
    t.emScope = ["any", "email", "origin", "type"].includes(String(t.emScope)) ? String(t.emScope) : "any";
    t.emTag = String(t.emTag || "").trim().slice(0, 120);
    t.emMailingId = String(t.emMailingId || "").replace(/[^0-9]/g, "").slice(0, 20);
    t.emIncludePast = !!t.emIncludePast;
    t.emSubject = String(t.emSubject || "").slice(0, 300);
    t.emOriginName = String(t.emOriginName || "").slice(0, 200);
    t.emOriginId = String(t.emOriginId || "").slice(0, 80);
    t.emEmailId = String(t.emEmailId || "").slice(0, 80);
    const OT = ["newsletter", "campaign", "sequence", "automation", "rule", "individual", "other"];
    t.emOriginType = OT.includes(String(t.emOriginType)) ? String(t.emOriginType) : "";
    if (!f.enabled) return null;
    if (!t.emAccountId) return "Elige la cuenta web del disparador de correo (no se activa sin cuenta)";
    const acc = await siGetAccount(t.emAccountId);
    if (!acc) return "Esa cuenta web no está conectada en este workspace";
    // DIRECTO-2 · lo normal es el seguimiento directo por el puente, que entra con el
    // correo y la contraseña de la cuenta (SIO-LIMPIEZA-1). La etiqueta es solo el
    // modo instantáneo (avanzado) o el plan B para cuentas solo-API-key.
    const puedeDirecto = !!acc.sandboxPass;
    const broadDirecto = puedeDirecto && ["any", "type", "origin"].includes(String(t.emScope));
    const directo = broadDirecto || !!(t.emMailingId && puedeDirecto);
    if (!t.emTag && !directo) {
      return !puedeDirecto
        ? "Esta cuenta está conectada solo con API key y el panel no puede leer sus aperturas: conéctala con acceso completo en Conexiones — o usa el modo instantáneo con una etiqueta"
        : "Ese correo aún no tiene envío rastreable (¿borrador o sin enviar?): elige un correo ya enviado o cambia el alcance";
    }
    if (t.emScope === "email" && !t.emEmailId) return "Elige el correo concreto, o cambia el alcance del disparador";
    if (t.emScope === "origin" && !t.emOriginId) return "Elige el origen (campaña, workflow, newsletter…), o cambia el alcance";
    if (t.emScope === "type" && !t.emOriginType) return "Elige el tipo de correo (newsletter, campaña…)";
    // CORREO ELIMINADO · verificación best-effort contra el catálogo: solo
    // bloquea si el catálogo está COMPLETO (sin fuentes caídas ni recortes)
    // y el correo ya no aparece — con el proveedor a medias, se permite
    // guardar (el disparo ya avisa si la cuenta/correo faltan).
    if (t.emScope === "email" && t.emEmailId) {
      try {
        const { getEmailCatalogOrStatus } = await import("./email-catalog.js");
        // Solo con catálogo YA listo y completo (el guardado no puede
        // quedarse colgado esperando al proveedor): best-effort honesto.
        const st2 = await getEmailCatalogOrStatus(t.emAccountId, { waitMs: 3000 });
        if (st2 && st2.status === "ready" && !st2.cat.partial.length && !st2.cat.pending.length && !st2.cat.truncated && !st2.cat.items.some((e) => e.extId === t.emEmailId)) {
          return "Ese correo ya no existe en la cuenta — elige otro en el selector";
        }
      } catch { /* proveedor caído: no bloquear el guardado */ }
    }
    return null;
  };
  // INTERRUPTOR-TARJETA-1 · Encender/pausar un flujo desde su TARJETA, sin abrir el editor
  // (era el motivo nº1 para entrar a editar). Al servidor viaja SOLO el estado:
  // el flujo lo lee y lo reescribe él, así una lista abierta hace media hora no
  // machaca con su copia vieja lo que se haya editado entre medias. Sin body,
  // alterna. Activar pasa por la MISMA puerta que el editor (flowCorreoGate).
  app.post("/admin/api/flows/:id/enabled", async (req, reply) => {
    if (!(await guard(req, reply))) return;
    const { id } = req.params as { id: string };
    const flow = (await listFlows()).find((f) => f.id === id);
    if (!flow) return reply.code(404).send({ error: "no existe ningún flujo con ese id" });
    const b = (json(req) ?? {}) as { enabled?: boolean };
    const on = typeof b.enabled === "boolean" ? b.enabled : !flow.enabled;
    if (on === !!flow.enabled) return { ok: true, id, name: flow.name, enabled: on };
    // KW-UNICA-POST-1 · dos flujos activos con la misma clave en la misma publicación: no.
    // Se mira sobre una copia: sin Postgres listFlows da los objetos vivos y mutar antes
    // dejaría encendido el flujo rechazado.
    const choque = conflictoClaveMismoPost({ ...flow, enabled: on }, await listFlows());
    if (choque) return reply.code(409).send({ error: choque });
    flow.enabled = on;
    const err = await flowCorreoGate(flow);
    if (err) return reply.code(400).send({ error: err });
    await saveFlow(flow);
    // DIRECTO-1 · un flujo de correo recién activado no espera media hora.
    if (on && flow.trigger?.type === "email") {
      void import("./email-events.js").then((m) => m.emailEventsPokeSoon()).catch(() => { /* tick regular */ });
    }
    return { ok: true, id, name: flow.name, enabled: on };
  });
  app.post("/admin/api/flows", async (req, reply) => {
    if (!(await guard(req, reply))) return;
    const f = json(req) as Flow;
    if (!f?.name) return reply.code(400).send({ error: "name requerido" });
    f.id ||= crypto.randomUUID();
    if (!f.nodes || typeof f.nodes !== "object") f.nodes = {};
    // ESPERA-HM-1 · una espera con minutos no numéricos programaría un next_run inválido
    // (NaN): se sanea aquí, en la única puerta de guardado, y el motor solo ve enteros ≥ 0.
    for (const nd of Object.values(f.nodes as Record<string, { type?: string; minutes?: unknown }>)) {
      if (nd?.type === "delay") {
        // ESPERA-SEG-1 · minutos + segundos con acarreo (61 s → 1 min 1 s), enteros ≥ 0.
        const tot = Math.max(0, Math.round((Number(nd.minutes) || 0) * 60 + (Number((nd as { seconds?: unknown }).seconds) || 0)));
        nd.minutes = Math.floor(tot / 60);
        (nd as { seconds?: number }).seconds = tot % 60;
      }
    }
    if (!f.trigger) f.trigger = { type: "wa_keyword", keyword: "" };
    // COMENTARIO-ABIERTO-1 · el par (modo, palabra clave) se guarda SIEMPRE coherente,
    // venga del panel o de una importación: «cualquier comentario» ⟺ sin clave. Si no,
    // una clave escondida haría que el flujo dijera una cosa y disparara otra.
    normalizeTriggerMatch(f.trigger);
    const gateCorreo = await flowCorreoGate(f);
    if (gateCorreo) return reply.code(400).send({ error: gateCorreo });
    // KW-UNICA-POST-1 · misma puerta para el editor, el MCP y las importaciones.
    const choqueKw = conflictoClaveMismoPost(f, await listFlows());
    if (choqueKw) return reply.code(409).send({ error: choqueKw });
    // MEDIA-SNAP-1 · copia guardada de la publicación elegida (miniatura + texto). Best-effort:
    // si la red no responde, el flujo se guarda igual y el repaso /media-snap-backfill la completa.
    try {
      const previo = (await listFlows()).find((x) => x.id === f.id) ?? null;
      await asegurarSnap(f, previo);
    } catch { /* la copia es un extra: jamás frena el guardado */ }
    // FLUJO-ID-AJENO-1 · un id que ya es de otro negocio no se pisa (UPSERT-TENANT-GUARD en
    // dbUpsertFlow): se explica en vez de salir como un 500 mudo.
    try { await saveFlow(f); } catch (e) {
      if (/id en uso/.test((e as Error).message)) return reply.code(409).send({ error: "Ese id ya lo usa otro flujo: guárdalo sin id y se creará uno nuevo" });
      throw e;
    }
    // DIRECTO-1 · un flujo de correo recién activado no espera media hora: tick
    // adelantado de la reconciliación (debounced; las puertas evitan martilleo).
    if (f.trigger?.type === "email" && f.enabled) {
      void import("./email-events.js").then((m) => m.emailEventsPokeSoon()).catch(() => { /* tick regular */ });
    }
    return { ok: true, id: f.id };
  });
  // MEDIA-SNAP-1 · repaso ÚNICO: a cada flujo con post concreto que aún no tiene copia le pide su
  // post a la red y se la guarda. Escribe con dbReescribirFlujo (NO toca updated_at: el desempate
  // entre flujos con la misma palabra clave y el «editado hace…» quedan como estaban). Con
  // ?dry=1 solo cuenta. Los que no se pueden recuperar (post borrado, historia caducada) se listan.
  app.post("/admin/api/flows/media-snap-backfill", async (req, reply) => {
    if (!(await guard(req, reply))) return;
    const dry = String((req.query as Record<string, string> | undefined)?.dry || "") === "1";
    const flows = await listFlows();
    const res = { revisados: 0, ya_tenian: 0, guardados: [] as string[], sin_acceso: [] as string[], pendientes_dry: [] as string[] };
    const cola = flows.filter((f) => flujoTienePostConcreto(f.trigger));
    res.revisados = cola.length;
    const pendientes = cola.filter((f) => {
      if (f.trigger?.mediaSnap?.id === f.trigger?.mediaId && f.trigger?.mediaSnap?.thumb) { res.ya_tenian++; return false; }
      return true;
    });
    if (dry) { res.pendientes_dry = pendientes.map((f) => f.name + " · " + f.trigger?.mediaId); return { ok: true, dry: true, ...res }; }
    for (let i = 0; i < pendientes.length; i += 4) {
      await Promise.all(pendientes.slice(i, i + 4).map(async (f) => {
        const cambio = await asegurarSnap(f, null).catch(() => false);
        const ok = cambio && (await dbReescribirFlujo(f.id, f as unknown as Record<string, unknown>));
        if (ok && !f.trigger?.mediaSnap?.perdido) res.guardados.push(f.name);
        else res.sin_acceso.push(f.name + " · " + f.trigger?.mediaId);
      }));
    }
    return { ok: true, ...res };
  });
  app.delete("/admin/api/flows/:id", async (req, reply) => {
    if (!(await guard(req, reply))) return;
    // FLUJO-ID-AJENO-1 · borrar lo que no es de este negocio (o ya no existe) no es un «ok».
    if (!(await removeFlow((req.params as { id: string }).id))) return reply.code(404).send({ error: "no existe ningún flujo con ese id" });
    return { ok: true };
  });
  app.get("/admin/api/flows/:id/stats", async (req, reply) => {
    if (!(await guard(req, reply))) return;
    return await dbFlowStats((req.params as { id: string }).id);
  });
  // SACAR A UN CONTACTO de las automatizaciones: cancela SUS recorridos de flujo (todos, o
  // solo el de flowId). El contacto queda en manos de la Bandeja (con «Atender yo» la IA
  // también calla → silencio total del bot). Creado en caliente la noche del live: un lead
  // atrapado en el «No te entendí» no tenía forma de ser silenciado desde el panel.
  app.post("/admin/api/flows/runs/cancel", async (req, reply) => {
    if (!(await guard(req, reply))) return;
    const b = json(req) ?? {};
    const phone = String(b.phone || "").trim();
    if (!phone) return reply.code(400).send({ error: "phone requerido" });
    const flowId = String(b.flowId || "").trim() || undefined;
    const cancelled = await dbCancelFlowRunsForPhone(phone, flowId);
    // PARAR-SIN-BOT · misma regla que los otros dos caminos de parada (ficha y Bandeja):
    // sacar del flujo + IA en silencio, para que parar nunca encienda la charla libre.
    await setHuman(phone, true);
    return { ok: true, stopped: cancelled.length, human: true };
  });
  // VACIAR DATOS del flujo: borra runs + registro + clics (tenant-scoped) SIN tocar el diseño.
  // Para limpiar las pruebas justo antes de un lanzamiento y medir solo gente real.
  app.post("/admin/api/flows/:id/reset", async (req, reply) => {
    if (!(await guard(req, reply))) return;
    const id = String((req.params as { id: string }).id || "");
    if (!id) return reply.code(400).send({ error: "id requerido" });
    const res = await dbResetFlowData(id);
    return { ok: true, ...res };
  });
  // PROBAR-FLUJO-1 · «Probar con un número»: arranca el flujo YA para un teléfono concreto,
  // sin esperar a que escriba la palabra clave. Sirve para ver en el propio móvil cómo
  // llega cada paso (tarjetas, imágenes, botones) antes de lanzar una campaña. Los pasos
  // de texto solo llegan si ese número tiene la ventana de 24 h abierta (regla de Meta).
  app.post("/admin/api/flows/:id/probar", async (req, reply) => {
    if (!(await guard(req, reply))) return;
    const id = String((req.params as { id: string }).id || "");
    const b = json(req) ?? {};
    const phone = String(b.phone || "").replace(/[^\d]/g, "");
    if (!id || !phone) return reply.code(400).send({ error: "Falta el número al que enviar la prueba" });
    const flow = (await listFlows()).find((f) => f.id === id);
    if (!flow) return reply.code(404).send({ error: "Ese flujo ya no existe" });
    if (!/^wa_/.test(String(flow.trigger?.type || ""))) return reply.code(400).send({ error: "Este flujo no arranca desde WhatsApp: la prueba por WhatsApp solo vale para flujos de WhatsApp" });
    // Sin ventana de 24 h abierta, WhatsApp rechaza los mensajes de texto del flujo: mejor
    // decirlo aquí que responder «enviado» y que no llegue nada.
    const ct = await findContactByPhoneLoose(phone);
    if (!ct || !inWindow(ct)) return reply.code(409).send({ error: "Ese número no ha escrito a esta cuenta en las últimas 24 horas, así que WhatsApp no deja enviarle los mensajes del flujo. Escríbele tú primero desde el móvil (o mándale una plantilla) y vuelve a probar." });
    await dbCancelFlowRunsForPhone(phone, id); // prueba limpia: sin un run anterior colgado
    // Sale por el número al que está atado el flujo (si lo hay), igual que en producción.
    const waNum = flow.appliesTo ? resolveWaNumber(String(flow.appliesTo).replace(/^wa:/, "")) : null;
    if (waNum) await runWithWaNumber({ token: waNum.token, phoneId: waNum.phoneNumberId }, () => startFlow(phone, flow, { prueba: true }));
    else await startFlow(phone, flow, { prueba: true });
    return { ok: true, phone, flow: flow.name };
  });
  // RELANZAR-FLUJO-1 · «Relanzar a este contacto»: arranca el flujo desde el primer paso para
  // un contacto que ya existe, por SU canal y cuenta (WhatsApp, Instagram o Messenger),
  // cancelando antes su run de este flujo e ignorando «una vez por persona». La lógica vive
  // en flows.ts (relanzarFlujo) para que el panel y la conexión de IA hagan exactamente lo mismo.
  app.post("/admin/api/flows/:id/relanzar", async (req, reply) => {
    if (!(await guard(req, reply))) return;
    const id = String((req.params as { id: string }).id || "");
    const b = json(req) ?? {};
    const phone = String(b.phone || "").trim().replace(/^\+/, "").replace(/\s+/g, "");
    if (!id || !phone) return reply.code(400).send({ error: "Falta el contacto al que relanzar el flujo" });
    const desde = typeof b.desde === "string" ? b.desde.trim() : "";
    const r = await relanzarFlujo(id, phone, desde || undefined);
    if (!r.ok) return reply.code(r.status || 400).send({ error: r.error });
    return { ok: true, phone, flow: r.flow, canal: r.canal, cuenta: r.cuenta, desde: r.desde, ...(r.aviso ? { aviso: r.aviso } : {}) };
  });
  // FLOW-LOGS («Ver Logs») · Registro de actividad del flujo: cada movimiento real de cada
  // contacto, con TODO en humano — etiqueta de paso legible («Mensaje · ¡Hola!…», nunca
  // "n11") y, por contacto, su estado actual («Esperando su respuesta en …»). El cliente
  // lo muestra en dos pestañas: Por contacto (historia de cada persona) y Cronología.
  app.get("/admin/api/flows/:id/events", async (req, reply) => {
    if (!(await guard(req, reply))) return;
    const id = String((req.params as { id: string }).id || "");
    const q = req.query as Record<string, string>;
    const limit = Math.min(5000, Math.max(50, Number(q.limit) || 2000));
    const flow = (await listFlows()).find((f) => f.id === id);
    // ── Etiquetas humanas de paso (misma lógica que analytics/flow-detail) ──
    const nodes = (flow?.nodes || {}) as Record<string, Record<string, unknown>>;
    const nodeLabel = (nid: string): string => {
      const n = nodes[nid];
      if (!n) return nid ? "paso antiguo (el flujo se editó)" : "";
      const t = String(n.type || "");
      const txt = (s: unknown, max = 52) => { const v = String(s || "").replace(/\s+/g, " ").trim(); return v.length > max ? v.slice(0, max) + "…" : v; };
      if (t === "message") return "Mensaje · " + (txt(n.text) || "(sin texto)");
      if (t === "ask") return "Pregunta · " + (txt(n.text) || String(n.saveAs || ""));
      if (t === "buttons") return "Opciones · " + (txt(n.text) || "");
      if (t === "follow") return "Pedir seguir (IG)";
      if (t === "delay") return "Espera " + esperaLbl(n.minutes);
      if (t === "condition") {
        const src = String(n.source || "");
        if (src === "emailOpened") return "¿Abrió el correo?";
        if (src === "hasTag") return "¿Tiene la etiqueta " + String(n.value || "") + "?";
        if (src === "linkOpened") return (n as { notPurchased?: unknown }).notPurchased ? "¿Abrió el enlace y no compró?" : "¿Abrió el enlace?";
        if (src === "purchased") return "¿Ha comprado?";
        if (src === "var") return "¿" + String(n.varName || "variable") + "?";
        return "¿Respondió?";
      }
      if (t === "action") {
        const k = String(n.kind || "");
        if (k === "notify" || n.notify) return "Avisar al responsable/closer";
        if (k === "sync" || n.syncTarget) return "Sincronizar a la web";
        if (k === "book") return "Agendar cita";
        if (k === "escalate" || n.escalate) return "Pasar a humano";
        if (k === "flow" || n.startFlow) return "Lanzar otro flujo";
        if (n.addTag) return "Etiquetar · " + String(n.addTag);
        if (n.setStage) return "Etapa · " + String(n.setStage);
        return "Acción";
      }
      if (t === "end") return "Fin del flujo";
      return t || nid;
    };
    // Posición BFS 1-based de cada paso (para «paso 5 de 132»).
    const order: string[] = [];
    {
      const seen = new Set<string>();
      const queue = [String(flow?.start || "")];
      while (queue.length) {
        const nid = queue.shift()!;
        if (!nid || seen.has(nid) || !nodes[nid]) continue;
        seen.add(nid); order.push(nid);
        const n = nodes[nid];
        for (const nx of [n.next, n.yes, n.no]) if (nx) queue.push(String(nx));
        if (Array.isArray(n.options)) for (const o of n.options) if (o && (o as { next?: string }).next) queue.push(String((o as { next?: string }).next));
      }
    }
    const posOf = new Map(order.map((nid, i) => [nid, i + 1]));
    const stepRef = (nid: string): string => {
      if (!nid) return "";
      const p = posOf.get(nid);
      return nodeLabel(nid) + (p ? " (paso " + p + " de " + order.length + ")" : "");
    };
    const [events, det] = await Promise.all([dbFlowEvents(id, limit), dbFlowDetail(id)]);
    const names = await dbGetContactsByIds([...new Set([...events.map((e) => e.phone), ...det.runs.map((r) => r.phone)])]);
    // ── Por contacto: estado ACTUAL en humano + actividad agregada de sus eventos ──
    const agg = new Map<string, { lastAt: number; nMsg: number; nResp: number; n: number; buy: boolean; err: number }>();
    for (const e of events) {
      const a = agg.get(e.phone) || { lastAt: 0, nMsg: 0, nResp: 0, n: 0, buy: false, err: 0 };
      a.n++; if (e.at > a.lastAt) a.lastAt = e.at;
      if (e.event === "mensaje") a.nMsg++;
      if (e.event === "respondió") a.nResp++;
      if (e.event.indexOf("compró") >= 0) a.buy = true;
      if (e.event === "error") a.err++;
      agg.set(e.phone, a);
    }
    const humanStatus = (st: string, nid: string, buy: boolean): { s: string; k: string } => {
      if (buy) return { s: "Salió: ya compró", k: "compró" };
      if (st === "waiting") return { s: "Esperando su respuesta en «" + stepRef(nid) + "»", k: "esperando" };
      if (st === "active") return { s: "En curso · " + stepRef(nid), k: "en curso" };
      if (st === "done") return { s: "Completó el flujo", k: "completó" };
      if (st === "cancelled") return { s: "Cancelado (reinició u otro motivo)", k: "cancelado" };
      return { s: st, k: st };
    };
    // COMPRAS-CONTACTO-1 · lo que ha gastado cada persona del registro (sin filas = no ha comprado).
    let gasto = new Map<string, import("./sio-ventas.js").GastoDePersona>();
    try {
      const { dbComprasFilasDeContactos } = await import("./db.js");
      const { gastoPorPersona } = await import("./sio-ventas.js");
      gasto = gastoPorPersona(await dbComprasFilasDeContactos(det.runs.map((r) => r.phone)), purchaseLinks());
    } catch { /* sin compras legibles: la columna sale con «—» */ }
    const contacts = det.runs.map((r) => {
      const a = agg.get(r.phone);
      const c = names.get(r.phone);
      const g = gasto.get(r.phone);
      const hs = humanStatus(r.run_status, r.node_id, !!a?.buy);
      return {
        phone: r.phone, name: r.name || c?.name || "", enteredAt: r.entered_at,
        status: hs.k, statusHuman: hs.s,
        // AVANCE-FLUJO-1 · cuándo saldrá su próximo paso o recordatorio (0 = nada programado).
        nextAt: (r.run_status === "active" || r.run_status === "waiting") ? (r.next_at || 0) : 0,
        lastAt: a?.lastAt || r.entered_at, nMsg: a?.nMsg || 0, nResp: a?.nResp || 0, nEvents: a?.n || 0, errors: a?.err || 0,
        // COMPRAS-CONTACTO-1 · gastado en su moneda principal; spentAll lleva cada moneda por separado.
        buys: g?.compras || 0, spent: g?.total[0]?.importe || 0, spentCur: g?.total[0]?.currency || "",
        spentAll: g?.total || [], spentEst: !!g?.estimado, spentSin: g?.sinImporte || 0,
      };
    });
    return {
      flowName: flow?.name || "",
      totalSteps: order.length,
      // RELANZAR-FLUJO-1 · los pasos en orden, con su etiqueta legible, para «Reiniciar…».
      steps: order.filter((nid) => String(nodes[nid]?.type || "") !== "end").map((nid) => ({ id: nid, label: stepRef(nid) })),
      contacts,
      events: events.map((e) => {
        const c = names.get(e.phone);
        const historic = e.detail === "histórico reconstruido";
        return {
          at: e.at, phone: e.phone, name: c?.name || "", event: e.event,
          step: e.node_id ? stepRef(e.node_id) : "",
          detail: historic ? "" : e.detail, historic,
        };
      }),
    };
  });
  // EMBUDO de eficiencia post-live: cuántos entraron → clicaron → escribieron → compraron,
  // con % de conversión, el reparto por CADA etiqueta que el flujo aplica (para ver ramas:
  // acudió/no acudió, pidió grabación, derivado…) y las COMBINACIONES de etapas más frecuentes.
  // Todo server-side y acotado por tenant (dbFlowFunnel + dbFlowDetail).
  app.get("/admin/api/flows/:id/funnel", async (req, reply) => {
    if (!(await guard(req, reply))) return;
    const id = String((req.params as { id: string }).id || "");
    const flow = (await listFlows()).find((f) => f.id === id);
    const nodes = (flow?.nodes || {}) as Record<string, Record<string, unknown>>;
    // Normaliza una etiqueta para fusionar variantes con acentos/espacios/guiones
    // («acudió live» = «acudio live» = «acudio-live»).
    const normTag = (s: unknown) => String(s || "").toLowerCase().normalize("NFD").replace(/[̀-ͯ]/g, "").replace(/[-_\s]+/g, " ").trim();
    // Etiquetas que ESTE flujo aplica (nodos con addTag), en orden BFS de aparición = las etapas.
    const flowTags: { norm: string; label: string }[] = [];
    const flowTagSeen = new Set<string>();
    {
      const seen = new Set<string>();
      const queue = [String(flow?.start || "")];
      while (queue.length) {
        const nid = queue.shift()!;
        if (!nid || seen.has(nid) || !nodes[nid]) continue;
        seen.add(nid);
        const n = nodes[nid];
        const raw = String((n as { addTag?: string }).addTag || "").trim();
        if (raw) { const nk = normTag(raw); if (nk && !flowTagSeen.has(nk)) { flowTagSeen.add(nk); flowTags.push({ norm: nk, label: raw }); } }
        for (const nx of [n.next, n.yes, n.no]) if (nx) queue.push(String(nx));
        if (Array.isArray(n.options)) for (const o of n.options) if (o && (o as { next?: string }).next) queue.push(String((o as { next?: string }).next));
      }
    }
    const CAP = 5000;
    const [fn, det] = await Promise.all([dbFlowFunnel(id), dbFlowDetail(id, CAP)]);
    // Conteos por etiqueta NORMALIZADA (fusiona variantes). METRICAS-1 · sumar variantes contaba
    // dos veces a quien lleva «Compró» y «compro» (y daba más del 100 %): con el detalle completo
    // se cuenta cada persona una vez; si el detalle está recortado, la suma se topa en el total.
    const entered = fn.contacts;
    const tagN = new Map<string, number>();
    if (det.runs.length >= entered) {
      for (const r of det.runs) {
        const vistas = new Set<string>();
        for (const t of (r.tags || [])) { const k = normTag(t); if (k && !vistas.has(k)) { vistas.add(k); tagN.set(k, (tagN.get(k) || 0) + 1); } }
      }
    } else {
      for (const { tag, n } of fn.tags) { const k = normTag(tag); tagN.set(k, Math.min(entered, (tagN.get(k) || 0) + n)); }
    }
    const pct = (n: number) => (entered > 0 ? Math.round((n / entered) * 1000) / 10 : 0);
    const getN = (concept: string) => tagN.get(normTag(concept)) || 0;
    // SIN-DEFAULTS-LM-1 · sin etiqueta de reserva: «inscrito lm» es la del curso
    // LeadMatch, y contar como compradores a los contactos de OTRO negocio que la
    // llevaran por casualidad falsea el embudo del cliente. Sin etiqueta en el flujo
    // ni en el ajuste, el contador de compras se queda a cero, que es la verdad.
    const boughtNorm = normTag(flow?.stopTag || getSetting("systemeio.stopTag"));
    const bought = tagN.get(boughtNorm) || 0;
    // Embudo de conversión compacto: etapas universales que apliquen a este flujo.
    const funnel: { key: string; label: string; n: number; pct: number }[] = [];
    funnel.push({ key: "entro", label: "Entró al flujo", n: entered, pct: 100 });
    funnel.push({ key: "clico", label: "Clicó un enlace", n: fn.clickers, pct: pct(fn.clickers) });
    const nEscribio = getN("escribió");
    if (nEscribio > 0 || flowTagSeen.has(normTag("escribió"))) funnel.push({ key: "escribio", label: "Escribió", n: nEscribio, pct: pct(nEscribio) });
    if (flow?.stopTag || bought > 0) funnel.push({ key: "compro", label: "Compró", n: bought, pct: pct(bought) });
    // Reparto por cada etiqueta del flujo (todas las etapas, incluidas las ramas).
    const tags = flowTags.map((t) => { const n = tagN.get(t.norm) || 0; return { label: t.label, n, pct: pct(n) }; });
    // Combinaciones de etapas por contacto (solo etiquetas de ESTE flujo), top más frecuentes.
    const orderIdx = new Map(flowTags.map((t, i) => [t.norm, i]));
    const comboMap = new Map<string, { parts: string[]; n: number }>();
    for (const r of det.runs) {
      const present = new Set<string>();
      for (const t of (r.tags || [])) { const k = normTag(t); if (flowTagSeen.has(k)) present.add(k); }
      const parts = [...present].sort((a, b) => (orderIdx.get(a) ?? 99) - (orderIdx.get(b) ?? 99)).map((k) => flowTags.find((f) => f.norm === k)?.label || k);
      const sig = parts.length ? parts.join(" → ") : "(sin etapas registradas)";
      const c = comboMap.get(sig) || { parts: parts.length ? parts : ["(sin etapas registradas)"], n: 0 };
      c.n++;
      comboMap.set(sig, c);
    }
    const combos = [...comboMap.values()].sort((a, b) => b.n - a.n).slice(0, 14);
    // OBJETIVO-FLUJO-1 · «¿quién hizo la acción final?» (compró, rellenó el formulario, llegó a la
    // página de gracias…), en cualquier canal. El objetivo sale del propio flujo, sin configurar
    // nada: es la condición («¿vio la página X?», «¿ha comprado?», «¿tiene la etiqueta X?») cuyo SÍ
    // CIERRA el flujo — solo acciones o mensajes detrás, ni esperas ni preguntas ni más
    // condiciones. Más la etiqueta de la regla de salida y las que pone ese cierre. Cuenta tanto
    // lo que el flujo ya decidió (evento SÍ) como lo que pasó y aún no ha comprobado (quien está
    // en una espera y ya pagó). «¿Abrió el enlace?» sin página concreta no es un objetivo.
    // Un SÍ que no lleva a nada, o solo a «Fin», también cierra (es lo que deja el botón
    // «Añade como último paso» de Resultados).
    // VENTAS-SIO-1 · lo que ha recaudado este flujo: ventas de las webs y (COMPRAS-CONTACTO-1) de los
    // enlaces de pago del panel de su gente, cada una al último flujo en el que entró antes de pagar.
    const ventas = await (async () => {
      const { dbVentasDeFlujos } = await import("./db.js");
      const { resumenDeVentas } = await import("./sio-ventas.js");
      return resumenDeVentas(await dbVentasDeFlujos({ flowIds: [id] }), purchaseLinks());
    })().catch((e) => { console.warn("[flow] recaudado:", (e as Error).message); return null; });
    const ventaDe = new Map((ventas?.compradores || []).map((c) => [c.phone, c]));
    const goal = await (async () => {
      const cierra = (start: unknown): { ok: boolean; tags: string[] } => {
        const tags: string[] = [];
        const seen = new Set<string>();
        const queue = [String(start || "")];
        while (queue.length) {
          const nid = queue.shift()!;
          if (!nid || seen.has(nid)) continue;
          const n = nodes[nid];
          if (!n) continue;
          seen.add(nid);
          const t = String(n.type || "");
          if (t === "end") continue;
          if (t !== "action" && t !== "message") return { ok: false, tags: [] };
          const tg = String((n as { addTag?: string }).addTag || "").trim();
          if (tg) tags.push(tg);
          if (n.next) queue.push(String(n.next));
        }
        return { ok: true, tags };
      };
      const pages: string[] = [];
      let purchase = false;
      const tagNorms = new Map<string, string>(); // norm → como se escribió
      const goalNodes = new Set<string>();
      for (const [nid, n] of Object.entries(nodes)) {
        if (String(n.type || "") !== "condition") continue;
        const src = String(n.source || "");
        const val = String(n.value || "").trim();
        const esObjetivo = (src === "linkOpened" && !!val && !n.notPurchased) || src === "purchased" || (src === "hasTag" && !!val);
        if (!esObjetivo) continue;
        const c = cierra(n.yes);
        if (!c.ok) continue;
        goalNodes.add(nid);
        if (src === "linkOpened") pages.push(val);
        else if (src === "purchased") purchase = true;
        else tagNorms.set(normTag(val), val);
        for (const tg of c.tags) tagNorms.set(normTag(tg), tg);
      }
      if (flow?.stopTag) tagNorms.set(normTag(flow.stopTag), flow.stopTag);
      if (!goalNodes.size && !tagNorms.size) return null;
      const { contactosQueVieronPagina, trozoDeRuta } = await import("./web-analytics.js");
      const runs = det.runs;
      const dig = (p: string) => String(p || "").replace(/[^\d]/g, "");
      const desde = new Map<string, number>();
      for (const r of runs) { const d = dig(r.phone); if (d) desde.set(d, r.entered_at || 0); }
      const [visto, compras, evs] = await Promise.all([
        pages.length ? contactosQueVieronPagina(currentWorkspaceId() || "default", desde, pages) : Promise.resolve(new Map<string, { at: number; path: string }>()),
        purchase ? dbComprasDeContactos(runs.map((r) => r.phone)) : Promise.resolve(new Map<string, number>()),
        goalNodes.size ? dbFlowEvents(id, 5000) : Promise.resolve([] as Awaited<ReturnType<typeof dbFlowEvents>>),
      ]);
      const siEvt = new Map<string, number>();
      for (const e of evs) if (e.event === "condición" && goalNodes.has(e.node_id) && /→ SÍ$/.test(e.detail || "")) { const prev = siEvt.get(e.phone); if (!prev || e.at < prev) siEvt.set(e.phone, e.at); }
      const people: { phone: string; name: string; source: string; at: number; how: string; importe: number; currency: string; estimado?: boolean; ingresos: { moneda: string; importe: number }[]; compras: number }[] = [];
      for (const r of runs) {
        const v = visto.get(dig(r.phone));
        const compra = compras.get(r.phone) || 0;
        const tag = (r.tags || []).find((t) => tagNorms.has(normTag(t)));
        const si = siEvt.get(r.phone);
        let how = "", at = 0;
        if (v) { how = "Vio " + (trozoDeRuta(v.path) || v.path); at = v.at; }
        else if (compra && compra >= (r.entered_at || 0)) { how = "Compra registrada"; at = compra; }
        else if (si) { how = "Cumplió el paso final"; at = si; }
        else if (tag) { how = "Etiqueta «" + tag + "»"; at = 0; }
        const vv = ventaDe.get(r.phone);
        if (!how && vv && purchase) { how = "Compró"; at = vv.at; }
        if (how) people.push({ phone: r.phone, name: r.name || "", source: r.source || "", at, how, importe: vv?.importe || 0, currency: vv?.currency || "", estimado: !!vv?.estimado, ingresos: vv?.ingresos || [], compras: vv?.compras || 0 });
      }
      people.sort((a, b) => b.at - a.at);
      const what = [...new Set(pages.map((p) => "ver " + (trozoDeRuta(p) || p)))].concat(purchase ? ["comprar"] : [], [...tagNorms.values()].map((t) => "etiqueta «" + t + "»"));
      return { n: people.length, pct: pct(people.length), what, people: people.slice(0, 1000) };
    })().catch((e) => { console.warn("[flow] objetivo:", (e as Error).message); return null; });
    return {
      goal,
      recaudado: ventas ? { total: ventas.total, compradores: ventas.compradores.slice(0, 1000), estimado: ventas.estimado, sinImporte: ventas.sinImporte } : null,
      flowName: flow?.name || "",
      entered,
      clickers: fn.clickers,
      bought,
      boughtLabel: flow?.stopTag || "", // SIN-DEFAULTS-LM-1 · sin etiqueta del curso a la vista del cliente
      hasStopTag: !!flow?.stopTag,
      convPct: pct(bought),
      funnel,
      tags,
      combos,
      sampleCapped: det.runs.length >= CAP,
      sampleSize: det.runs.length,
    };
  });
  // MÉTRICAS COMPLETAS del flujo («Ver métricas completas»): reparto % en cada bifurcación
  // (hacia dónde va la gente), conversión por paso (mostrados→respondieron), clics POR ENLACE
  // con la lista de quién clicó, conversión por rama (qué opción acaba en humano/compra), y
  // tiempos de venta (mediana hasta responder / hasta humano). Todo desde app_flow_events +
  // app_link_clicks + estados reales. Solo lectura, tenant-scoped.
  app.get("/admin/api/flows/:id/metrics", async (req, reply) => {
    if (!(await guard(req, reply))) return;
    const id = String((req.params as { id: string }).id || "");
    const flow = (await listFlows()).find((f) => f.id === id);
    if (!flow) return reply.code(404).send({ error: "flujo no encontrado" });
    const nodes = (flow.nodes || {}) as Record<string, Record<string, unknown>>;
    // ── BFS + etiqueta humana (mismo criterio que /events) ──
    const order: string[] = [];
    {
      const seen = new Set<string>();
      const queue = [String(flow.start || "")];
      while (queue.length) {
        const nid = queue.shift()!;
        if (!nid || seen.has(nid) || !nodes[nid]) continue;
        seen.add(nid); order.push(nid);
        const n = nodes[nid];
        for (const nx of [n.next, n.yes, n.no]) if (nx) queue.push(String(nx));
        if (Array.isArray(n.options)) for (const o of n.options) if (o && (o as { next?: string }).next) queue.push(String((o as { next?: string }).next));
      }
    }
    const posOf = new Map(order.map((nid, i) => [nid, i + 1]));
    const txt = (s: unknown, max = 60) => { const v = String(s || "").replace(/\s+/g, " ").trim(); return v.length > max ? v.slice(0, max) + "…" : v; };
    const nodeLabel = (nid: string): string => {
      const n = nodes[nid];
      if (!n) return "paso antiguo";
      const t = String(n.type || "");
      if (t === "message") return "Mensaje · " + (txt(n.text) || "(sin texto)");
      if (t === "ask") return "Pregunta · " + (txt(n.text) || String(n.saveAs || ""));
      if (t === "buttons") return "Opciones · " + (txt(n.text) || "");
      if (t === "follow") return "Pedir seguir (IG)";
      return t;
    };
    const [events, det, fn, clickRows] = await Promise.all([
      dbFlowEvents(id, 5000), dbFlowDetail(id, 5000), dbFlowFunnel(id), dbFlowLinkClickers(id),
    ]);
    // ── Agregación por nodo desde los eventos ──
    const sentBy = new Map<string, Set<string>>();   // 'mensaje' por nodo → teléfonos
    const shownBy = new Map<string, Set<string>>();  // 'opciones'/'pregunta'/'pedir seguir' por nodo
    const respBy = new Map<string, Map<string, Set<string>>>(); // nodo → label → teléfonos
    const respAllBy = new Map<string, Set<string>>();
    const firstShownAt = new Map<string, number>();  // phone|node → ts primera vez mostrado
    const enteredAt = new Map<string, number>();     // phone → ts entró (primera)
    const carlaAt = new Map<string, number>();       // phone → ts primer aviso a Carla
    const boughtPh = new Set<string>();
    const derivedSilence = new Set<string>();
    const derivedWrite = new Set<string>();
    const replyDeltas: number[] = [];
    const add = (m: Map<string, Set<string>>, k: string, p: string) => { let s = m.get(k); if (!s) { s = new Set(); m.set(k, s); } s.add(p); };
    const evAsc = [...events].sort((a, b) => a.at - b.at);
    for (const e of evAsc) {
      const p = e.phone, nid = e.node_id || "";
      if (e.event === "entró") { if (!enteredAt.has(p)) enteredAt.set(p, e.at); continue; }
      if (e.event === "mensaje") { if (nid) add(sentBy, nid, p); continue; }
      if (e.event === "opciones" || e.event === "pregunta" || e.event === "pedir seguir") {
        if (nid) { add(shownBy, nid, p); const k = p + "|" + nid; if (!firstShownAt.has(k)) firstShownAt.set(k, e.at); }
        continue;
      }
      if (e.event === "respondió") {
        if (nid) {
          add(respAllBy, nid, p);
          let lm = respBy.get(nid); if (!lm) { lm = new Map(); respBy.set(nid, lm); }
          const lbl = String(e.detail || "").trim();
          // COHORTE EXCLUSIVA · si el contacto ya había respondido OTRA cosa en este paso
          // (reinició el flujo y volvió a pasar), cuenta solo su ÚLTIMA respuesta: si no,
          // el mismo teléfono sumaba en varias opciones y los % superaban el 100%.
          for (const s of lm.values()) s.delete(p);
          let set = lm.get(lbl); if (!set) { set = new Set(); lm.set(lbl, set); }
          set.add(p);
          const k = p + "|" + nid; const t0 = firstShownAt.get(k);
          if (t0 && e.at > t0) replyDeltas.push(e.at - t0);
        }
        continue;
      }
      if (e.event === "acción" && String(e.detail || "").includes("aviso al closer")) { if (!carlaAt.has(p)) carlaAt.set(p, e.at); continue; }
      if (e.event.includes("compró")) { boughtPh.add(p); continue; }
      if (e.event === "derivado · inactividad") { derivedSilence.add(p); carlaAt.has(p) || carlaAt.set(p, e.at); continue; }
      if (e.event === "derivado · escribió en espera") { derivedWrite.add(p); carlaAt.has(p) || carlaAt.set(p, e.at); continue; }
    }
    // ── Splits por bifurcación (nodos buttons con actividad) + destino de cada opción ──
    const norm = (s: string) => s.toLowerCase().normalize("NFD").replace(/[̀-ͯ]/g, "").replace(/\s+/g, " ").trim();
    const splits: unknown[] = [];
    for (const nid of order) {
      const n = nodes[nid];
      if (String(n.type) !== "buttons") continue;
      const shown = shownBy.get(nid)?.size || 0;
      const lm = respBy.get(nid) || new Map<string, Set<string>>();
      const respondedSet = respAllBy.get(nid) || new Set<string>();
      if (!shown && !respondedSet.size) continue;
      const opts = (Array.isArray(n.options) ? n.options : []) as { label?: string }[];
      const usedPh = new Set<string>();
      const options = opts.map((o) => {
        const lbl = String(o.label || "");
        // match exacto (tap del botón) + normalizado (por si cambió una tilde)
        let set = lm.get(lbl);
        if (!set) { for (const [k, v] of lm) if (norm(k) === norm(lbl)) { set = v; break; } }
        set = set || new Set();
        for (const p of set) usedPh.add(p);
        const carla = [...set].filter((p) => carlaAt.has(p)).length;
        const bought = [...set].filter((p) => boughtPh.has(p)).length;
        return { label: lbl, n: set.size, pct: respondedSet.size ? Math.round((set.size / respondedSet.size) * 100) : 0, carla, bought };
      });
      const libreSet = [...respondedSet].filter((p) => !usedPh.has(p));
      splits.push({
        nodeId: nid, pos: posOf.get(nid) || 0, label: nodeLabel(nid),
        shown, responded: respondedSet.size,
        respRate: shown ? Math.round((respondedSet.size / shown) * 100) : 0,
        options,
        libre: libreSet.length ? { n: libreSet.length, carla: libreSet.filter((p) => carlaAt.has(p)).length, bought: libreSet.filter((p) => boughtPh.has(p)).length } : null,
      });
    }
    // ── Conversión por paso interactivo (mostrados → respondieron) ──
    const steps = order
      .filter((nid) => ["buttons", "ask", "follow"].includes(String(nodes[nid].type)))
      .map((nid) => {
        const shown = shownBy.get(nid)?.size || 0;
        const resp = respAllBy.get(nid)?.size || 0;
        return { nodeId: nid, pos: posOf.get(nid) || 0, label: nodeLabel(nid), shown, responded: resp, rate: shown ? Math.round((resp / shown) * 100) : 0 };
      })
      .filter((s) => s.shown > 0);
    // ── Clics POR ENLACE (con quién) ──
    const urlNodes = new Map<string, string[]>(); // urlBase → nodos que lo llevan
    for (const nid of order) {
      const l = String((nodes[nid] as { link?: string }).link || "");
      if (!l) continue;
      const base = l.split(/[?#]/)[0];
      const arr = urlNodes.get(base) || []; arr.push(nid); urlNodes.set(base, arr);
    }
    const clickersByUrl = new Map<string, { phone: string; n: number; lastAt: number }[]>();
    for (const c of clickRows) { const arr = clickersByUrl.get(c.urlBase) || []; arr.push(c); clickersByUrl.set(c.urlBase, arr); }
    const allPhones = new Set<string>([...enteredAt.keys(), ...clickRows.map((c) => c.phone), ...det.runs.map((r) => r.phone)]);
    const names = await dbGetContactsByIds([...allPhones]);
    const linkRows = (det.links || []).map((L) => {
      const base = String(L.url || "").split(/[?#]/)[0];
      const nids = urlNodes.get(base) || [];
      const sentSet = new Set<string>();
      for (const nid of nids) for (const p of sentBy.get(nid) || []) sentSet.add(p);
      const who = (clickersByUrl.get(base) || []).map((c) => ({ phone: c.phone, name: names.get(c.phone)?.name || "", n: c.n, lastAt: c.lastAt }));
      const short = base.replace(/^https?:\/\//, "");
      return {
        urlBase: base, label: L.label || short.slice(0, 60),
        stepsWith: nids.map((nid) => "paso " + (posOf.get(nid) || "?")).join(", "),
        sent: sentSet.size, clicks: L.clicks || 0, people: L.people || 0,
        ctrPct: sentSet.size ? Math.round(((L.people || 0) / sentSet.size) * 100) : null,
        clickers: who,
      };
    }).sort((a, b) => (b.people - a.people) || (b.clicks - a.clicks));
    // ── Tiempos (medianas) ──
    const median = (a: number[]) => { if (!a.length) return null; const s = [...a].sort((x, y) => x - y); return s[Math.floor(s.length / 2)]; };
    const toCarla: number[] = [];
    for (const [p, t] of carlaAt) { const t0 = enteredAt.get(p); if (t0 && t > t0) toCarla.push(t - t0); }
    const mReply = median(replyDeltas); const mCarla = median(toCarla);
    // Compró: mismo criterio que el embudo — etiqueta de la regla de compra sobre los contactos del flujo.
    const normT = (s: unknown) => String(s || "").toLowerCase().normalize("NFD").replace(/[̀-ͯ]/g, "").replace(/[-_\s]+/g, " ").trim();
    const boughtNorm = normT(flow.stopTag || getSetting("systemeio.stopTag")); // SIN-DEFAULTS-LM-1
    const boughtN = fn.tags.filter((t) => normT(t.tag) === boughtNorm).reduce((a, t) => a + t.n, 0);
    return {
      flowName: flow.name || "", totalSteps: order.length,
      entered: fn.contacts, clickersTotal: fn.clickers, bought: boughtN, boughtLabel: flow.stopTag || "", hasStopTag: !!flow.stopTag, // SIN-DEFAULTS-LM-1 convPct: fn.contacts ? Math.round((boughtN / fn.contacts) * 1000) / 10 : 0,
      reachedCarla: carlaAt.size, derivedSilence: derivedSilence.size, derivedWrite: derivedWrite.size,
      medianReplyMin: mReply == null ? null : Math.round(mReply / 60000),
      medianToCarlaMin: mCarla == null ? null : Math.round(mCarla / 60000),
      splits, steps, links: linkRows,
      eventsUsed: events.length, capped: events.length >= 5000,
    };
  });
  // SEGUIMIENTO-WA-1 (MET-WA-04) · embudo de SEGUIMIENTO de un flujo de WhatsApp (p. ej. quien
  // pidió el diagnóstico): mensaje inicial → cada seguimiento → reserva CONFIRMADA. Todo va por
  // PERSONAS que entraron en el periodo, con su historia completa desde ese momento.
  //  · Etapas: se recorre el flujo desde el inicio; cruzar una ESPERA abre etapa nueva. La
  //    primera etapa con mensajes es el inicial; cada siguiente, un seguimiento.
  //  · Reserva confirmada = la agenda de la web (reserva hecha, emparejada por email o por
  //    nombre único) o una reunión apuntada en su ficha. Pulsar «Reservar» o abrir el enlace
  //    NO es reservar. Sin ninguna reserva sincronizada nunca, la agenda no está conectada y
  //    el dato es «sin medición», no un cero.
  //  · Atribución: la reserva cuenta para el ÚLTIMO mensaje recibido antes de hacerla, y solo
  //    dentro de VENTANA; una reserva previa al seguimiento es del inicial, nunca del recordatorio.
  //    Cada persona cuenta UNA vez. Una reunión de ficha no tiene momento de reserva: se cuenta
  //    aparte («sin momento»), no se atribuye a ningún mensaje.
  //  · Abandono: personas sin reserva ni compra y sin nada programado, por el último mensaje
  //    que recibieron. Mismos eventos que el resto de métricas de flujos (app_flow_events).
  // RAMAS-WA-1 (MET-WA-05) · y las RAMAS: cada opción con su texto, a dónde lleva y qué fue de
  // quien la eligió (reservó, compró o se paró); quién se paró en CADA paso; cada enlace con
  // pulsaron → visitaron la web (visita atribuida; sin píxel, «sin medición») → resultado.
  // Regla de conteo: una persona cuenta UNA vez, desde su primera entrada en el rango; en cada
  // pregunta vale su ÚLTIMA elección; lo que escribe a mano no es una opción (se cuenta aparte:
  // lo atiende el asistente o el equipo). Filtros: punto de entrada (lo que la hizo entrar,
  // del evento «entró») y campaña (la del primer contacto de su ficha).
  app.get("/admin/api/analytics/whatsapp/seguimiento", async (req, reply) => {
    if (!(await guard(req, reply))) return;
    const q = (req.query as Record<string, string>) || {};
    const win = apWin(req);
    const ahora = Date.now();
    const untilMs = win?.untilMs ?? ahora;
    const sinceMs = win?.sinceMs ?? ahora - apDays(req) * 86400000;
    const VENTANA_D = 7, VENTANA = VENTANA_D * 86400000;
    const todos = await listFlows();
    const flujos = (await dbFlowsConEntradasWa(sinceMs, untilMs))
      .map((a) => { const f = todos.find((x) => x.id === a.flow_id); return f ? { id: f.id, name: f.name || "(sin nombre)", entraron: a.n } : null; })
      .filter((x): x is { id: string; name: string; entraron: number } => !!x)
      .sort((a, b) => b.entraron - a.entraron);
    let id = String(q.flow || "");
    if (!flujos.some((f) => f.id === id)) id = (flujos.find((f) => /diagn/i.test(f.name)) || flujos[0])?.id || "";
    const flow = todos.find((f) => f.id === id);
    if (!flow) return { flujos, flujo: null, ventanaDias: VENTANA_D };
    const nodes = (flow.nodes || {}) as Record<string, Record<string, unknown>>;
    // ── Etapas: recorrido en anchura; cruzar una espera suma una etapa ──
    const etapaDe = new Map<string, number>();
    {
      const cola: Array<[string, number]> = [[String(flow.start || ""), 0]];
      while (cola.length) {
        const [nid, k] = cola.shift()!;
        if (!nid || !nodes[nid] || etapaDe.has(nid)) continue;
        etapaDe.set(nid, k);
        const n = nodes[nid];
        const k2 = String(n.type) === "delay" ? k + 1 : k;
        for (const nx of [n.next, n.yes, n.no]) if (nx) cola.push([String(nx), k2]);
        if (Array.isArray(n.options)) for (const o of n.options as { next?: string }[]) if (o && o.next) cola.push([String(o.next), k2]);
      }
    }
    const ENVIO = new Set(["message", "buttons", "ask"]);
    const nodosEnvio = [...etapaDe.keys()].filter((nid) => ENVIO.has(String(nodes[nid].type)));
    const etapasK = [...new Set(nodosEnvio.map((nid) => etapaDe.get(nid)!))].sort((a, b) => a - b);
    const idxDeNodo = new Map<string, number>(nodosEnvio.map((nid) => [nid, etapasK.indexOf(etapaDe.get(nid)!)]));
    // ── Historia de cada persona que ENTRÓ en el periodo ──
    const evs = await dbFlowEventsDesde(id, sinceMs);
    type Persona = { ent: number; entrada: string; rec: number[]; ultimoNodo: string; ultimoAt: number; resp: Array<{ at: number; nodo: string; txt: string }>; compro: number };
    const gente = new Map<string, Persona>();
    for (const e of evs) {
      if (!/^[0-9]+$/.test(e.phone)) continue;
      const p = gente.get(e.phone);
      if (e.event === "entró") {
        if (!p && e.at <= untilMs) gente.set(e.phone, { ent: e.at, entrada: String(e.detail || "").trim(), rec: [], ultimoNodo: "", ultimoAt: 0, resp: [], compro: 0 });
        continue;
      }
      if (!p) continue;
      const nid = e.node_id || "";
      if ((e.event === "mensaje" || e.event === "opciones" || e.event === "pregunta") && idxDeNodo.has(nid)) {
        const i = idxDeNodo.get(nid)!;
        if (p.rec[i] == null) p.rec[i] = e.at;
        if (e.at >= p.ultimoAt) { p.ultimoAt = e.at; p.ultimoNodo = nid; }
        continue;
      }
      if (e.event === "respondió") { p.resp.push({ at: e.at, nodo: nid, txt: String(e.detail || "").trim() }); continue; }
      if (e.event.includes("compró") && !p.compro) p.compro = e.at;
    }
    // RAMAS-WA-1 · filtros. Las listas se cuentan ANTES de filtrar (el selector enseña todas).
    const fichas = await dbGetContactsByIds([...gente.keys()]);
    const campDe = (t: string) => String(fichas.get(t)?.utm_campaign || "").trim();
    const mEnt = new Map<string, number>(), mCam = new Map<string, number>();
    for (const [t, p] of gente) { mEnt.set(p.entrada, (mEnt.get(p.entrada) || 0) + 1); mCam.set(campDe(t), (mCam.get(campDe(t)) || 0) + 1); }
    const listaDe = (m: Map<string, number>) => [...m].map(([k, n]) => ({ k, n })).sort((a, b) => b.n - a.n || a.k.localeCompare(b.k));
    const entradas = listaDe(mEnt), campanas = listaDe(mCam);
    const fEnt = q.entrada !== undefined && mEnt.has(String(q.entrada)) ? String(q.entrada) : null;
    const fCam = q.campana !== undefined && mCam.has(String(q.campana)) ? String(q.campana) : null;
    for (const [t, p] of [...gente]) if ((fEnt != null && p.entrada !== fEnt) || (fCam != null && campDe(t) !== fCam)) gente.delete(t);
    const tels = [...gente.keys()];
    const [compras, reservas, det, clics, visitas] = await Promise.all([
      dbComprasDeContactos(tels),
      dbReservasDesde(sinceMs),
      dbFlowDetail(id, 5000),
      dbFlowLinkClickers(id),
      dbVisitasTrasClicFlujo(id),
    ]);
    for (const [t, ts] of compras) { const p = gente.get(t); if (p && ts > p.ent && !p.compro) p.compro = ts; }
    const proxima = new Map(det.runs.map((r) => [r.phone, r.next_at]));
    // ── Reservas confirmadas: sólo por el correo de la ficha ──
    // MET-AUTO-09-FIN · una reserva se relaciona con una persona sólo si la identidad está acreditada
    // (regla común de src/identidad.ts). El nombre no acredita: dos «María» distintas no son la misma.
    const porEmail = new Map<string, string>();
    for (const t of tels) {
      const c = fichas.get(t);
      if (c?.email) porEmail.set(String(c.email).trim().toLowerCase(), t);
    }
    const reservaDe = new Map<string, { at: number | null; via: string }>();
    for (const b of reservas.filas) {
      if (/cancel/i.test(b.estado)) continue;
      const t = (b.email && porEmail.get(b.email)) || "";
      const p = t ? gente.get(t) : undefined;
      if (!p) continue;
      if (b.creada != null && b.creada < p.ent) continue; // reservó ANTES de entrar: no es de este flujo
      const prev = reservaDe.get(t);
      if (!prev || (b.creada != null && (prev.at == null || b.creada < prev.at))) reservaDe.set(t, { at: b.creada, via: "agenda" });
    }
    let conFicha = 0;
    for (const t of tels) {
      const c = fichas.get(t); const p = gente.get(t)!;
      if (!reservaDe.has(t) && c?.next_action_at && c.next_action_at >= p.ent) { reservaDe.set(t, { at: null, via: "ficha" }); conFicha++; }
    }
    const medida = reservas.conectada || conFicha > 0;
    // ── Atribución de cada reserva al último mensaje recibido antes de hacerla ──
    const N = etapasK.length;
    const ultimaAntes = (p: Persona, at: number) => { let s = -1; for (let i = 0; i < N; i++) if (p.rec[i] != null && p.rec[i] <= at) s = i; return s; };
    const resPorEtapa = Array.from({ length: N }, () => new Set<string>());
    const fueraVentana = new Set<string>(), sinMomento = new Set<string>();
    const etapaReserva = new Map<string, number>();
    for (const [t, r] of reservaDe) {
      const p = gente.get(t)!;
      if (r.at == null) { sinMomento.add(t); continue; }
      const s = ultimaAntes(p, r.at);
      if (r.at - (s >= 0 ? p.rec[s] : p.ent) > VENTANA) { fueraVentana.add(t); continue; }
      const k = Math.max(0, s);
      if (k < N) { resPorEtapa[k].add(t); etapaReserva.set(t, k); }
    }
    // ── Respuestas: cuentan para el último mensaje recibido antes de responder ──
    const respPorEtapa = Array.from({ length: N }, () => new Set<string>());
    const opcionesPorNodo = new Map<string, Map<string, Set<string>>>();
    for (const [t, p] of gente) {
      for (const r of p.resp) {
        const s = ultimaAntes(p, r.at);
        if (s >= 0) respPorEtapa[s].add(t);
        const n = nodes[r.nodo];
        if (n && String(n.type) === "buttons" && r.txt) {
          let m = opcionesPorNodo.get(r.nodo); if (!m) { m = new Map(); opcionesPorNodo.set(r.nodo, m); }
          for (const set of m.values()) set.delete(t); // cuenta su ÚLTIMA respuesta en ese paso
          (m.get(r.txt) || m.set(r.txt, new Set()).get(r.txt)!).add(t);
        }
      }
    }
    const urlBase = (u: unknown) => String(u || "").split(/[?#]/)[0];
    const clicsPorUrl = new Map<string, Set<string>>();
    for (const c of clics) (clicsPorUrl.get(c.urlBase) || clicsPorUrl.set(c.urlBase, new Set()).get(c.urlBase)!).add(c.phone);
    const visitasPorUrl = new Map<string, Set<string>>();
    for (const v of visitas.visitas) (visitasPorUrl.get(v.urlBase) || visitasPorUrl.set(v.urlBase, new Set()).get(v.urlBase)!).add(v.phone);
    const corta = (v: unknown, max = 400) => { const x = String(v || "").replace(/\s+/g, " ").trim(); return x.length > max ? x.slice(0, max) + "…" : x; };
    const enCurso = (t: string) => { const nx = proxima.get(t); return nx != null && nx > ahora; };
    // ── Abandono: sin reserva ni compra y sin nada programado, por último mensaje recibido ──
    const parados = new Map<string, number>();
    const paradoSet = new Set<string>();
    for (const [t, p] of gente) {
      if (reservaDe.has(t) || p.compro || enCurso(t) || !p.ultimoNodo) continue;
      parados.set(p.ultimoNodo, (parados.get(p.ultimoNodo) || 0) + 1);
      paradoSet.add(t);
    }
    // RAMAS-WA-1 · qué fue de un grupo de personas, y a qué paso lleva una opción (se saltan
    // esperas y acciones; una comprobación decide sola el camino, así que se dice tal cual).
    const queFue = (ts: Iterable<string>) => {
      const a = [...ts].filter((t) => gente.has(t));
      return { n: a.length, reservaron: medida ? a.filter((t) => reservaDe.has(t)).length : null, compraron: a.filter((t) => gente.get(t)!.compro).length, pararon: a.filter((t) => paradoSet.has(t)).length };
    };
    const llevaA = (nx: unknown) => {
      let cur = String(nx || "");
      const vistos = new Set<string>();
      while (cur && nodes[cur] && !vistos.has(cur)) {
        vistos.add(cur);
        const n = nodes[cur], ty = String(n.type || "");
        if (ENVIO.has(ty)) return { tipo: "paso", texto: corta(n.text, 140), etapa: idxDeNodo.get(cur) ?? null };
        if (ty === "condition") return { tipo: "condicion", texto: "", etapa: null };
        cur = String(n.next || "");
      }
      return { tipo: "fin", texto: "", etapa: null };
    };
    const nodoInfo = (nid: string) => {
      const n = nodes[nid] || {};
      const opts = Array.isArray(n.options) ? (n.options as { label?: string; next?: string }[]) : [];
      const lbls = opts.map((o) => String(o?.label || ""));
      const m = opcionesPorNodo.get(nid);
      const otro = new Set<string>();
      if (m) for (const [txt, set] of m) if (!lbls.includes(txt)) for (const t of set) otro.add(t);
      const u = urlBase(n.link);
      const pulsaron = u ? [...(clicsPorUrl.get(u) || [])].filter((t) => gente.has(t)) : [];
      return {
        id: nid, tipo: String(n.type || ""), texto: corta(n.text), enlace: u,
        opciones: lbls.map((l, i) => ({ label: l, ...queFue(m?.get(l) || []), lleva: llevaA(opts[i]?.next) })),
        otro: queFue(otro),
        pararon: parados.get(nid) || 0,
        enlaceRes: u ? { pulsaron: pulsaron.length, visitaron: visitas.medible ? pulsaron.filter((t) => visitasPorUrl.get(u)?.has(t)).length : null, ...(() => { const r = queFue(pulsaron); return { reservaron: r.reservaron, compraron: r.compraron }; })() } : null,
      };
    };
    const etapas = etapasK.map((_k, i) => {
      const nids = nodosEnvio.filter((nid) => idxDeNodo.get(nid) === i);
      const recSet = new Set([...gente].filter(([, p]) => p.rec[i] != null).map(([t]) => t));
      const urls = [...new Set(nids.map((nid) => urlBase(nodes[nid].link)).filter(Boolean))];
      const enlace = urls.length ? [...recSet].filter((t) => urls.some((u) => clicsPorUrl.get(u)?.has(t))).length : null;
      // Población ELEGIBLE: los que recibieron el mensaje anterior, y en qué quedaron los que no recibieron este.
      let elegibles: Record<string, number> | null = null;
      if (i > 0) {
        const prev = [...gente].filter(([, p]) => p.rec[i - 1] != null);
        const sinEste = prev.filter(([, p]) => p.rec[i] == null);
        const reservoAntes = (t: string) => etapaReserva.has(t) && etapaReserva.get(t)! < i;
        const yaReservaron = sinEste.filter(([t]) => reservoAntes(t)).length;
        const esperando = sinEste.filter(([t]) => !reservoAntes(t) && enCurso(t)).length;
        elegibles = { previos: prev.length, recibieron: prev.length - sinEste.length, yaReservaron, esperando, salieron: sinEste.length - yaReservaron - esperando };
      }
      return { n: i, recibieron: recSet.size, elegibles, respondieron: respPorEtapa[i].size, enlace, reservaron: medida ? resPorEtapa[i].size : null, pasos: nids.map(nodoInfo) };
    });
    const top = [...parados].sort((a, b) => b[1] - a[1])[0];
    const recibieronNodo = (nid: string) => new Set(evs.filter((e) => e.node_id === nid && gente.has(e.phone) && (e.event === "mensaje" || e.event === "opciones" || e.event === "pregunta")).map((e) => e.phone)).size;
    const abandono = top ? { ...nodoInfo(top[0]), etapa: idxDeNodo.get(top[0]) ?? 0, pararon: top[1], recibieron: recibieronNodo(top[0]), total: [...parados.values()].reduce((a, b) => a + b, 0) } : null;
    return {
      flujos, ventanaDias: VENTANA_D,
      flujo: {
        id, name: flow.name || "", entraron: gente.size,
        entradas, campanas, filtro: { entrada: fEnt, campana: fCam }, visitasMedibles: visitas.medible,
        medida, agenda: reservas.conectada,
        reservaron: medida ? reservaDe.size : null, fueraVentana: fueraVentana.size, sinMomento: sinMomento.size,
        compraron: [...gente.values()].filter((p) => p.compro).length,
        enCurso: tels.filter(enCurso).length,
        etapas, abandono,
        recortado: evs.length >= 20000,
      },
    };
  });
  // RESCATE de comentarios de IG que se cayeron (su webhook no llegó, típico tras un
  // reinicio) y por eso NUNCA entraron en su automatización. Barre por API los posts con
  // flujo de comentario y reincorpora a los caídos. dryRun=1 (por defecto) solo informa;
  // dryRun=0 dispara de verdad. Idempotente (reclama el comentario antes de disparar).
  app.post("/admin/api/ig/backfill-comments", async (req, reply) => {
    if (!(await guard(req, reply))) return;
    const q = req.query as Record<string, string>;
    const body = (json(req) ?? {}) as Record<string, unknown>;
    const pick = (k: string) => (body[k] ?? q[k]) as string | number | undefined;
    const dryRunRaw = String(pick("dryRun") ?? "1");
    const dryRun = !(dryRunRaw === "0" || dryRunRaw === "false");
    const sinceHours = Math.min(720, Math.max(1, Number(pick("sinceHours")) || 24));
    const flowId = (pick("flowId") || pick("flow_id")) as string | undefined;
    const incluirReclamados = ["1", "true"].includes(String(pick("incluirReclamados") ?? ""));
    // RESCATE-UNO-1 · commentIds: lista o "id1,id2" — solo esos comentarios.
    const rawIds = body.commentIds ?? q.commentIds;
    const commentIds = (Array.isArray(rawIds) ? rawIds : String(rawIds ?? "").split(",")).map((x) => String(x).trim()).filter(Boolean);
    try {
      const rep = await backfillIgCommentDrops({ sinceHours, dryRun, flowId: flowId ? String(flowId) : undefined, incluirReclamados, commentIds });
      return rep;
    } catch (e) {
      return reply.code(500).send({ error: (e as Error).message });
    }
  });
  // Lo mismo para FACEBOOK (copia literal del handler de arriba). Facebook era la
  // única red sin red de recuperación: su ingesta depende al 100% del webhook 'feed'
  // y un comentario no entregado se perdía para siempre. dryRun=1 POR DEFECTO: mira
  // e informa; hay que pedir dryRun=0 explícitamente para responder de verdad.
  app.post("/admin/api/fb/backfill-comments", async (req, reply) => {
    if (!(await guard(req, reply))) return;
    const q = req.query as Record<string, string>;
    const body = (json(req) ?? {}) as Record<string, unknown>;
    const pick = (k: string) => (body[k] ?? q[k]) as string | number | undefined;
    const dryRunRaw = String(pick("dryRun") ?? "1");
    const dryRun = !(dryRunRaw === "0" || dryRunRaw === "false");
    const sinceHours = Math.min(720, Math.max(1, Number(pick("sinceHours")) || 24));
    try {
      return await backfillFbCommentDrops({ sinceHours, dryRun });
    } catch (e) {
      return reply.code(500).send({ error: (e as Error).message });
    }
  });
  // RESCATE puntual: entrega el ENLACE de un flujo a UN contacto por el botón (para quien
  // pulsó pero se perdió su respuesta en un reinicio y el sondeo ya no lo alcanza).
  app.post("/admin/api/ig/deliver-flow-link", async (req, reply) => {
    if (!(await guard(req, reply))) return;
    const body = (json(req) ?? {}) as Record<string, unknown>;
    const phone = String(body.phone || "").trim();
    const flowId = String(body.flowId || body.flow_id || "").trim();
    if (!phone || !flowId) return reply.code(400).send({ error: "phone + flowId requeridos" });
    try {
      const res = await deliverIgFlowLinkTo(phone, flowId);
      return res.ok ? res : reply.code(422).send(res);
    } catch (e) {
      return reply.code(500).send({ error: (e as Error).message });
    }
  });
  // AUTO-PRUEBA de la regla de compra (sin dinero): usa un comprador REAL de otra etiqueta,
  // le crea un run de prueba y verifica que la reconciliación lo saca del flujo. Limpia solo.
  app.post("/admin/api/ig/purchase-guard-selftest", async (req, reply) => {
    if (!(await guard(req, reply))) return;
    const bd = (json(req) ?? {}) as Record<string, unknown>;
    const q = req.query as Record<string, string>;
    const tag = String(bd.tag || q.tag || "skill_autopost_compra").trim();
    const account = String(bd.account || q.account || "5d5bda96").trim();
    try {
      const { purchaseGuardSelfTest } = await import("./purchase-guard.js");
      return await purchaseGuardSelfTest(tag, account);
    } catch (e) {
      return reply.code(500).send({ error: (e as Error).message });
    }
  });
  // Opciones para el editor de acciones: etiquetas existentes, pipelines+etapas y flujos.
  /** Mapa clave→nombre de closers (para enseñar y para filtrar por responsable):
   *  Admin (env) + usuarios del panel.
   *
   *  BIZGROUPS · EQUIPO-DEL-NEGOCIO-1: los del grupo dueño del workspace ABIERTO
   *  más sus miembros, para cualquier actor. Antes el admin de entorno recibía los
   *  usuarios de TODA la plataforma (nombres y emails de otros negocios en la
   *  Bandeja, en Difusión y en lo que lee una conexión de IA). Vive aquí, y no
   *  copiado en cada endpoint, para que la Bandeja, Difusión y la analítica de
   *  leads ofrezcan exactamente la misma lista: un responsable que se pudiera
   *  elegir en una y no en la otra sería un filtro que no encuentra a nadie. */
  async function closersMap(): Promise<Record<string, string>> {
    const closers: Record<string, string> = { "env-admin": "Admin" };
    try {
      const wsId = currentWorkspaceId();
      const ws = await dbGetWorkspace(wsId);
      const users = await dbListUsersByGroup(ws?.group_id || "default");
      const ids = new Set(users.map((u) => String(u.id)));
      const fuera = (await dbListWorkspaceMembers(wsId)).filter((m) => !ids.has(String(m.user_id)));
      for (const m of fuera) { const u = await dbGetUserById(String(m.user_id)).catch(() => null); if (u) users.push(u); }
      for (const u of users) closers["u:" + u.id] = u.name || u.email;
    } catch { /* sin users */ }
    return closers;
  }

  app.get("/admin/api/flow-options", async (req, reply) => {
    if (!(await guard(req, reply))) return;
    // ETIQUETAS-SQL-1 · las etiquetas en uso salen de una agregación SQL, como en
    // /admin/api/tags. Antes se traían 2000 contactos ENTEROS (con su historial) solo
    // para leerles el campo `tags`: era el paso lento de abrir Flujos y Difusión, y
    // además mentía — con más de 2000 contactos, una etiqueta que solo tuvieran los
    // más antiguos no aparecía en el desplegable y el dueño la reescribía a mano.
    const tagSet = new Set<string>();
    for (const t of (await dbTagCounts(STAGE_TAG_PREFIX)).keys()) if (t) tagSet.add(t);
    for (const t of tagCatalog()) tagSet.add(t);
    // TAG-PICKER-1 · Incluir también las etiquetas usadas en flujos ACTIVOS (nodos addTag),
    // aunque todavía no las tenga ningún contacto. Sin esto, una etiqueta recién tecleada en un
    // flujo no aparecía en el desplegable de otros nodos → el owner la reescribía con otra grafía
    // y se fragmentaba («espera después live» vs «espera post live»). Solo flujos activos: los
    // DESACTIVADOS suelen ser backups congelados (grafías viejas ya unificadas) y no deben
    // reintroducir esas variantes muertas en el desplegable.
    for (const f of await listFlows()) {
      if (!f.enabled) continue;
      for (const n of Object.values(f.nodes || {})) {
        const t = (n as { addTag?: string }).addTag;
        if (t && !t.startsWith(STAGE_TAG_PREFIX)) tagSet.add(t);
      }
    }
    return {
      tags: [...tagSet].sort((a, b) => a.localeCompare(b)),
      // Para el filtro «Responsable» de la audiencia de Difusión.
      closers: await closersMap(),
      pipelines: getPipelines(),
      flows: (await listFlows()).map((f) => ({ id: f.id, name: f.name })),
      sequences: (await listSequences()).map((s) => ({ id: s.id, name: s.name })),
      waNumbers: listWaNumbers().map((n) => ({ id: n.phoneNumberId, label: n.label })),
      // FLUJOS-AVATAR-1 · foto de perfil de cada cuenta (misma llamada y caché de 5 min que
      // /admin/api/ig-accounts): las tarjetas de flujos «de cualquier historia/publicación» no
      // tienen miniatura de contenido y salían con un icono genérico, como si la cuenta no
      // estuviera conectada. Si Meta no contesta, avatar vacío y se queda el icono.
      igAccounts: await Promise.all(listIgAccounts().map(async (a) => {
        const { avatar } = await getIgUsernameCached(a.igId, a.token).catch(() => ({ avatar: "" }));
        return { id: a.igId, label: a.label, avatar: avatar || "" };
      })),
      // Páginas de Facebook conectadas, para el ámbito de un flujo fb_comment.
      fbPages: listFbAccountsPublic().map((p) => ({ id: p.pageId, label: p.name || p.pageId, avatar: p.pictureUrl || "" })),
      // AMBITO-YT-1 · canales de YouTube conectados, para el ámbito de un flujo
      // yt_comment. Van AQUÍ y no en /admin/api/yt-media a propósito: esa ruta pide el
      // permiso 'bots' y devuelve lista vacía si la API de YouTube falla, así que un
      // usuario con solo Flujos vería el selector vacío y al guardar ampliaría el
      // alcance del flujo a todos los canales sin enterarse.
      ytAccounts: youtubeListAccounts().map((a) => ({ id: a.id, label: a.title || a.id, avatar: a.thumb || "" })),
      // Páginas de LinkedIn conectadas, para el ámbito de un flujo li_comment (appliesTo = id de la Página).
      // Logo de la Página para la miniatura de la tarjeta (caché 6 h; con tope de 3 s para no frenar Flujos).
      liAccounts: await Promise.all(linkedinCmOrgsList().map(async (o) => ({
        id: o.orgId, label: o.name || o.orgId,
        avatar: (await Promise.race([linkedinCmOrgLogo(o.orgId), new Promise<string>((r) => setTimeout(() => r(""), 3000))]).catch(() => "")) || "",
      }))),
      // SYNC-CUENTA-1: las cuentas systeme.io REALES, para que el paso "Sincronizar"
      // pueda apuntar a UNA concreta. Antes solo se elegía la plataforma
      // ('systemeio' | 'leadmatch-lab') y, con varias cuentas de systeme.io, era
      // ambiguo: el bridge acababa cogiendo la primera de la lista (que en producción
      // es la SANDBOX del curso). `hasApiKey` dice si esa cuenta puede además ASIGNAR
      // la etiqueta (lo que dispara el workflow) o solo crear el contacto.
      sioAccounts: (await siListAccounts()).map((a) => ({
        id: a.id,
        // CORREO-ETIQUETA-1 · el resto de listas de esta misma respuesta traen
        // `label` y esta no: el filtro de canales caía a `a.id` y enseñaba
        // «Correo · 3f9a1c02» —ocho caracteres internos— a un cliente que no es
        // técnico. Mismo nombre que ya usa Contactos: el dominio de la web y, si
        // no se conoce, el correo de la cuenta.
        // CORREO-ETIQUETA-2 · el owner quiere ver EL CORREO de la cuenta, no el dominio:
        // con varias cuentas en systeme.io todas salían como «Correo · systeme.io» y no
        // se distinguían. El dominio queda de reserva para una cuenta sin correo.
        label: a.accountEmail || String(a.panelBaseUrl || "").replace(/^https?:\/\//, "").replace(/\/+$/, "") || a.label || a.id,
        email: a.accountEmail || a.label,
        panelBaseUrl: a.panelBaseUrl,
        sandbox: (a.panelBaseUrl || "").includes("leadmatch-lab"),
        hasApiKey: a.hasApiKey,
        // SIO-LIMPIEZA-1 · sin cookie desde el 30-oct-2026: el catálogo no trae agregados.
        hasCookie: false,
        // DIRECTO-2: la vía directa es el puente, que entra con correo y contraseña.
        directOk: a.hasSandboxPass,
      })),
      // NOTIFY-1: plantillas WhatsApp APROBADAS con 2+ variables, para el selector del
      // paso «Avisar a un closer». Antes ese campo era texto libre → el owner escribió
      // la frase de AYUDA como si fuera el nombre ("El lead: {{1}}=nombre…"), Meta la
      // rechazó y el aviso murió en silencio. Con un selector eso ya no puede pasar.
      // PLANTILLAS-EDITOR-1 · misma vía que el catálogo de Plantillas (/wa-templates): cuenta
      // resuelta con ensureWabaId + token del número conectado + caché compartida de 5 min.
      // Antes `listTemplates()` a secas devolvía [] EN SILENCIO si el token global estaba
      // vacío, y el editor marcaba «no válida» hasta la plantilla aprobada (15-sep-2026).
      // PLANTILLAS-EDITOR-2 · y el editor distingue «catálogo no cargado» de «0 aprobadas»:
      // `waTemplatesReason` va vacío SOLO cuando la lista es de verdad. Con motivo, el editor
      // bloquea el selector y conserva la plantilla configurada en vez de marcarla «no válida».
      // La vía estricta lanza en vez de devolver [] y el fallo no entra en la caché compartida.
      // Lo vigila scripts/test-plantillas-editor.mjs (falla si esto vuelve a dar [] con número).
      ...(await (async (): Promise<{ waTemplates: { name: string; lang: string | undefined; vars: boolean; varsN: number }[]; waTemplatesReason: string }> => {
        const token = getSetting("whatsapp.accessToken") || listWaNumbers().find((n) => n.token)?.token || "";
        if (!token) return { waTemplates: [], waTemplatesReason: "No hay ningún número de WhatsApp conectado todavía." };
        const wabaId = await ensureWabaId().catch(() => "");
        if (!wabaId) return { waTemplates: [], waTemplatesReason: CATALOGO_SIN_ACCESO };
        try {
          const cat = await cachedUpstream(upKey("wa-templates", ""), 300_000, () => listTemplatesForWabaEstricto(wabaId, token));
          return {
            waTemplates: cat
              .filter((t) => t.status === "APPROVED")
              // varsN: cuántas variables {{n}} tiene el cuerpo — el selector del
              // disparador «recordatorio» avisa si no son 2 ({{1}} motivo, {{2}} cuándo).
              .map((t) => ({ name: t.name, lang: t.language, vars: !!t.hasVar, varsN: String(t.body || "").split("{{").length - 1 })),
            waTemplatesReason: "",
          };
        } catch (e) {
          console.error("[flow-options] catálogo de plantillas no disponible:", String((e as Error)?.message || e));
          return { waTemplates: [], waTemplatesReason: motivoCatalogo(e) };
        }
      })()),
      // RECORDATORIO-FLOW-1: eventos web conocidos (nombres distintos de las
      // reservas sincronizadas) para el ámbito del disparador «recordatorio»,
      // y la zona horaria del negocio (se edita ahí mismo, es compartida).
      eventos: await (async () => {
        try {
          const bks = await dbSioBookingsRange(Date.now() - 45 * 86400000, Date.now() + 120 * 86400000);
          const out: string[] = [];
          for (const b of bks) { const e = String(b.event_name || "").trim(); if (e && out.indexOf(e) < 0) out.push(e); }
          return out.sort((a, b) => a.localeCompare(b));
        } catch { return []; }
      })(),
      tz: getSetting("biz.timezone") || "",
    };
  });

  // --- Catálogo de etiquetas (sección Etiquetas) ---
  // Lista: catálogo (definidas a mano) ∪ las que ya están en uso, con su nº de contactos.
  app.get("/admin/api/tags", async (req, reply) => {
    if (!(await guard(req, reply))) return;
    // Agregación SQL sobre TODO el tenant: antes listContacts(5000) + bucle, que
    // con >5000 contactos presentaba el conteo de la muestra reciente como total
    // (y ese número alimenta el confirm de borrado — prometía menos alcance).
    const counts = await dbTagCounts(STAGE_TAG_PREFIX);
    const cat = tagCatalog();
    const names = new Set<string>([...cat, ...counts.keys()]);
    // ETQ-04 · ETIQUETA-EN-FLUJOS-1 · qué flujos del negocio nombran cada etiqueta en su
    // configuración (tag-refs.ts). Si no se pueden leer, `flows` no viaja y la vista no
    // dice nada: jamás se deduce de los contactos que la tienen.
    let refsDe: ((n: string) => TagFlowRef[]) | null = null;
    try { refsDe = tagFlowIndex(await listFlows()); } catch (e) { console.warn("[tags] no se pudieron leer los flujos:", (e as Error).message); }
    // ETQ-06 · DESC-ETIQUETA-1 · para qué sirve (nota interna, etiquetas-desc.ts). Solo viaja si la tiene.
    const dsc = descripcionesEtiquetas();
    const tags = [...names].sort((a, b) => a.localeCompare(b)).map((name) => ({
      name,
      count: counts.get(name) || 0,
      inCatalog: cat.includes(name),
      ...(refsDe ? { flows: flujosQueLaUsan(refsDe(name)) } : {}),
      ...(dsc.has(name) ? { desc: dsc.get(name) } : {}),
    }));
    return { tags };
  });
  // Crear / renombrar / borrar una etiqueta. Body: {action:"add"|"delete"|"rename"|"desc",
  // name, newName?, desc?} — action es OBLIGATORIO ("add" crea; "rename" exige newName, el
  // nombre nuevo). Renombrar y borrar se propagan a los contactos.
  // ETQ-06 · DESC-ETIQUETA-1 · `desc` (opcional en add y rename; la acción "desc" solo cambia
  // esa nota) es para qué sirve la etiqueta: no toca contactos, flujos ni catálogo.
  app.post("/admin/api/tags", { bodyLimit: 1024 * 1024 }, async (req, reply) => {
    if (!(await guard(req, reply))) return;
    const b = json(req) ?? {};
    const action = String(b.action || "");
    if (action === "sync-systemeio") {
      const accountId = String(b.accountId || "");
      const cat0 = tagCatalog();
      // Si llega `tags` → push SELECTIVO (solo esas, sin importar de systeme.io).
      // Si no → modo "todas": catálogo + usadas por contactos, e importa de vuelta.
      const selected = Array.isArray(b.tags)
        ? [...new Set((b.tags as unknown[]).map((x) => String(x).trim()).filter(Boolean))]
        : null;
      let local: string[];
      if (selected && selected.length) {
        local = selected;
      } else {
        // Etiquetas en uso de TODO el tenant (agregación SQL, sin el cap 5000).
        const used = await dbTagCounts(STAGE_TAG_PREFIX);
        local = [...new Set([...cat0, ...used.keys()])];
      }
      try {
        const res = await syncSystemeioTags(accountId || undefined, local);
        // Solo en modo "todas" importamos las de systeme.io al catálogo local.
        if (!selected && res.pulled.length) {
          await setSetting("tags.catalog", JSON.stringify([...new Set([...cat0, ...res.pulled])]));
        }
        // FALLO-SILENCIOSO-1: si alguna etiqueta no se pudo crear, NO devolvemos ok:true.
        // 207 = éxito parcial (algunas sí, otras no); 502 = no se creó ninguna de las que
        // había que crear. El panel pinta el detalle por etiqueta en ambos casos.
        const body = {
          ok: res.failed.length === 0,
          pulled: selected ? [] : res.pulled,
          pushed: res.pushed,
          skipped: res.skipped,
          failed: res.failed,
          total: res.total,
          account: res.account,
        };
        if (res.failed.length) {
          const code = res.pushed.length ? 207 : 502;
          return reply.code(code).send(body);
        }
        return body;
      } catch (e) {
        return reply.code(502).send({ error: (e as Error).message || "no se pudo sincronizar" });
      }
    }
    const name = String(b.name || "").trim();
    if (!name) return reply.code(400).send({ error: "nombre requerido" });
    if (name.startsWith(STAGE_TAG_PREFIX))
      return reply.code(400).send({ error: "ese prefijo está reservado para etapas" });
    let cat = tagCatalog();
    if (action === "add") {
      if (typeof b.desc === "string" && (cat.includes(name) || (await dbTagCounts(STAGE_TAG_PREFIX)).has(name)))
        return reply.code(409).send({ error: "Esa etiqueta ya existe. Puedes editar su nota." });
      if (!cat.includes(name)) cat.push(name);
      await setSetting("tags.catalog", JSON.stringify(cat));
      // ETQ-06 · DESC-ETIQUETA-1 · sin `desc` no se borra la que hubiera: «Añadir a tu catálogo» también es un add.
      if (typeof b.desc === "string" && b.desc.trim()) await ponDescEtiqueta(name, b.desc);
      return { ok: true };
    }
    if (action === "desc") {
      // ETQ-06 · DESC-ETIQUETA-1 · solo la nota (tags.desc). Sobre una etiqueta que ya no existe
      // (borrada entre medias) no se deja una nota huérfana.
      if (!cat.includes(name) && !(await dbTagCounts(STAGE_TAG_PREFIX)).has(name))
        return reply.code(404).send({ error: "Esa etiqueta ya no existe: puede que la hayan borrado o renombrado hace un momento." });
      const desc = await ponDescEtiqueta(name, b.desc);
      return { ok: true, desc };
    }
    if (action === "delete") {
      // ETQ-05 · ETIQUETA-USO-1 · Nunca un borrado silencioso: si el propio panel la lee
      // (bajas, compras, métricas) o algo de la configuración la nombra (flujos,
      // difusiones, formularios…), no se borra. 409 con el motivo; el panel ya lo enseñó
      // antes con GET /admin/api/tags/uso, esto es la barrera para el Asistente y la API.
      const sis = etiquetaDeSistema(name);
      if (sis && sis.bloquea) return reply.code(409).send({ error: "«" + name + "» no se puede borrar. " + sis.motivo, sistema: sis });
      const usos = await usosDeEtiqueta(name);
      if (usos.length)
        return reply.code(409).send({ error: "«" + name + "» no se puede borrar: la usan " + resumenUsos(usos) + ". Quítala de ahí primero; si no, dejarían de funcionar como esperas.", usos });
      cat = cat.filter((t) => t !== name);
      await setSetting("tags.catalog", JSON.stringify(cat));
      await quitaDescEtiqueta(name); // ETQ-06 · DESC-ETIQUETA-1 · su nota se va con ella
      // UPDATE SQL sobre TODO el tenant: el confirm del panel promete quitarla de
      // los N contactos que la tienen; el bucle capado a 5000 cumplía menos.
      const touched = await dbRemoveTagEverywhere(name);
      return { ok: true, touched };
    }
    if (action === "rename") {
      if (!cat.includes(name) && !(await dbTagCounts(STAGE_TAG_PREFIX)).has(name))
        return reply.code(404).send({ error: "Esa etiqueta ya no existe: puede que la hayan borrado o renombrado hace un momento." });
      const nn = String(b.newName || "").trim();
      if (!nn) return reply.code(400).send({ error: "nuevo nombre requerido" });
      if (nn.startsWith(STAGE_TAG_PREFIX))
        return reply.code(400).send({ error: "ese prefijo está reservado para etapas" });
      if (nn === name) return { ok: true, touched: 0, actualizados: [], pendientes: [], errores: [] };
      // ETQ-05 · ETIQUETA-USO-1 · ni etiquetas del sistema, ni fusiones silenciosas con
      // otra que ya existe (se juntarían y no se podrían separar).
      const noSe = motivoParaNoRenombrar(name, nn, [...cat, ...(await dbTagCounts(STAGE_TAG_PREFIX)).keys()]);
      if (noSe) return reply.code(409).send({ error: noSe });
      cat = [...new Set(cat.map((t) => (t === name ? nn : t)))];
      await setSetting("tags.catalog", JSON.stringify(cat));
      // ETQ-06 · DESC-ETIQUETA-1 · la nota viaja con la etiqueta; si llega `desc`, además se cambia.
      await renombraDescEtiqueta(name, nn);
      if (typeof b.desc === "string") await ponDescEtiqueta(nn, b.desc);
      // Renombrado sobre TODO el tenant en un solo UPDATE (antes: bucle capado a 5000).
      const touched = await dbRenameTagEverywhere(name, nn);
      // Y en la configuración que la nombra por su texto. Lo que no se puede cambiar
      // solo vuelve en `pendientes`, con su motivo, para que el panel lo diga.
      const refs = await renombrarReferencias(name, nn);
      return { ok: true, touched, ...refs };
    }
    return reply.code(400).send({ error: "acción no válida" });
  });
  // ETQ-05 · ETIQUETA-USO-1 · Alcance de una etiqueta ANTES de tocarla: cuántos contactos
  // la tienen y qué configuración la nombra. Con `nuevo`, además, si se puede renombrar a
  // ese nombre y qué quedaría sin cambiar. Solo lee.
  app.get("/admin/api/tags/uso", async (req, reply) => {
    if (!(await guard(req, reply))) return;
    const q = (req.query || {}) as Record<string, unknown>;
    const name = String(q.name || "").trim();
    if (!name) return reply.code(400).send({ error: "nombre requerido" });
    const nuevo = String(q.nuevo || "").trim();
    const counts = await dbTagCounts(STAGE_TAG_PREFIX);
    const out: Record<string, unknown> = {
      nombre: name,
      contactos: counts.get(name) || 0,
      sistema: etiquetaDeSistema(name),
    };
    if (nuevo && nuevo !== name) {
      out.nuevo = nuevo;
      out.noSePuede = nuevo.startsWith(STAGE_TAG_PREFIX) ? "Ese principio de nombre está reservado para las etapas." : motivoParaNoRenombrar(name, nuevo, [...tagCatalog(), ...counts.keys()]);
    }
    out.usos = await usosDeEtiqueta(name, nuevo && nuevo !== name ? nuevo : undefined);
    return out;
  });

