  app.get("/admin/api/leadfinder/jobs/:id", async (req, reply) => {
    if (!(await guard(req, reply))) return;
    const job = await getLeadJob((req.params as { id: string }).id);
    if (!job) return reply.code(404).send({ error: "no encontrado" });
    return job;
  });
  app.get("/admin/api/leadfinder/jobs/:id/export.csv", async (req, reply) => {
    if (!(await guard(req, reply))) return;
    const job = await getLeadJob((req.params as { id: string }).id);
    if (!job) return reply.code(404).send("no encontrado");
    // CSV-FORMULA-1 · una celda que empieza por = + - @ la ejecutaría la hoja de cálculo
    // (el nombre de un negocio o un correo los escribe un tercero): se neutraliza con '.
    const esc = (s: unknown) => {
      let t = String(s ?? "").replace(/\r?\n/g, " ");
      if (/^[=+\-@]/.test(t)) t = "'" + t;
      return `"${t.replace(/"/g, '""')}"`;
    };
    const lines = ["nombre,email,web,telefono,direccion,instagram,facebook,linkedin"];
    for (const r of job.results) {
      const emails = r.emails.length ? r.emails : [""];
      for (const email of emails) {
        lines.push([
          esc(r.name), esc(email), esc(r.website), esc(r.phone), esc(r.address),
          esc(r.socials.instagram), esc(r.socials.facebook), esc(r.socials.linkedin),
        ].join(","));
      }
    }
    return reply
      .header("Content-Type", "text/csv; charset=utf-8")
      .header("Content-Disposition", `attachment; filename="leads-${job.niche}-${job.city}.csv"`)
      .send("﻿" + lines.join("\n"));
  });
  app.post("/admin/api/leadfinder/import", async (req, reply) => {
    if (!(await guard(req, reply))) return;
    const b = json(req) ?? {};
    if (!b.jobId || !Array.isArray(b.indices))
      return reply.code(400).send({ error: "jobId e indices requeridos" });
    try {
      const res = await importLeads(
        String(b.jobId),
        (b.indices as unknown[]).map((x) => Number(x)).filter((n) => Number.isInteger(n)),
        String(b.stage || ""),
      );
      return { ok: true, ...res };
    } catch (e) {
      return reply.code(400).send({ error: (e as Error).message });
    }
  });

