  // --- Sync targets (Systeme.io / leadmatch-lab) ---
  // Resuelve la CONEXIÓN elegida y deduce de ella la plataforma. Antes cada
  // endpoint recibía una plataforma suelta y, con dos cuentas conectadas en la
  // misma, el destino real dependía de a cuál llegara primero el puente.
  const webElegida = async (accountId: string) => {
    const id = String(accountId || "").trim();
    if (!id) return { error: "elige a qué web quieres mandarlos" } as const;
    const acc = (await siListAccounts()).find((x) => x.id === id);
    if (!acc) return { error: "esa web ya no está conectada" } as const;
    const sandbox = String(acc.panelBaseUrl || "").includes("leadmatch-lab");
    const target: SyncTargetId = sandbox ? "leadmatch-lab" : "systemeio";
    return { acc, target } as const;
  };
