  app.post("/admin/api/sync/lead-source", async (req, reply) => {
    if (!(await guard(req, reply))) return;
    const b = json(req) ?? {};
    const web = await webElegida(String(b.accountId || ""));
    if ("error" in web) return reply.code(400).send({ error: web.error });
    const target = web.target;
    const source = String(b.source || "");
    if (!b.jobId || !Array.isArray(b.indices))
      return reply.code(400).send({ error: "jobId e indices requeridos" });
    const getter =
      source === "hashtag" ? getHashtagJob :
      source === "x" ? getTwitterJob :
      source === "gh" ? getGithubJob : null;
    if (!getter)
      return reply.code(400).send({ error: "source inválido (hashtag | x | gh)" });
    const job = await getter(String(b.jobId));
    if (!job) return reply.code(404).send({ error: "búsqueda no encontrada" });
    const wanted = new Set((b.indices as unknown[]).map((x) => Number(x)));
    const tag = source === "hashtag" ? "ig-hashtag" : source === "x" ? "x-search" : "github";
    const leads = [];
    for (let i = 0; i < job.results.length; i++) {
      if (!wanted.has(i)) continue;
      const r = job.results[i];
      const email = (r.emails[0] || "").trim().toLowerCase();
      if (!email) continue;
      const extra: Record<string, string> = { fuente: tag };
      if (job.area) extra.keyword = job.area;
      for (const [k, vv] of Object.entries(r.socials)) extra[k] = vv;
      if (r.emails.length > 1) extra.emails = r.emails.join(", ");
      if (r.address) extra.location = r.address;
      leads.push({ email, name: r.name || "", tags: ["lead", tag], extra });
    }
    if (!leads.length) return reply.code(400).send({ error: "ningún lead seleccionado tiene email" });
    const res = await syncLeads(target, leads, web.acc.id);
    return {
      ok: true,
      target,
      enqueued: res.enqueued.length,
      skipped: res.skipped,
      job_ids: res.enqueued,
    };
  });

  // --- Autopost (carruseles multi-plataforma) ---
