  app.post("/admin/api/autopost/schedule", async (req, reply) => {
    if (!(await guard(req, reply))) return;
    const b = json(req) ?? {};
    const enabled = !!b.enabled;
    const cadence = String(b.cadence || "3xweek");
    const hour = Math.max(0, Math.min(23, Number(b.hour ?? 19)));
    const minute = Math.max(0, Math.min(59, Number(b.minute ?? 0)));
    // days: array opcional (0-6, dom=0). Si llega vacío o ausente, limpiamos
    // daysMask y se usa el preset cadence (retrocompat clientes antiguos).
    let daysClean: number[] | null = null;
    if (Array.isArray(b.days)) {
      const filtered = (b.days as unknown[])
        .map((n) => Number(n))
        .filter((n) => Number.isInteger(n) && n >= 0 && n <= 6);
      const uniq = Array.from(new Set(filtered)).sort((a, b2) => a - b2);
      if (uniq.length > 0) daysClean = uniq;
    }
    // ZONA-HORARIA-AUTOPOST-1 · aceptar zona horaria del cliente, validarla. Solo se persiste
    // si viene en la petición: si no, el programador sigue la zona del negocio (biz.timezone)
    // y no queda clavada una copia que dejaría de seguirla si el negocio cambia de zona.
    let timezone = autopostTimeZone(); // default actual
    let timezoneRecibida = false;
    if (typeof b.timezone === "string" && b.timezone.length > 0) {
      try {
        new Intl.DateTimeFormat("es", { timeZone: b.timezone }).format(new Date());
        timezone = b.timezone; // válida, usar la del cliente
        timezoneRecibida = true;
      } catch {
        // inválida, quedar con la actual
      }
    }
    await setSetting("autopost.enabled", enabled ? "true" : "false");
    await setSetting("autopost.cadence", cadence);
    await setSetting("autopost.hour", String(hour));
    await setSetting("autopost.minute", String(minute));
    await setSetting("autopost.daysMask", daysClean ? daysClean.join(",") : "");
    if (timezoneRecibida) await setSetting("autopost.timezone", timezone);
    const nextRun = enabled ? computeNextRun(cadence, hour, Date.now(), minute, daysClean, timezone) : 0;
    await setSetting("autopost.nextRun", String(nextRun));
    return { ok: true, nextRun };
  });
  // Imágenes de referencia (generar/corregir carruseles): data URLs de imagen o URLs
  // http(s). Cap a 6 y descarta lo que no sea imagen para no inflar el prompt.
  const sanitizeRefImages = (v: unknown): string[] | undefined => {
    if (!Array.isArray(v)) return undefined;
    const out = v
      .filter((x): x is string => typeof x === "string")
      .map((s) => s.trim())
      .filter((s) => /^data:image\//i.test(s) || /^https?:\/\//i.test(s))
      .slice(0, 6);
    return out.length ? out : undefined;
  };
