  // === Publicación en redes: 3 grupos (= 3 cuentas Zernio), presentado como UNA sola ===
  const zKeyOf = (blk: number): string => getSetting(ZERNIO_BLOCK_SETTING[blk] || "") || "";
  const zProfSetting = (blk: number): string => (blk === 0 ? "autopost.zernioProfileId" : `autopost.zernioProfileId${blk + 1}`);
  // Garantiza (crea/reutiliza) el profile del grupo `blk` para este workspace.
  const zernioBlockProfile = async (blk: number): Promise<{ ok: boolean; profileId?: string; error?: string }> => {
    const key = zKeyOf(blk);
    if (!key) return { ok: false, error: "Aún no has configurado este grupo de redes." };
    const ps = zProfSetting(blk);
    const stored = getSetting(ps) || "";
    let name = "Negocio";
    try { const ws = await dbGetWorkspace(currentWorkspaceId()); if (ws && ws.label) name = ws.label; } catch { /* */ }
    const ep = await zernioEnsureProfileApi(key, name, stored || undefined);
    if (ep.ok && ep.profileId && ep.profileId !== stored) await setSetting(ps, ep.profileId);
    return ep;
  };
  // Vista unificada: agrega las cuentas conectadas de TODOS los grupos configurados.
  const zernioAllChannels = async (): Promise<{ connected: ConnectedAccount[]; degraded: boolean }> => {
    const results = await Promise.all(ZERNIO_BLOCK_SETTING.map(async (sk, blk) => {
      const key = getSetting(sk) || "";
      if (!key) return { accounts: [] as ConnectedAccount[], degraded: false };
      const pid = getSetting(zProfSetting(blk)) || undefined;
      return await listZernioAccounts(key, pid, blk);
    }));
    const connected: ConnectedAccount[] = [];
    let degraded = false;
    for (const r of results) { connected.push(...r.accounts); if (r.degraded) degraded = true; }
    // X no tiene grupo de Zernio: se publica por Upload-Post (autopost/xpublish.ts). Si esa
    // cuenta tiene X conectada, entra en la vista unificada para que el Programador la dé
    // por conectada. Un fallo de Upload-Post no degrada el resto de redes.
    try {
      const up = await getActiveUpAccount();
      if (up && up.token) {
        const ux = await listConnectedAccounts(up.token, up.user);
        for (const a of ux.accounts) {
          const pl = String(a.platform || "").toLowerCase();
          if (pl === "x" || pl === "twitter") connected.push({ ...a, platform: "x" });
        }
      }
    } catch { /* best-effort */ }
    return { connected, degraded };
  };

  // Redes conectadas (estilo SSO) para una cuenta UP (?accountId=X) o vista unificada Zernio.
  app.get("/admin/api/autopost/connections", async (req, reply) => {
    if (!(await guard(req, reply))) return;
    // PERF-CACHE-1: el peor endpoint medido (7-10s contra Zernio/Upload-Post) y lo
    // llaman Carruseles Y Programador. Solo se cachean respuestas NO degradadas.
    if (apPublishProvider() === "zernio") {
      const { connected, degraded } = await cachedUpstream(
        upKey("autopost/connections", "zernio"),
        180_000,
        () => zernioAllChannels(),
        { refresh: wantsRefresh(req), staleMs: 86_400_000, cacheable: (r) => !r.degraded },
      );
      return { connected, degraded, hasToken: ZERNIO_BLOCK_SETTING.some((k) => !!getSetting(k)), provider: "zernio" };
    }
    const accountId = (req.query as Record<string, string>)?.accountId;
    const resolved = await resolveUpAccount(accountId);
    if (!resolved) return { connected: [], degraded: true, hasToken: false };
    const { accounts, degraded } = await cachedUpstream(
      upKey("autopost/connections", `up:${resolved.user || accountId || ""}`),
      180_000,
      () => listConnectedAccounts(resolved.token, resolved.user),
      { refresh: wantsRefresh(req), staleMs: 86_400_000, cacheable: (r) => !r.degraded },
    );
    return { connected: accounts, degraded, hasToken: !!resolved.token, user: resolved.user, provider: "upload-post" };
  });
  // Test de credencial(es). ?block=N testea un grupo; sin él, todos los configurados.
