    if (bq !== undefined && bq !== "") return await testZernio(zKeyOf(parseInt(bq, 10) || 0));
    const keys = ZERNIO_BLOCK_SETTING.map((k) => getSetting(k) || "").filter(Boolean);
    if (!keys.length) return { ok: false, channels: 0, error: "Aún no has configurado ninguna red." };
    const tests = await Promise.all(keys.map((k) => testZernio(k)));
    const okAny = tests.some((t) => t.ok);
