function dhWaitPermissions(){return new Promise(function(resolve,reject){var t=setTimeout(function(){var e=new Error('No se pudieron comprobar tus permisos. Vuelve a intentarlo.');e.apiUrl='/admin/api/users';reject(e);},8000);Promise.resolve(window.__navGateP).then(function(){clearTimeout(t);resolve();},function(e){clearTimeout(t);reject(e);});});}
function dhTabKey(e){if(['ArrowLeft','ArrowRight','Home','End'].indexOf(e.key)<0)return;e.preventDefault();var bs=Array.from(e.currentTarget.querySelectorAll('[data-dh-tab]'));var i=bs.indexOf(document.activeElement);i=e.key==='Home'?0:e.key==='End'?bs.length-1:(i+(e.key==='ArrowRight'?1:-1)+bs.length)%bs.length;bs[i].click();bs[i].focus();}
function dhHuman(){window.__inboxFilter={q:'',human:'true',window:'',stage:'',channel:'',account:'',tab:'human'};go('inbox');}
// COMUNIDAD-IG-1 (MET-IG-06) · los mensajes directos de Instagram no vienen en las cifras de la
