 if(d.canal==='todos'&&L.equipo)ti+=' Tu equipo añadió '+dmN(L.equipo)+(L.equipo===1?' contacto':' contactos')+' a mano, importados o con el buscador de leads: no suman aquí.';
 var ve=dhCan('metrics')||dhCan('contacts')||dhCan('inbox'),ciego=!tot&&!prev&&dmAvisoEnLeads(d)&&!!dmAvisoWebs(d);
 var pf=L.porFuente||null,ks=pf?dmFuenteOrden(pf,''):[],max=ks.reduce(function(m,k){return Math.max(m,pf[k]);},0)||1;
 var bars=ks.map(function(k){var c=pf[k],w=Math.max(2,Math.round(c/max*100)),p=tot?c/tot*100:0,pct=p>0&&p<1?'<1 %':Math.round(p)+' %',nom=dmFuenteNom(k);
  var inner='<span class=dm-bar-l>'+dmFuenteIco(k)+'<span>'+esc(nom)+'</span></span><span class=dm-bar-t><span class=dm-bar-f style="width:'+w+'%;background:var('+(DM_FUENTE_COL[k]||'--dm-s1')+')"></span></span><span class=dm-bar-n><b>'+dmN(c)+'</b><small>'+esc(pct)+'</small></span>';
  var al=' aria-label="'+esc(nom+' · '+dmN(c)+' · '+pct)+'"',desc=k==='desconocido'?DM_FUENTE_DESC+' ':'';
  return ve?'<button type=button class=dm-bar data-k="'+esc(k)+'"'+al+' title="'+esc(desc+(c===1?'Ver el contacto':'Ver los '+dmN(c)+' contactos'))+'" onclick="dmFuenteVer(this.dataset.k)">'+inner+'</button>'
   :'<div class=dm-bar'+al+(desc?' title="'+esc(desc)+'"':'')+'>'+inner+'</div>';}).join('');
 var fu=bars?'<div class=dm-fu><h4 class=dm-fu-h title="La primera fuente conocida de cada contacto nuevo, con el mismo criterio que Métricas: manda el enlace etiquetado por el que llegó y, sin él, el canal por el que nació su ficha. Registrarse en una web o escribir por WhatsApp más tarde no cambia de dónde llegó. Las barras suman el total.">De dónde llegan tus contactos</h4><div class=dm-bars>'+bars+'</div></div>':'';
