async function dmCorreoCargar(gen,my){var s=dmSt(),r=dmRango(s),d=s.data;if(!d)return;
 var days=Math.max(1,Math.ceil((r.t-r.f)/DM_DIA));
 var e=null;try{e=await api('/admin/api/analytics/email?days='+days+'&from='+r.f+'&to='+r.t+'&dfrom='+mxISODia(r.f)+'&dto='+mxISODia(r.t));}catch(_){e=null;}
 if(!viewAlive(gen)||my!==s.seq)return;var el=document.getElementById('dm_correo');if(!el)return;
 var sm=e&&e.summary,vacio='',cta='',serie=d.dias.map(function(){return 0;}),ap=d.dias.map(function(){return null;});
 if(sm&&Array.isArray(sm.byDay)){var ix={};d.dias.forEach(function(k,i){ix[k]=i;});
  sm.byDay.forEach(function(x){var i=ix[String(x.date||'').slice(0,10)];if(i!==undefined){serie[i]+=Number(x.sent)||0;ap[i]=x.sent?Number(x.openedPct)||0:null;}});}
 // DASH-SOBRIO-1 · un fallo de la petición no es «no tienes correo»: antes decía «Conecta tu cuenta»
 // a quien ya la tenía conectada. Y «no ha respondido» lleva su «Reintentar», no «vuelve en un rato».
 var fallo=!e||e.ok===false;
 if(!fallo&&(e.hasAny===false||(!sm&&!(e.accounts||[]).length))){vacio='Conecta tu cuenta de correo y verás cuántos correos envías y cuántos se abren.';if(dhCan('connections'))cta=dmAcc('Conectar el correo','dmCon','systeme');}
 else if(!sm){var cad=!fallo&&!!e.expired;vacio=cad?'La conexión con tu cuenta de correo ha caducado. Vuelve a conectarla para ver los envíos.':'Tu cuenta de correo no ha respondido. Suele ser algo momentáneo.';cta=cad?(dhCan('connections')?dmAcc('Volver a conectar','dmCon','systeme'):''):dmAcc('Reintentar','dmCorreoReintentar','');}
 else if(!sm.totalSent)vacio='No se enviaron correos en estas fechas.';
 var extra=sm&&sm.totalSent?dmFacts([{l:'Apertura',v:dmN1(sm.openRatePct||0)+' %',ti:'De cada 100 correos entregados, cuántos se abrieron'},sm.bounceRatePct!=null?{l:'Rebotados',v:dmN1(sm.bounceRatePct)+' %',ti:'Correos que no llegaron a entregarse'}:null]):'';
 var html=dmCard({id:'correo',elId:'dm_correo',ic:'mail',title:'Correo',ti:'Envíos de tus campañas y newsletters en estas fechas.',
  big:sm?dmN(sm.totalSent||0):'—',bigLbl:sm?'enviados':'',extra:extra,
  chart:{keys:d.dias,series:[{name:'Enviados',vals:serie,color:'--ch',fmt:dmN}],type:'area',h:166,
   tipExtra:function(i,agg){if(agg)return '';var v=ap[i];return v==null?'':dmN1(v)+' % de apertura';}},
  vacio:vacio,cta:cta,foot:sm&&sm.totalSent?dmPieMx('Ver las métricas del correo','correo'):''});
 var cls=el.className;el.outerHTML=html;el=document.getElementById('dm_correo');if(el)el.className=cls;var c=document.querySelector('.dm-chart[data-dmc="correo"]');if(c){dmDraw(c,true);if(window.__dmRO)window.__dmRO.observe(c);}}
function dmCardWa(d){var W=d.whatsapp,vacio='',cta='',nd=d.dias.length||1;
 if(!W.conectado){vacio='Conecta tu línea de WhatsApp y verás aquí los mensajes que recibes y envías cada día.';if(dhCan('connections'))cta=dmAcc(netIco('whatsapp')+'Conectar WhatsApp','dmCon','whatsapp');}
 else if(!W.in&&!W.out&&!W.prevIn&&!W.prevOut)vacio='Sin mensajes en estas fechas.';
 var fs=[{l:'Enviados',v:dmN(W.out),ti:'Mensajes que enviaste tú, tus automatizaciones o tus difusiones. Frente a '+dmN(W.prevOut||0)+' en los días anteriores.'},{l:'Recibidos al día',v:dmN1(W.in/nd),ti:'Mensajes recibidos por día, de media'}];
 // DASH-07-CAMPANAS-1 · son mensajes, no conversaciones ni campañas: el title lo dice y remite a «Campañas».
 return dmCard({id:'wa',icHtml:netIco('whatsapp'),title:'Mensajes de WhatsApp',ti:'Mensajes de texto de tus líneas de WhatsApp, la oficial y las conectadas con código QR. Cuenta mensajes, no personas ni conversaciones: diez mensajes de una misma persona son diez. Los recibidos incluyen las respuestas a tus difusiones, que esta cifra no puede separar'+(dmVeCampanas(d)?'; tus difusiones se miden aparte, en «Campañas de WhatsApp»':'')+'. No cuenta fotos, audios ni lo que escribes desde el propio móvil.',
  big:dmN(W.in),bigLbl:'mensajes recibidos',delta:dmDelta(W.in,W.prevIn),sinDato:!W.conectado,prev:dmPrevTxt(d,dmN(W.prevIn)),extra:dmFacts(fs),
  chart:{keys:d.dias,series:[{name:'Recibidos',vals:W.serieIn||[],color:'--dm-wa',fmt:dmN},{name:'Enviados',vals:W.serieOut||[],color:'--dm-out',fmt:dmN}],type:'line',h:166},
  // Sin ninguna línea conectada, Métricas diría «sin conectar»: el pie ofrece reconectarla aquí mismo.
  vacio:vacio,cta:cta,foot:!W.conectado?'':W.lineas===0?(dhCan('connections')?dmPie('Vuelve a conectar WhatsApp','dmCon','whatsapp','Tu línea está desconectada: lo de arriba son los mensajes que ya tenías'):''):dmPieMx('Ver las métricas de WhatsApp','wa')});}
// DASH-07-CAMPANAS-1 · «Campañas de WhatsApp»: cada difusión que salió en estas fechas es una campaña, con quién
// respondió y quién compró después, con las reglas de Métricas › WhatsApp (RESULTADO-DIFUSION-1). Va aparte de
// «Mensajes de WhatsApp», que cuenta mensajes y no puede separar las respuestas a una difusión. Se carga sola
