 if(L&&L.porCanal)fs.push({l:'Contactos nuevos',v:dmN(Number(L.porCanal.web)||0),ti:'Personas que dejaron sus datos por primera vez en un formulario de tus webs en estas fechas y no conocías de antes.'});
