 if(card.id==='dm_feed'){if(k!=='ArrowLeft'&&k!=='ArrowRight')return;e.preventDefault();
  var s=dmSt(),l=k==='ArrowLeft'?'izq':'der';if(s.feedLado!==l&&dmDosColumnas()){s.feedLado=l;dmSave('disp');dmFeedLado();dmResetBtn();}return;}
 var dir=(k==='ArrowLeft'||k==='ArrowUp')?-1:((k==='ArrowRight'||k==='ArrowDown')?1:0);if(!dir)return;e.preventDefault();
 var t=dir<0?card.previousElementSibling:card.nextElementSibling;if(!t||!t.hasAttribute('data-dmcard'))return;
