 // ahora solo si su bloque trae algo, y si no queda ninguno la pestaña lo explica en
 // vez de dejar el hueco en blanco.
 // (Sin comillas invertidas en este comentario: vive DENTRO de APP_HTML.)
 var _hayQuick=quickRow.indexOf('dh-qa')>=0;
 var _hayHub=hubGrid.indexOf('dh-hub-card')>=0;
 var _herramientasHtml=(_hayQuick?'<h4 class=dh-sec-h>Acciones rápidas</h4>'+quickRow:'')
  +(_hayHub?'<h4 class=dh-sec-h>Todo lo que puedes hacer</h4>'+hubGrid:'')
  +((_hayQuick||_hayHub)?'':empty({ic:'lock',title:'Tu acceso no incluye estas herramientas',body:'Quien administra tu negocio puede ampliarte el acceso cuando lo necesites.'}))
