 v.innerHTML=H(titulo,sub,'<button type=button class="sec gh" id=ntfAllBtn onclick="ntfMarkAll()" title="Marca como leídas todas las notificaciones de este negocio">'+ICN('check')+'Marcar todo como leído</button>')
