// Copia el evento COMPLETO tal y como lo sirvió el servidor (ya redactado:
// secretos y contacto enmascarados en lectura) — no hay nada sensible aquí.
function actCopyTech(idEnc){
 var id=decodeURIComponent(idEnc);
 var f=window.__act;
 var e=(f&&f.byId?f.byId:{})[id];
 if(!e){ toast('Evento no disponible','err'); return; }
 var iso=''; try{ iso=new Date(Number(e.created_at)).toISOString(); }catch(_){ iso=String(e.created_at||''); }
 var data={ id:e.id, fecha:iso, fuente:e.source, nivel:e.level, estado:e.status, resumen:e.summary, datos:e.payload };
 var txt=''; try{ txt=JSON.stringify(data,null,2); }catch(_){ txt=String(data); }
 var okFn=function(){ toast('Copiado al portapapeles','ok'); };
 var koFn=function(){ toast('No se pudo copiar','err'); };
 try { if(navigator.clipboard&&navigator.clipboard.writeText){ navigator.clipboard.writeText(txt).then(okFn,koFn); return; } } catch(_){}
 try { var ta=document.createElement('textarea'); ta.value=txt; document.body.appendChild(ta); ta.select(); document.execCommand('copy'); ta.remove(); okFn(); } catch(_){ koFn(); }
}
// POST mark-seen tras render: limpia el badge "no vistos" en la NAV.
async function actMarkSeen(){
 try {
  await fetch('/admin/api/activity/mark-seen',{
   method:'POST',
   headers:{'Content-Type':'application/json'},
   body:JSON.stringify({timestamp:Date.now()}),
  });
  // Tras marcar como vistos: refresca badge inmediatamente (irá a 0).
  refreshActivityBadge();
 } catch(_) {}
}
// Polling badge: cada 30s pide counters y pinta unseenCount + dot rojo si >0.
async function refreshActivityBadge(){
 if (document.hidden) return;
 if (!window.__isEnv) return; // Actividad es env-only (lvl 2): solo el super-operador la sondea
 try {
  var d = await api('/admin/api/activity/counters',{nocache:true});
  var el = document.getElementById('nc_activity'); if(!el) return;
  var n = Number(d&&d.unseenCount)||0;
  if (n > 0) {
   var txt = n > 99 ? '99+' : String(n);
   var antes = Number(el.dataset.n||0); el.dataset.n = String(n); // HONESTIDAD-3: relanza el pulso solo si sube
   if (n > antes && el.classList.contains('nc-alert')) { el.classList.remove('nc-alert'); void el.offsetWidth; }
   el.textContent = txt;
   el.classList.add('nc-alert');
  } else {
   el.textContent = ''; el.dataset.n = '0';
   el.classList.remove('nc-alert');
  }
 } catch(_) {}
}
