 var cl=document.getElementById('nwc_clear');if(cl)cl.style.display=(nn>1?'':'none'); // LIMPIAR-LOTE-1
 var inp=document.getElementById('nwc_loteNew');if(inp)inp.placeholder=nn?'añadir otro…':'+34 600 11 22 33, Ana';
