// Añade entradas (texto de una o varias líneas) deduplicando por los dígitos
// del teléfono: pegar dos veces la misma lista no duplica cajitas. El tope de
// 500 se corta AQUÍ, avisando de cuántos quedan fuera: dejar entrar 520 y
// negarse en «Comprobar» era un callejón sin salida de 20 aspas.
function nwcLoteMete(txt){
 var arr=nwcLoteArr();
 var clave=function(l){var ix=l.search(/[,;]/);return (ix<0?l:l.slice(0,ix)).replace(/[\\s\\-.()]/g,'');};
 var vistas={};arr.forEach(function(l){vistas[clave(l)]=1;});
 var n=0,dup=0,fuera=0;
 String(txt||'').split(/\\r?\\n/).map(function(l){return l.trim();}).filter(Boolean).forEach(function(l){
  var k=clave(l);
  if(!k)return;
  if(vistas[k]){dup++;return;}
  if(arr.length>=500){fuera++;return;}
  vistas[k]=1;arr.push(l);n++;
 });
 if(n)nwcLoteGuarda(arr);
 if(fuera)toast('El lote admite 500 como mucho|'+(fuera===1?'1 se ha quedado fuera':fuera+' se han quedado fuera'),'err');
 return {n:n,dup:dup,fuera:fuera};
}
function nwcLoteAdd(){
 var inp=document.getElementById('nwc_loteNew');if(!inp||!inp.value.trim())return;
 var txt=inp.value;inp.value='';
 nwcLoteMete(txt);
}
function nwcLoteDel(ev,i){
 if(ev)ev.stopPropagation();
 var arr=nwcLoteArr();
 if(i<0||i>=arr.length)return;
 arr.splice(i,1);
 nwcLoteGuarda(arr);
}
function nwcLoteTecla(e){
 if(e.key==='Enter'){e.preventDefault();nwcLoteAdd();return;}
 if(e.key==='Backspace'&&!e.target.value){
  var arr=nwcLoteArr();
  if(arr.length){e.preventDefault();arr.pop();nwcLoteGuarda(arr);}
 }
}
// Un pegado multilínea se convierte en cajitas al momento (los navegadores
// aplastan los saltos de línea al pegar en un input: hay que interceptarlo).
function nwcLotePega(e){
 var cb=e.clipboardData||window.clipboardData;
 var txt=cb&&cb.getData?String(cb.getData('text')||''):'';
 if(txt.indexOf(String.fromCharCode(10))<0)return;
 e.preventDefault();
 var inp=document.getElementById('nwc_loteNew');
 var pend=inp?inp.value:'';if(inp)inp.value='';
 var r=nwcLoteMete((pend.trim()?pend+String.fromCharCode(10):'')+txt);
 if(r.n)toast('Lista pegada|'+(r.n===1?'1 teléfono':r.n+' teléfonos')+(r.dup?(' · '+(r.dup===1?'1 ya estaba':r.dup+' ya estaban')):''),'ok');
 else if(r.dup)toast('Ya estaban en la lista','ok');
}
function nwcLoteFoco(e){if(e&&e.target&&e.target.closest&&e.target.closest('.fx-kwchip'))return;
 var i=document.getElementById('nwc_loteNew');if(i)i.focus();}
