function nwcPollLote(id,total){
 if(window.__nwcPoll)clearInterval(window.__nwcPoll);
 window.__nwcPoll=setInterval(async function(){
  var r=await api('/admin/api/broadcasts?limit=100',{nocache:true}).catch(function(){return null;});
  var fila=((r&&r.broadcasts)||[]).filter(function(x){return x.id===id;})[0];
  if(!fila)return;
  var hechosL=(fila.sent||0)+(fila.failed||0);
  if(fila.status==='sending'){
   var pi=document.getElementById('nwc_progi');if(pi)pi.style.width=Math.min(100,Math.round(100*hechosL/Math.max(1,total)))+'%';
   var pt=document.getElementById('nwc_progt');if(pt)pt.textContent=hechosL+' de '+total;
   return;
  }
  clearInterval(window.__nwcPoll);window.__nwcPoll=null;
  toast(fila.status==='sent'?('Lote aceptado|'+fila.sent+' enviados · '+fila.failed+' fallos'):('Lote terminado: '+fila.status),(fila.status==='sent'&&!fila.failed)?'ok':'err');
  nwcClose();
  window.__inboxSig='';try{inboxRefresh();}catch(_){}
 },2000);
}
