function emojiToWebp(emoji){
 return new Promise(function(resolve,reject){ try{
  var sz=512; var cv=document.createElement('canvas'); cv.width=sz; cv.height=sz;
  var ctx=cv.getContext('2d'); ctx.clearRect(0,0,sz,sz);
  ctx.font='384px "Apple Color Emoji","Segoe UI Emoji","Noto Color Emoji",sans-serif';
  ctx.textAlign='center'; ctx.textBaseline='middle'; ctx.fillText(emoji,sz/2,sz/2+24);
  cv.toBlob(function(b){ if(!b){ reject(new Error('sin blob')); return; } resolve(b); },'image/webp',0.92);
 }catch(e){ reject(e); } });
}
function blobToB64(blob){ return new Promise(function(res,rej){ var rd=new FileReader(); rd.onload=function(){ res(String(rd.result||'').replace(/^data:[^;]+;base64,/,'')); }; rd.onerror=rej; rd.readAsDataURL(blob); }); }
async function sendSticker(emoji){
 var p=window.__chatOpen; if(!p){ return; }
 var thr=document.querySelector('#chat .thread');
 var tmpId='tmpmsg_'+(window.__tmpSeq=(window.__tmpSeq||0)+1);
 if(thr){ thr.insertAdjacentHTML('beforeend','<div class="msg out first last pending has-media sticker-msg" id="'+tmpId+'"><span class=msg-sticker>'+esc(emoji)+'</span><span class=msg-meta>'+mtime(Date.now())+'<span class="msg-ck waiting" title="Enviando…">🕓</span></span></div>'); thrScrollBottom(thr); }
 try{
  var blob=await emojiToWebp(emoji);
  var b64=await blobToB64(blob);
  var isWebp=(blob.type||'').indexOf('webp')>=0;
  var r=await post('/admin/api/reply',{phone:p,media:{ name:'sticker.webp', mime:isWebp?'image/webp':'image/png', kind:isWebp?'sticker':'image', dataB64:b64 },...(window.__chatAcct&&String(window.__chatAcct).indexOf('wa:')===0?{acct:window.__chatAcct}:{})});
  if(!r||r.error){ throw Object.assign(new Error((r&&r.error)||'rechazado'),{detalle:r&&r.detalle}); }
  var el=document.getElementById(tmpId);
  if(el){ var ck=el.querySelector('.msg-ck'); if(ck){
   if(r.accepted&&r.wamid){ck.textContent='🕓';ck.title=(r.transport==='qr'?'Enviado desde tu WhatsApp; esperando confirmación de entrega':'Aceptado por Meta; esperando confirmación de envío');}
   else{el.classList.remove('pending');ck.textContent='✓';ck.title=ixCkTitle();}
  } }
  window.__chatSig=''; if(typeof chatRefresh==='function') chatRefresh();
 }catch(e){
  var el2=document.getElementById(tmpId);
  if(el2){ el2.classList.remove('pending'); el2.classList.add('failed'); var mt=el2.querySelector('.msg-meta'); if(mt){ mt.innerHTML='no enviado <span class=msg-ck>⚠</span>'; if(e&&e.detalle) mt.title='Motivo técnico: '+e.detalle; } }
  toast('Error|No se pudo enviar el sticker'+(e&&e.message?' · '+e.message:''),'err');
 }
}
// Al mover de etapa se ASIGNA también el pipeline que la cabecera está enseñando.
// Sin eso el contacto se quedaba «sin pipeline» para siempre y solo aparecía en el
// primer tablero por descarte, aunque le hubieras puesto una etapa a mano.
async function setStageFromChat(pEnc,stage){
 var p=(pEnc.indexOf('%')>=0)?decodeURIComponent(pEnc):pEnc;
 // El desplegable de pipeline vive ahora en el menú «⋯» y no siempre está en el
 // DOM. Cuando no está manda el pipeline REAL de este chat (__chatPipeId), no el
 // primero de la lista: mover de etapa no puede cambiarte de tablero a escondidas.
 var sp=document.querySelector('.chd-pipe');
 var pid=sp?sp.value:(window.__chatPipeId||((pipesGet()[0])||{}).id||'');
 // Quitar la etapa NO asigna tablero: apuntar a alguien a un pipeline porque has
 // vaciado un desplegable sería inventarse una decisión que nadie ha tomado.
 var r=await post('/admin/api/stage',stage?{phone:p,stage:stage,pipeline_id:pid}:{phone:p,stage:''});
 if(r&&r.error){ toast('No se pudo mover|'+String(r.error).slice(0,110),'err'); return; }
 toast(stage?('Movido a '+stage):'Etapa quitada','ok');
 openChat(encodeURIComponent(p));
}
// Cambiar de PIPELINE desde el chat. La etapa solo sobrevive si existe también en
// el tablero nuevo: llevársela a uno donde no existe deja al lead sin columna en
// ninguno de los dos, que es la avería que el propio Pipeline llama «fuera de etapa».
async function setPipeFromChat(pEnc,pipeId){
 var p=(pEnc.indexOf('%')>=0)?decodeURIComponent(pEnc):pEnc;
 var np=pipesGet().filter(function(x){return x.id===pipeId;})[0];
 if(!np){ toast('Ese pipeline ya no existe','err'); return; }
 var se=document.querySelector('.chd-stage');
 var cur=se?se.value:'';
 var mantiene=(np.stages||[]).indexOf(cur)>=0;
 var r=await post('/admin/api/stage',{phone:p,stage:mantiene?cur:'',pipeline_id:pipeId});
 if(r&&r.error){ toast('No se pudo cambiar de pipeline|'+String(r.error).slice(0,110),'err'); openChat(encodeURIComponent(p)); return; }
 // Perder la etapa al cambiar de tablero se DICE. En silencio se lee como que el
 // panel ha perdido el dato.
 toast(mantiene?('Movido a «'+np.name+'» · '+cur)
  :('Movido a «'+np.name+'»|'+(cur?('«'+cur+'» no es una etapa de este pipeline: elígele una.'):'Ponle una etapa para que aparezca en el tablero.')),'ok');
 openChat(encodeURIComponent(p));
}
// Borra una conversación de la bandeja (limpiar pruebas/spam). El contacto permanece en Contactos.
async function deleteConv(pEnc, nameEnc){
 var p=(pEnc.indexOf('%')>=0)?decodeURIComponent(pEnc):pEnc;
 var name=nameEnc?decodeURIComponent(nameEnc):p;
 var ok=await confirmAct({title:'¿Borrar conversación?', body:'La conversación con «'+name+'» desaparecerá de la bandeja. El contacto, si existe, seguirá en Contactos. No se puede deshacer.', ok:'Sí, borrar'});
 if(!ok) return;
 var r=await api('/admin/api/inbox/'+encodeURIComponent(p),{method:'DELETE'}).catch(function(){return {};});
 if(r&&r.ok){ toast('Conversación borrada','ok'); window.__inboxSig=''; rInbox(); }
 else toast('Error|'+((r&&r.error)||'no se pudo borrar'),'err');
}
// ── Bandeja en vivo (casi tiempo real, sin F5) ──────────────────────────────
// La lista se refresca cada 5 s y la conversación abierta cada 3 s, de forma
// quirúrgica: NO recrea la vista, así no pierdes lo que escribes, ni el scroll,
// ni se cierra el chat. Se pausa sola cuando la pestaña está en segundo plano
// (document.hidden) y al salir de la Bandeja (go() llama a ixTeardown).
function ixInboxQs(){ return ixQs(); }
// CHAT-POR-NUMERO-1 (rev. 2-sep) · con chats partidos, «abierto» es el par telefono+
// cuenta; acct null (enlaces antiguos) casa con todas las filas del telefono.
function ixMarkActive(p,acct){ try{ document.querySelectorAll('.ix-conv').forEach(function(el){ var ok=el.getAttribute('data-ph')===p&&(acct==null||String(el.getAttribute('data-acct')||'')===String(acct)); el.classList.toggle('on', ok); }); }catch(_){} }
async function inboxRefresh(){
 if(document.hidden) return;
 if(navKeyFromHash()!=='inbox'){ ixStopList(); return; }
 var listEl=document.querySelector('.ix-list'); if(!listEl) return;
 // nocache: este refresco DEBE traer datos frescos (lo dispara el push SSE / el poll).
 // Sin esto, api() servía la respuesta cacheada (TTL 30s) y el mensaje nuevo no aparecía.
 // LISTA-AL-DIA-1 (BAN-01) · si la selección cambió mientras llegaba, esta respuesta ya no vale.
 var __qs=ixInboxQs(), __rs=window.__ixRSeq;
 var d; try{ d=await api('/admin/api/inbox?'+__qs,{nocache:true}); }catch(_){ return; }
 if(!d || __qs!==ixInboxQs() || __rs!==window.__ixRSeq) return;
 window.__ixMe = d.me||window.__ixMe||{}; window.__ixClosers = d.closers||window.__ixClosers||{};
 if(d.bots){ window.__ixAccts = ixBuildAccts(d.bots); window.__ixBots = d.bots; }
 // NEGOCIOS-BANDEJA-1 · un negocio o una cuenta que desaparece mientras miras: se repinta entero.
 if(ixSelAjustar(d)){ rInbox(); return; }
 window.__ixEtapas = (d.filters && d.filters.etapas) || window.__ixEtapas || [];
 var f=window.__inboxFilter||{};
 // BANDEJA-LEIDOS-1 · los contadores van APARTE de la lista: mirando WhatsApp, un
 // Instagram nuevo no cambia la lista pero sí el número de su pestaña y el del menú.
 var cnt=d.counts||{};
 window.__ixCounts = cnt; ixNavUnread(cnt.unreadAll);
 var csig=JSON.stringify(cnt);
 if(csig!==window.__ixCountsSig){
  window.__ixCountsSig=csig;
  var zoneEl=document.querySelector('.ix-zone-channel'); if(zoneEl) zoneEl.innerHTML=ixFilaSel(cnt);
  if(document.getElementById('ixFiltPop')) ixFiltPintar();
 }
 var sig=ixListSig(d); if(sig===window.__inboxSig) return;   // nada cambió → no repintes
 window.__inboxSig=sig;
 var sc=listEl.scrollTop;
 listEl.innerHTML = ixBuildList(d) || ixVacio(f);
 listEl.scrollTop=sc;                                          // conserva el scroll de la lista
 // BANDEJA-LEIDOS-1 · la lista cambió: el chat abierto se pone al día YA, sin esperar a
 // su propio turno. Antes la vista previa de la izquierda enseñaba el mensaje nuevo
 // segundos antes que el propio chat. chatRefresh no repinta si no hay nada nuevo.
 if (window.__chatOpen) chatRefresh();
}
// BANDEJA-LEIDOS-1 · número del menú lateral = chats sin leer (lo mismo que la pestaña «Todos» sin filtros).
function ixNavUnread(n){ if(n==null)return; if(typeof dmPendPintar==='function')dmPendPintar(Number(n)||0); var el=document.getElementById('nc_inbox'); if(!el)return; n=Number(n)||0; el.textContent=n>0?(n>99?'99+':String(n)):''; el.title=n>0?ixSinLeerTxt(n)+' en los negocios y canales que ves en la Bandeja, sin contar el buscador ni los filtros':''; window.__navUnread=n; } // BAN-08-UNIDAD-1
// Marca como leído el chat que se está mirando. Sin cuenta (abierto desde fuera de la
// Bandeja) vale para todos los chats de esa persona.
function ixMarcarLeido(p, acct){
 var b={phone:p}; if(acct!=null) b.acct=String(acct);
 // CONTADOR-AL-LEER-1 (BAN-01) · /inbox/read no emite SSE: sin esto el número del menú, el
 // de cada negocio y el de cada canal seguían contando el chat recién abierto hasta el
 // siguiente sondeo (6-15 s). Mismo refresco que «Marcar todo como leído».
 return post('/admin/api/inbox/read', b).then(function(r){
  if(!r||!r.ok) return;
  if(navKeyFromHash()==='inbox'){ window.__ixCountsSig=null; inboxRefresh(); }
  else { window.__navUnreadAt=0; refreshInboxUnread(); }
 }).catch(function(){});
}
// WA-QR-ANTERIORES-1 · pide al móvil los 50 mensajes anteriores al más antiguo del chat.
// Lo que llegue lo repinta chatRefresh por SSE; el servidor frena las repeticiones.
async function ixCargarAnteriores(b){
 var p=window.__chatOpen;if(!p||!b||b.disabled)return;
 var t0=b.innerHTML;b.disabled=true;b.textContent='Pidiendo al móvil…';
 var acct=(window.__chatAcct&&String(window.__chatAcct).indexOf('wa:')===0)?window.__chatAcct:'';
 var r=await post('/admin/api/inbox/'+encodeURIComponent(p)+'/anteriores',{acct:acct});
 if(!r||!r.ok){toast((r&&r.error)||'No se pudo pedir al móvil.',r&&r.__httpStatus===429?'warn':'err');b.disabled=false;b.innerHTML=t0;return;}
 if(r.nuevos>0){toast('Mensajes anteriores cargados|Han llegado '+r.nuevos+(r.nuevos===1?' mensaje':' mensajes')+' del móvil.');chatRefresh();}
 else if(!r.respondio)toast('El móvil no ha contestado|Comprueba que el teléfono está encendido y con internet, y vuelve a probar.','warn');
 else if(r.recibidos>0)toast('Ya estaba todo|El móvil ha mandado mensajes que ya tenías aquí.','warn');
 else toast('No hay mensajes anteriores|El móvil no conserva nada anterior de este chat.','warn');
 b.disabled=false;b.innerHTML=t0;
}
async function chatRefresh(){
 if(document.hidden) return;
 var p=window.__chatOpen; if(!p) return;
 var threadEl=document.querySelector('#chat .thread');
 if(!threadEl){
  // Con el esqueleto pintado hay una apertura EN VUELO: no tocar el estado del chat
  // (anular __chatAcct aqui hacia que la respuesta saliera por otro numero, rev. 2-sep).
  if(!document.querySelector('#chat .ix-chskel')){ window.__chatOpen=null; window.__chatAcct=null; window.__chatChan=null; ixStopChat(); }
  return;
 }
 // nocache: la conversación abierta es lo que el usuario mira de cerca → siempre fresco.
 // CHAT-POR-NUMERO-1 · el refresco respeta el chat (número) abierto.
 var __aq=(window.__chatAcct&&String(window.__chatAcct).indexOf('wa:')===0)?('?acct='+encodeURIComponent(window.__chatAcct)):'';
 // BANDEJA-LEIDOS-1 · el SSE, el temporizador y el envío lanzan refrescos que se solapan:
 // si la respuesta de uno VIEJO llegaba la última, repintaba el hilo sin el mensaje nuevo
 // (y la lista ya lo enseñaba). Sólo pinta la petición más reciente, y del chat abierto.
 var __seq=(window.__chatReqSeq=(window.__chatReqSeq||0)+1);
 var d; try{ d=await api('/admin/api/inbox/'+encodeURIComponent(p)+__aq,{nocache:true}); }catch(_){ return; }
 if(!d || __seq!==window.__chatReqSeq || window.__chatOpen!==p) return;
 threadEl=document.querySelector('#chat .thread'); if(!threadEl) return;
 var turns=d.turns||[];
 var sig=ixTurnsSig(turns);
 // BAN-04-FIN · el modo de la cabecera sigue a la fila de la lista (se refresca sola): si el
 // flujo termina por sí solo y pasa al asistente IA, la cabecera lo dice sin reabrir el chat.
 ixModoSync(p);
 if(sig===window.__chatSig) return;                            // sin mensajes nuevos
 window.__chatSig=sig;
 // Lo estás mirando: lo que acaba de entrar ya está leído.
 var __ult=turns[turns.length-1];
 if(__ult&&__ult.role==='user'&&!document.hidden) ixMarcarLeido(p, window.__chatAcct);
 var nearBottom=(threadEl.scrollHeight-threadEl.scrollTop-threadEl.clientHeight)<80;
 threadEl.innerHTML = renderThread(turns);
 ogHydrateAll(threadEl);                                       // OG-INBOX-1: tarjetas de enlace
 if(nearBottom) thrScrollBottom(threadEl);                     // autoscroll solo si ya estabas abajo
}
