function ixTeardown(){ ixStopList(); ixStopChat(); chdMenuClose(); rxPopClose(); ixFiltCerrar(); ixAcctPopClose(); window.__chatOpen=null; window.__chatAcct=null; window.__chatChan=null; setTimeout(ixTopbar,0); }
// REVISION-PREMIUM-1 · volver a la lista (móvil/tablet): se quita el chat de en medio y se para su refresco.
