 var totReal=(d.totalAll!=null?Number(d.totalAll):(d.contacts||[]).length);
 var tabla='<div class="card ct-tarjeta">'+pgTable({id:'crmcontacts',dateKeys:[{key:'last_inbound',label:'Último mensaje recibido'},{key:'created_at',label:'Añadido a Contactos'}],dateAviso:'El rango se aplica a todos tus contactos, no solo a los de esta página.',rows:d.contacts||[],per:25,keepPage:true,remote:{total:totReal,cb:'ctPage'},renderRow:ctRow,sortKey:'last_inbound',sortDir:'desc',columns:cols,tableClass:'ct-tbl'+(cc.vis.web?' ct-tbl-web':''),empty:empty({ic:'users',title:'Todavía no tienes contactos',body:'Aparecen solos en cuanto alguien te escriba por WhatsApp, Instagram o Facebook. También puedes añadir uno a mano.',ctaLabel:'Añadir contacto',ctaAction:'openNewContact()'})})+'</div>';
 // DISENO-1 · BANDEJ-08 · las columnas que se ocultan por anchura (CSS) también se dicen; la nota solo se ve cuando aplica.
