 var p=(ix>=0?prods[ix]:null)||d.product||null;
 var huerfano=(!p);
 var tp=huerfano?null:payTipo(p);
 // ENL-05-PERMISOS-1 · lo que la persona puede hacer con lo que ve: cambiar el catálogo, ver los datos
