 var puede=(d.puede_editar!==false)&&(pd.puede_editar!==false);
 var verContactos=(d.contactos!==false);
 var ficha=verContactos&&dhCan('contacts');
 var sinGuardar=(!huerfano&&ix>=0&&!!window.__payBase&&!(pid in window.__payBase));
 var st=null,sts=pd.stats||[]; for(var j=0;j<sts.length;j++) if(sts[j].id===(huerfano?'__sin_identificar__':pid)) st=sts[j];
 var gente=d.gente||[];
 var sinC=d.sin_contacto||{n:0,importe:0,moneda:''};
