 var savedContacts=window.__navListContext&&window.__navListContext.crmcontacts;
 if(savedContacts){
  window.__pg=window.__pg||{};
  window.__pg.crmcontacts=Object.assign({},window.__pg.crmcontacts||{},savedContacts);
  delete window.__navListContext.crmcontacts;
 }else if(window.__pg&&window.__pg.crmcontacts)window.__pg.crmcontacts.page=1;
 var d=await api('/admin/api/contacts'+ctQs(f));
 if(!viewAlive(_gen))return;
 window.__ctData=d;
