function contactsSearch(q){ window.__contactsFilter.q = q; clearTimeout(__contactsSearchT); __contactsSearchT = setTimeout(ctApply, 250); }
function contactsSetStage(s){ window.__contactsFilter.stage = s; ctApply(); }
