function contactsSetCompra(v){ window.__contactsFilter.compra = v?'1':''; ctApply(); }
function contactsSetMsgs(v){ window.__contactsFilter.msgs = (v==='con'||v==='sin')?v:''; ctApply(); }
// CUENTAS-CONTACTOS-2 · Rellena la cuenta de systeme.io de los contactos que se
