// CTO-05-DEFINICIONES-1 · el aviso decía «no modifica nada» y callaba lo que SÍ cambia aquí: la
// web de cada contacto que aparezca. Ahora dice qué se mira (todos los que tienen email y aún no
// tienen web, con independencia del filtro de pantalla), qué se escribe aquí, qué no se toca, y
// el tope real del servidor (2.000 contactos, los que escribieron más recientemente). No es
// una acción de riesgo: se confirma en el estilo normal, no en el de borrar.
async function contactsSioBackfill(btn){
 // El tamaño del negocio solo se conoce sin filtros puestos (con filtros, totalAll cuenta las
 // coincidencias): con filtros se avisa del tope en condicional, sin afirmar cuánto es la lista.
 var dd=window.__ctData||{}, tot=Number(dd.totalAll)||0;
 var cuerpo='Se buscarán por email los contactos sin web asignada, sin aplicar los filtros de esta lista. Se guardará aquí la primera web donde aparezcan; en tus webs no se cambia ni se envía nada.'
  +((dd.filtrado||tot>2000)?' Se revisan hasta 2.000 contactos, empezando por los que han escrito más recientemente.':'');
 if(!(await confirmAct({title:'¿Enlazar tus contactos con tus webs?',body:cuerpo,ok:'Enlazar',cancel:'Cancelar',kind:'primary'}))) return;
 if(btn){ btn.disabled=true; btn.textContent='Enlazando…'; }
 var r=null; try{ r=await post('/admin/api/contacts/sio-backfill',{}); }catch(e){ r=null; }
 if(r&&r.ok){
  if(r.updated)toast('Listo|'+(r.updated===1?'1 contacto enlazado con su web':(r.updated+' contactos enlazados con su web')),'ok');
  else toast('Nada que enlazar|'+(r.reason||'No se ha encontrado a ninguno de esos contactos en las webs consultadas.'),'info');
 }
 else { toast('Error|No se han podido enlazar los contactos','err'); }
 rContacts();
}
