 var c=JSON.parse(JSON.stringify(p));
 c.name=copyName(p.name||p.id||'Conocimiento',L.map(function(x){return x.name||x.id||'';}));
 var base=(p.id||'kp')+'-copia';var id=base;var n=2;
 while(L.some(function(x){return x.id===id;})){id=base+'-'+n;n++;}
 c.id=id;L.push(c);
