    +'<div style="min-width:120px"><label class=fl>Duración</label><select id=kp_ag_dur style="margin:0">'+[15,30,45,60,90,120].map(function(m2){return '<option value='+m2+(Number(ag.duracionMin||30)===m2?' selected':'')+'>'+m2+' min</option>';}).join('')+'</select></div>'
   +'</div>'
