function bcfbAudMode(id,mode){var o=window.__f.nodes[id];if(!o)return;o.audience=o.audience||{};o.audience.mode=mode;if(mode==='tags'){o.audience.tags=o.audience.tags||[];}else if(mode==='segment'){o.audience.stage=o.audience.stage||'';o.audience.source=o.audience.source||'';}else if(mode==='explicit'||mode==='csv'){o.audience.recipients=o.audience.recipients||[];}fbEdit(id);}
function bcfbTagAdd(id,t){if(!t)return;var o=window.__f.nodes[id];if(!o||!o.audience)return;o.audience.tags=o.audience.tags||[];if(o.audience.tags.indexOf(t)<0)o.audience.tags.push(t);fbEdit(id);}
function bcfbTagDel(id,t){var o=window.__f.nodes[id];if(!o||!o.audience||!o.audience.tags)return;o.audience.tags=o.audience.tags.filter(function(x){return x!==t;});fbEdit(id);}
