 var winOpts=[['','Da igual la ventana'],['in','Solo los que llegan gratis'],['out','Solo los de plantilla']].map(function(o){return '<option value="'+o[0]+'"'+(b.win===o[0]?' selected':'')+'>'+o[1]+'</option>';}).join('');
