     // sigue funcionando; no-dd evita que ddSelects los vista.
     +'<div class=sch-row2>'
      +'<div class=sch-field id=sch_acc_field><div class=sch-fl-row><label class=fl id=sch_acc_lbl>Cuenta de Instagram</label><span class=sch-acc-hint id=sch_acc_hint></span></div><div class=sch-accs id=sch_accs role=group aria-labelledby=sch_acc_lbl></div><select id=sch_acc class=no-dd hidden aria-hidden=true tabindex=-1>'+opts+'</select></div>'
      +'<div class=sch-field><label class=fl id=sch_kind_lbl>Tipo de contenido</label><div class=sch-seg id=sch_kind_seg role=group aria-labelledby=sch_kind_lbl></div><select id=sch_kind class=no-dd hidden aria-hidden=true tabindex=-1><option value=image>Foto / Imagen</option><option value=reel>Vídeo / Reel / Short</option><option value=carousel>Carrusel (varias)</option><option value=story>Historia (24 h)</option></select></div>'
     +'</div>'
    +'</div>'
    // Bloque 2 · Contenido (creatividad + caption)
