  return '<div class=sch-pv-car-sl>'+(esV?'<video src="'+esc(u)+'" class=sch-pv-car-med autoplay muted loop playsinline></video>':'<img src="'+esc(u)+'" class=sch-pv-car-med alt="" draggable=false>')+'</div>';
