async function googleAdsSelectAccount(id){ var r=await post('/admin/api/googleads-accounts/select',{customerId:id}); if(r&&r.ok){toast('Cuenta seleccionada','ok');gaRepaint();} else toast('Error|'+((r&&r.error)||'no se pudo'),'err'); }
