// a cuentas que no existen en el nuevo). El wsId lo descubrimos vía
// /admin/api/workspaces/active (cache 60s) y lo mantenemos en window.__mxWs.
function mxStateKey(){return 'mx_'+(window.__mxWs||'default')+'_state';}
function mxStateLoad(){try{var raw=sessionStorage.getItem(mxStateKey());if(!raw)return;var s=JSON.parse(raw);if(s&&typeof s==='object'){if(Array.isArray(s.websel)||s.websel===null)window.__mxWebSel=s.websel;if(s.ig!=null)window.__mxIg=s.ig;if(s.ads!=null)window.__mxAds=s.ads;if(s.yt!=null)window.__mxYt=s.yt;if(s.wa!=null)window.__mxWa=s.wa;if(s.tt!=null)window.__mxTt=s.tt;if(s.site!=null)window.__mxSite=s.site;if(s.prev!=null)window.__mxPrev=s.prev;if(s.fb!=null)window.__mxFbPage=s.fb;if(s.si!=null)window.__mxSiAcc=s.si;if(s.li!=null)window.__mxLiOrg=s.li;if(s.as!=null)window.__mxAutoScope=s.as;if(s.ai!=null)window.__mxAutoInicio=s.ai;if(s.af!=null)window.__mxAutoFuncion=s.af;if(s.afu!=null)window.__mxAutoFuente=s.afu;if(s.wf&&typeof s.wf==='object')window.__mxWF=s.wf;}}catch(_){/* sessionStorage bloqueado o JSON corrupto: ignorar, seguimos con defaults */}}
function mxStateSave(){try{var s={ig:window.__mxIg||'',ads:window.__mxAds||'',yt:window.__mxYt||'',wa:window.__mxWa||'',tt:window.__mxTt||'',site:window.__mxSite||'',prev:window.__mxPrev||'',fb:window.__mxFbPage||'',si:window.__mxSiAcc||'',li:window.__mxLiOrg||'',as:window.__mxAutoScope||'',ai:window.__mxAutoInicio||'',af:window.__mxAutoFuncion||'',afu:window.__mxAutoFuente||'',wf:window.__mxWF||{},websel:(window.__mxWebSel||null)};sessionStorage.setItem(mxStateKey(),JSON.stringify(s));}catch(_){/* idem */}}
// AUTOMATIZACION-CANAL-1 · selector combinado canal+cuenta para la vista Automatización.
// Igual que auto_scope en el servidor: '' = todos, '<canal>' = todo ese canal,
// '<canal>:<id>' = una cuenta concreta. La lista sale de flow-options (__fopts).
// CANALES-LOGO-1 · el canal corto del ámbito ('wa','ig','fb','yt') es el mismo canal que
// el resto del panel pinta con su logo de marca: aquí está el puente a las claves de BRAND.
// Correo no es una marca: lleva el icono de sobre, con el color de la familia «tus cosas».
var MX_CANAL_MARCA={wa:'whatsapp',ig:'instagram',fb:'facebook',yt:'youtube'};
function mxCanalIco(ch,plano){
 if(ch==='email')return '<span class="brandico nkd" style="color:#9A4F38;display:inline-flex">'+ICN('mail')+'</span>';
 // CANALES-LOGO-1 · sin canal (la fila comodín «Todos los canales») el rayo va envuelto
 // igual que los logos: así le alcanza el ajuste a 14px del menú y su etiqueta arranca a
 // la misma altura que las de abajo, en vez de pegarse ~22px a la izquierda.
 var b=MX_CANAL_MARCA[ch];if(!b)return '<span class="brandico nkd" style="color:var(--dim);display:inline-flex">'+ICN('bolt')+'</span>';
 // plano = glifo del color de la marca sin caja blanca (para la fila «todo el canal»);
 // sin plano = el logo en su cajita, igual que los selectores de IG/LinkedIn de la barra.
 return plano?netIcoColor(b,((BRAND[b]||[])[1])||'64748b'):netIco(b);
}
function mxAutoScopeOpts(){
 // CANALES-LOGO-1 · la fila comodín también lleva icono, como la pestaña «Todos» de la
 // Bandeja: sin él era la única sin logo y la columna de etiquetas salía descuadrada.
 var o=window.__fopts||{};var out=[{v:'',t:'Todos los canales',ic:mxCanalIco('')}];
 var groups=[
  {ch:'wa',lbl:'WhatsApp',list:o.waNumbers||[]},
  {ch:'ig',lbl:'Instagram',list:o.igAccounts||[]},
  {ch:'fb',lbl:'Facebook',list:o.fbPages||[]},
  {ch:'yt',lbl:'YouTube',list:o.ytAccounts||[]},
  {ch:'email',lbl:'Correo',list:o.sioAccounts||[]}
 ];
 groups.forEach(function(g){
  if(!g.list.length)return;
  // CANALES-LOGO-1 · cada opción lleva su logo, como los diez selectores hermanos.
  if(g.list.length>1)out.push({v:g.ch,t:'Todo '+esc(g.lbl),ic:mxCanalIco(g.ch,true)});
  g.list.forEach(function(a){out.push({v:g.ch+':'+a.id,t:esc(g.lbl)+' · '+esc(a.label||a.id),ic:mxCanalIco(g.ch)});});
 });
 return out;
}
function mxAutoScopeSel(v){window.__mxAutoScope=v||'';mxStateSave();mxRender();}
