function mxAutoInicioSel(v){window.__mxAutoInicio=v||'';mxStateSave();mxRender();}
function mxAutoFuncionSel(v){window.__mxAutoFuncion=v||'';mxStateSave();mxRender();}
function mxAutoFuenteSel(v){window.__mxAutoFuente=v||'';mxStateSave();mxRender();}
function mxAutoClaseSel(inicio,funcion){window.__mxAutoInicio=inicio||'';window.__mxAutoFuncion=funcion||'';mxStateSave();mxRender();}
function mxAutoFiltrosLimpiar(){window.__mxAutoInicio='';window.__mxAutoFuncion='';window.__mxAutoFuente='';mxStateSave();mxRender();}
var MX_INICIO_LBL={comentario:'Comentario → mensaje privado',peticion:'Petición de la persona',correo:'Seguimiento de un correo',cita:'Confirmación y recordatorio',formulario:'Formulario'};
var MX_FUNCION_LBL={vender:'Vender',agendar:'Agendar una cita',captar:'Captar datos',cualificar:'Cualificar y derivar',entregar:'Entregar un recurso',conversar:'Responder y conversar'};
var MX_FUENTE_LBL={organica:'Orgánica',pago:'De pago',identificar:'Por identificar'};
var MX_CANAL_LBL={wa:'WhatsApp',ig:'Instagram',fb:'Facebook',yt:'YouTube',email:'Correo'};
function mxAutoClaseTxt(f){return [MX_INICIO_LBL[f.inicio]||'',MX_FUNCION_LBL[f.funcion]||'',MX_CANAL_LBL[f.canal]||''].filter(Boolean).join(' · ');}
// ===== Date-picker premium: presets + calendario propio de 2 meses (sin <input type=date> nativo) =====
function mxSOD(d){var x=new Date(d);x.setHours(0,0,0,0);return x.getTime();}
function mxEOD(d){var x=new Date(d);x.setHours(23,59,59,999);return x.getTime();}
function mxFmtD(ms){return new Date(ms).toLocaleDateString('es-ES',{day:'numeric',month:'short'});}
function mxFmtDY(ms){return new Date(ms).toLocaleDateString('es-ES',{day:'numeric',month:'short',year:'numeric'});}
// RANGO-CORREO-2 · El dia del USUARIO, en su calendario. Mandar solo los milisegundos no
// basta: el servidor los volvia a ajustar a SU medianoche, y en Railway el servidor va en UTC.
function mxISODia(ms){var d=new Date(ms),z=function(n){return (n<10?'0':'')+n;};
 return d.getFullYear()+'-'+z(d.getMonth()+1)+'-'+z(d.getDate());}
function mxRangeLabel(){if(window.__mxFrom&&window.__mxTo){var a=mxSOD(window.__mxFrom),b=mxSOD(window.__mxTo);if(a===b)return mxFmtDY(window.__mxFrom);return mxFmtD(window.__mxFrom)+' – '+mxFmtDY(window.__mxTo);}var l={7:'Últimos 7 días',14:'Últimos 14 días',28:'Últimos 28 días',30:'Últimos 30 días',90:'Últimos 90 días'};return l[window.__mxDays]||('Últimos '+window.__mxDays+' días');}
// FIX id79 (Fase 1): las fuentes WA/YT/FB/IG solo aceptan ?days= en el server
