// MX-FB-REFRESH 2026-06-05: invalida el cache server-side de Facebook (segMemo
// TTL 3min) y re-renderiza. Usado por el banner "Ya lo arreglé" cuando el user
// resolvio el problema de scope/role en Meta App y quiere verificar al momento
// sin esperar al TTL.
async function mxFbRefresh(){
 try{
  toast('Comprobando con Meta…','info');
  // RESPUESTA-ACCION-1 · antes el fallo se tragaba y se repintaba con la caché vieja:
  // el usuario creía haber comprobado con Meta sin que hubiera pasado nada.
  var r=await post('/admin/api/analytics/fb-cache-bust',{});
  if(!r||r.ok===false||r.error){toast('No se pudo comprobar con Meta|'+String((r&&r.error)||'inténtalo otra vez').slice(0,120),'err');return;}
  mxRender();
 }catch(e){ toast('Error|'+e.message,'err'); }
}
// MX-FB-DIAG 2026-06-05: muestra el detalle EXACTO de lo que Meta esta
// devolviendo (raw error message + flags needsAppRole/needsReconnect + lista de
// warnings). Asi el user puede verificar si la causa que dice el banner es real
// o si el backend la esta heurizando mal.
async function mxFbDiag(){
 if(!window.__isEnv) return;
 try{
  toast('Pidiendo diagnóstico a Meta…','info');
  var r=await api('/admin/api/analytics/fb-diag').catch(function(e){return {error:String(e&&e.message||e)};});
  if(r.error){ toast('Error: '+r.error,'err'); return; }
  var L=[];
  L.push('=== PAGE ===');
  L.push('Page: '+(r.pageName||'?')+' (ID '+(r.pageId||'?')+')');
  L.push('Conectada: '+(r.connectedAt||'?')+' (hace '+(r.connectedAgoMin||0)+' min)');
  L.push('');
  L.push('=== TOKEN ===');
  var t=r.tokenInfo||{};
  L.push('Tipo: '+(t.type||'?')+' · is_valid: '+(t.is_valid?'true':'false'));
  if(t.expires_at) L.push('Caduca: '+new Date(t.expires_at*1000).toISOString());
  L.push('Has pages_read_engagement: '+(r.hasPagesReadEngagement?'SI ✓':'NO ✗'));
  L.push('');
  L.push('Scopes detectados ('+(r.scopes||[]).length+'):');
  (r.scopes||[]).forEach(function(s){L.push('  • '+s+(s==='pages_read_engagement'?' ← KEY':''));});
  if(t.granular_scopes){
   L.push('');
   L.push('Granular scopes (con target IDs):');
   t.granular_scopes.forEach(function(g){L.push('  • '+g.scope+(g.target_ids?' [Pages: '+g.target_ids.length+']':''));});
  }
  L.push('');
  L.push('=== TEST DIRECTO POSTS ===');
  var pt=r.postsTest||{};
  L.push('HTTP '+(pt.http||'?')+' · ok: '+(pt.ok?'true':'false')+' · posts: '+(pt.count||0));
  if(pt.error){
   L.push('Error code '+pt.error.code+' subcode '+(pt.error.error_subcode||'-')+' type '+pt.error.type);
   L.push('Mensaje: '+pt.error.message);
   if(pt.error.fbtrace_id) L.push('fbtrace_id: '+pt.error.fbtrace_id);
  }
  L.push('');
  L.push('=== TEST DIRECTO INSIGHTS ===');
  var it=r.insightsTest||{};
  L.push('HTTP '+(it.http||'?')+' · ok: '+(it.ok?'true':'false')+' · puntos: '+(it.dataPoints||0));
  if(it.error){ L.push('Error '+it.error.code+': '+it.error.message); }
  L.push('');
  L.push('=== HEURISTICA BACKEND ===');
  var h=r.heuristic||{};
  L.push('needsAppRole: '+(h.needsAppRole?'true':'false'));
  L.push('needsReconnect: '+(h.needsReconnect?'true':'false'));
  if(Array.isArray(h.warnings)){
   L.push('Warnings:');
   h.warnings.forEach(function(w){L.push('  • '+w);});
  }
  infoModal('Diagnóstico de Facebook', L.join('\\n'));
  // Tambien lo dejo en consola para que el user lo pueda copiar facil
  try{ if(localStorage.getItem('debug')==='1') console.log('[FB-DIAG]', r); }catch(_){}
 }catch(e){ toast('Error|'+e.message,'err'); }
}
