 var igPartes=[a.likes,a.comments,a.saves,a.shares];
 var igNoCuadra=typeof a.interactions==='number'&&a.interactions>=0&&igPartes.every(function(v){return typeof v==='number'&&v>=0;})&&(a.likes+a.comments+a.saves+a.shares)>a.interactions;
 var igDudI=igNoCuadra||igPartes.concat([a.interactions]).some(igNeg);
