 window.__mxIgDud=igDud; // PULIDO-IG-1 · el CSV deja la tasa en blanco igual que aquí
 var igVal=function(v){return igNeg(v)?('−'+mxFmt(-v)):mxFmt(v);};
 var igSigno=function(v){return (typeof v!=='number')?'—':((v<0?'−':(v>0?'+':''))+mxFmt(Math.abs(v)));};
 // PULIDO-IG-1 · cada cifra lleva su definición a mano (title), y una que no llegó lo dice.
 var igLbl=function(txt,txtAj,v,def){return igNeg(v)?('<span title="'+esc(igAjTitle)+'">'+txtAj+'</span>'):((v==null||def)?('<span title="'+esc(v==null?igSinDato:def)+'">'+txt+'</span>'):txt);};
 var igTasaTit=igDud?'No se calcula mientras alguna cifra de estos 28 días llegue de Instagram como ajuste negativo o no cuadre con las demás: el porcentaje saldría falso.':(a.engagementRateBasis==='followers'?'De cada 100 seguidores, cuántas interacciones (me gusta, comentarios, guardados y compartidos) hubo en 28 días. Instagram no ha dado el alcance, así que se divide entre seguidores.':'De cada 100 cuentas alcanzadas, cuántas interacciones (me gusta, comentarios, guardados y compartidos) hubo en 28 días: interacciones ÷ alcance.');
 // PORTADA-IG-1 · «de un vistazo» deja paso a la portada y sus cifras van a su grupo: los seguidores, a
