 var igTasaF=(!igDud&&a.engagementRate!=null&&a.engagementRateBasis!=='followers'&&typeof a.interactions==='number'&&typeof a.reach==='number')?('<span class=mx-tile-f>'+mxFmt(a.interactions)+' interacciones ÷ '+mxFmt(a.reach)+' alcance</span>'):'';
