 var igDmCell='<a class="mx-minicell mx-minilink" href="#" onclick="igBandejaDm();return false;" title="Instagram no incluye los mensajes directos en estas cifras. Este enlace abre la bandeja filtrada por Instagram, aquí mismo."><div class=mx-minival>'+ICN('inbox')+'</div><div class=mx-minilbl>Mensajes directos&nbsp;· ver en la bandeja</div></a>';
 var inter='<div class=card><h3>Comentarios, mensajes y reacciones · 28 días</h3>'
  +'<div class=mx-igrp><div class=mx-igrp-h>Conversaciones <span class=mx-igrp-s>te hablan</span></div><div class=mx-mini>'+igCell('Comentarios',a.comments)+igDmCell+'</div></div>'
