  +'</div>';
 var posts=d.posts||[];
 var igTL=function(p){if(p.typeLabel)return p.typeLabel;var u=String(p.type||'').toUpperCase();if(u.indexOf('CAROUSEL')>=0)return 'Carrusel';if(u.indexOf('REEL')>=0||u.indexOf('VIDEO')>=0)return 'Reel / Vídeo';if(u.indexOf('IMAGE')>=0||u.indexOf('PHOTO')>=0)return 'Imagen';return p.type||'Post';};
 var igIsReel=function(p){var u=String(p.mediaProductType||p.type||'').toUpperCase();return u.indexOf('REEL')>=0||u.indexOf('VIDEO')>=0;};
