// Llega con la portada: qué publicación trajo cada contacto nuevo de estas fechas (porPublicacion).
function mxIgRkCs(cs){var s=window.__mxIgRk;if(!s)return;var pp=(cs&&cs.ok&&cs.porPublicacion)||[],ids={},m={},n=0;
 s.all.forEach(function(p){ids[String(p.id)]=1;});
 pp.forEach(function(x){var id=String((x&&x.mediaId)||''),v=Number(x&&x.n)||0;if(ids[id]&&v>0){m[id]=v;n++;}});
 s.cMap=n?m:null;if(!n)return;
 var tb=window.__mxIgTb;if(tb)tb.all.forEach(function(r){r.c=m[String(r.p.id)]||0;});
 var el=document.getElementById('mx_igrk');if(el)el.outerHTML=mxIgRkHtml();
 if(mxIgRkM()==='contactos')mxIgTbOrd('contactos','desc');}
// RANKING-IG-1 · la tabla completa: todas las publicaciones que se cargan (hasta 30), paginada, con búsqueda,
