 if(H.reel(p)){var ex=[];if(p.avgWatchTime!=null)ex.push('▶ '+p.avgWatchTime+'s medio');if(p.replays!=null)ex.push(mxFmt(p.replays)+' repeticiones');if(ex.length)sub+=(sub?' · ':'')+ex.join(' · ');}
 var skv=tb.k==='contactos'?(r.c>0?r.c:null):(MX_IGTB_SK[tb.k]?p[tb.k]:null);
 var sk=(skv!=null&&MX_IGTB_SK[tb.k])?('<div class="igpt-sk'+(tb.k==='contactos'?' al':'')+'">'+mxFmt(skv)+' '+esc(skv===1?MX_IGTB_SK[tb.k][1]:MX_IGTB_SK[tb.k][0])+'</div>'):'';
 // De las anteriores a las 12 más recientes no se piden estas cifras: «—» con el motivo, no «Instagram no lo da».
