// metricas-pro #15 — renderer Instagram PRO (datos reales Graph API).
// Lee /admin/api/analytics/instagram-pro?days=&ig_id= y pinta:
//  · Heatmap 24h (online_followers promediado por hora del dia)
//  · Bar chart "Best posting times" (top 6 horas con mas online followers)
//  · KPI tile Story reach 28d + sample de las 5 ultimas stories con sus insights
async function mxIgProRender(igId){
 var box=document.getElementById('mxIgProBody');if(!box)return;
 var qp='days='+window.__mxDays+(igId?'&ig_id='+encodeURIComponent(igId):'');
 var d;try{d=await api('/admin/api/analytics/instagram-pro?'+qp);}catch(e){box.innerHTML='<div class=card>'+empty({ic:'chart',title:'No se pudo cargar Instagram PRO',body:String((e&&e.message)||e)})+'</div>';return;}
 if(!d||d.configured===false){box.innerHTML='<div class=card>'+mxProEmptyCTA('Conecta tu cuenta de Instagram Business para ver KPIs PRO reales (mejores horas para publicar, alcance de stories, rendimiento de hashtags).','Conectar Instagram','conectar(\"instagram\")')+'</div>';return;}
 // COUNCIL-FIX: _tzB y bptBars se declaran ANTES de usarse — antes iban después
 // del bloque kpis/heatmap que los lee (var hoisted=undefined): «Ventana pico»
 // salía siempre «—» y la rotación del heatmap indexaba con NaN (todo a cero).
 var _tzB=Math.round(-(new Date().getTimezoneOffset())/60);
 var bptBars=(d.bestPostingTimes||[]).map(function(t){var lh=(((Number(t.hour)||0)+_tzB)%24+24)%24;return {label:(lh<10?'0':'')+lh+':00',followers:t.followers};});
 // KPI tile Story reach 28d. FIX #15: si server devolvio null (Graph failed),
 // mostramos "—" (no 0 enganoso). mxProKpiTile ya soporta valor null → "—".
 var kpis='<div class=mx-pro-kpi-grid>'
  +mxProKpiTile('Alcance de stories · 24h', d.storyReach28d==null?null:mxFmt(d.storyReach28d))
  +mxProKpiTile('Stories recientes',mxFmt((d.recentStories||[]).length))
  +mxProKpiTile('Ventana pico',(bptBars&&bptBars[0])?bptBars[0].label:'—')
  +'</div>';
 // Heatmap 24h. FIX #15: si Graph fallo (null), mostramos mensaje explicito en
 // lugar de un heatmap de ceros (que parecia que no habia audiencia, falso).
 var heatmap;
 if(d.onlineFollowersByHour==null){
  heatmap='<div class=mx-pro-heatmap><div class=mx-pro-hm-lbl>Audiencia online por hora del día (promedio '+mxWinLbl()+')</div><p class=muted style="margin:0;font-size:13px">Audiencia online no disponible — Meta no devolvió este insight para tu cuenta en este rango.</p></div>';
 } else {
  var _ofB=d.onlineFollowersByHour.slice();var _ofL=_ofB.map(function(_,i){return _ofB[((i-_tzB)%24+24)%24];});
  heatmap=mxProHeatmap24h(_ofL,'Audiencia online por hora del día (promedio '+mxWinLbl()+' · tu hora local)');
 }
 var bptCard=bptBars.length
  ?'<div class=card><h3>Mejores horas para publicar · top 6 ventanas</h3><p class=ap-help style="margin:0 0 14px">Las horas con más audiencia online de IG (promedio del rango). Publica aquí para maximizar el alcance orgánico.</p><div class=mx-pro-bars>'+mxProBars(bptBars,function(x){return x.label;},function(x){return x.followers;})+'</div></div>'
  :'<div class=card><p class=muted>Instagram no facilita las horas de actividad de los seguidores para esta cuenta.</p></div>';
 // Stories.
 var storyRows=(d.recentStories||[]).map(function(s){return '<tr><td>'+(s.thumb?'<img src="'+esc(s.thumb)+'" style="width:38px;height:38px;object-fit:cover;border-radius:6px" alt="">':'')+'</td><td><span class=tag>'+esc(s.mediaType||'STORY')+'</span></td><td class=right>'+mxFmt(s.reach)+'</td><td class=right>'+mxFmt(s.impressions)+'</td><td class=right>'+mxFmt(s.replies)+'</td><td>'+(s.permalink?('<a href="'+esc(s.permalink)+'" target=_blank rel=noopener>Ver</a>'):'')+'</td></tr>';}).join('');
 var storyCard=(d.recentStories&&d.recentStories.length)
  ?'<div class=card><h3>Stories recientes</h3><p class=ap-help style="margin:0 0 12px">Últimas stories en vivo (Meta solo expone insights mientras están activas, 24h).</p><div class=table-wrap><table><thead><tr><th></th><th>Tipo</th><th class=right>Alcance</th><th class=right>Impresiones</th><th class=right>Respuestas</th><th></th></tr></thead><tbody>'+storyRows+'</tbody></table></div></div>'
  :'<div class=card><p class=muted>No hay stories activas ahora mismo.</p></div>';
 // Hashtag perf. FIX #15 ig: 3 estados explicitos (en lugar de "tabla vacia"):
 //   - hashtagPerf array con items → render normal (bars).
 //   - hashtagPerf null + warning de scope → mensaje permisos explicito al
 //     operador (NO inventar tabla vacia que sugiere "no hay hashtags").
 //   - hashtagPerf null sin warning → no rendear nada (el user no usa #).
 var hashCard='';
 if(d.hashtagPerf&&d.hashtagPerf.length){
  hashCard='<div class=card><h3>Popularidad de tus hashtags · top 3</h3><p class=ap-help style="margin:0 0 14px">Likes + comentarios del top 10 público de cada hashtag que usas (publicaciones de cualquier cuenta, señal de demanda del hashtag).</p><div class=mx-pro-bars>'+mxProBars(d.hashtagPerf,function(x){return x.tag;},function(x){return x.reach;})+'</div></div>';
 } else if(d.hashtagPerf==null){
  // AVISOS-META-1 · el servidor ya manda la bandera; el texto del aviso queda como respaldo.
  var scopeWarn=d.hashtagScopeMissing===true||(d.warnings||[]).some(function(w){return /ig_hashtag_search|instagram_basic/i.test(String(w));});
  if(scopeWarn){
   hashCard='<div class=card><h3>Rendimiento de hashtags</h3><p class=muted style="margin:0;font-size:13px;line-height:1.55">No disponible todavía: Instagram no nos deja leer el rendimiento de tus hashtags desde este panel. Avisa al administrador del panel para que lo active; el resto de métricas de Instagram no cambia.'+(window.__isEnv?' <span class=muted>Detalle para el operador: pide <code>instagram_basic</code> + <code>ig_hashtag_search</code> en App Review y vuelve a conectar la cuenta.</span>':'')+'</p></div>';
  }
 }
 var warnCard='';if(window.__isEnv&&(d.warnings||[]).length){warnCard='<div class=card style="border-color:var(--warnline);background:var(--warnbg)"><h3 style="color:var(--warn);margin-top:0">Avisos técnicos de Meta (solo los ve el operador)</h3><ul style="margin:0;padding-left:18px;font-size:12.5px;color:var(--tx);line-height:1.7">'+(d.warnings||[]).map(function(w){return '<li>'+esc(w)+'</li>';}).join('')+'</ul></div>';}
 box.innerHTML='<div class=mx-pro-section><h3>'+ICN('sparkles')+'Instagram PRO</h3><p class=muted style="margin:0 0 14px">KPIs de creador profesional: mejores momentos para publicar, alcance de stories y rendimiento de hashtags.</p></div>'+kpis+heatmap+bptCard+storyCard+hashCard+warnCard;
}
