async function mxYtProRender(channelId){
 var box=document.getElementById('mxYtProBody');if(!box)return;
 var qp='days='+window.__mxDays+(channelId?'&yt_channel='+encodeURIComponent(channelId):'');
 var d;try{d=await api('/admin/api/analytics/youtube-pro?'+qp);}catch(e){box.innerHTML='<div class=card>'+empty({ic:'chart',title:'No se pudo cargar YouTube PRO',body:String((e&&e.message)||e)})+'</div>';return;}
 if(!d||d.configured===false){box.innerHTML='<div class=card>'+mxProEmptyCTA('Conecta tu canal de YouTube para ver KPIs PRO reales (vistas por hora, top vídeos, crecimiento de suscriptores).','Conectar YouTube','conectar(\"youtube\")')+'</div>';return;}
 // KPI tiles + sparkline subs.
 var hasSpark=(d.subSparkline||[]).length>=2;
 var sparkHtml=hasSpark?mxProSparkline(d.subSparkline,'#ff0033'):'<div class=mx-pro-spark-empty>Sin histórico</div>';
 var tiles='<div class=mx-pro-kpi-grid>'
  +mxProKpiTile('Suscriptores',mxFmt(d.subscribersNow||0))
  +mxProKpiTile('Top vídeos',mxFmt((d.topVideos||[]).length))
  +'<div class=mx-pro-tile><span class=mx-pro-tile-lbl>Tendencia subs · 14d</span><div style="padding-top:8px">'+sparkHtml+'</div></div>'
  +'</div>';
 // FIX #15 yt: heatmap por hora NO disponible en YT Analytics pública.
 // Si server devolvio viewsHourly null (always now), degradamos a sparkline
 // 30d real con titulo claro. Antes inventaba distribuyendo views/dia entre
 // 12-21h "porque si" — violaba never-fake-metrics.
 var heatmap;
 if(d.viewsHourly==null){
  // Sparkline real desde viewsDailySeries (length = rangeDays).
  var series=(d.viewsDailySeries||[]).map(function(x){return Number(x.views)||0;});
  // VACIO-EXPLICA-1 · sin serie diaria: o el rango es corto, o la analítica de YouTube
  // todavía no ha consolidado los días. Se dice cuándo aparecerá.
  var sparkSvg=series.length>=2?mxProSparkline(series,'#ff0033'):'<div class=mx-pro-spark-empty>Aún no hay vistas diarias en este rango. YouTube consolida la analítica con hasta dos días de retraso: amplía el rango de fechas de arriba o vuelve en un par de días.</div>';
  heatmap='<div class=mx-pro-heatmap><div class=mx-pro-hm-lbl>Vistas últimos '+window.__mxDays+'d (sparkline real)</div><p class=ap-help style="margin:0 0 12px;font-size:12px">YouTube Analytics no expone heatmap por hora del día en su API pública — mostramos la serie diaria real en su lugar.</p>'+sparkSvg+'</div>';
 } else {
  heatmap=mxProHeatmap24h(d.viewsHourly,'Visualizaciones por hora del día (aprox '+window.__mxDays+'d)');
 }
 // Top videos.
 var vidRows=(d.topVideos||[]).map(function(v){return '<tr><td>'+(v.thumb?'<a href="https://youtu.be/'+encodeURIComponent(v.id)+'" target=_blank rel=noopener><img src="'+esc(v.thumb)+'" style="width:80px;height:45px;object-fit:cover;border-radius:5px" alt=""></a>':'')+'</td><td><a href="https://youtu.be/'+encodeURIComponent(v.id||'')+'" target=_blank rel=noopener title="'+esc(v.title||'')+'">'+esc(v.title||'(sin título)')+'</a></td><td class=right>'+mxFmt(v.views)+'</td><td class=right>'+mxFmt(v.likes)+'</td><td class=right>'+(v.published?new Date(v.published).toLocaleDateString('es-ES',{day:'numeric',month:'short'}):'')+'</td></tr>';}).join('');
 var vidCard=(d.topVideos&&d.topVideos.length)
  ?'<div class=card><h3>Top 10 vídeos recientes</h3><p class=ap-help style="margin:0 0 14px">Últimos vídeos publicados con sus vistas y likes en el rango.</p><div class=table-wrap><table><thead><tr><th></th><th>Título</th><th class=right>Vistas</th><th class=right>Likes</th><th class=right>Publicado</th></tr></thead><tbody>'+vidRows+'</tbody></table></div></div>'
  :'<div class=card><p class=muted>Sin vídeos recientes.</p></div>';
 var warnCard='';if((d.warnings||[]).length){warnCard='<div class=card style="border-color:var(--warnline);background:var(--warnbg)"><h3 style="color:var(--warn);margin-top:0">Avisos de YouTube</h3><ul style="margin:0;padding-left:18px;font-size:12.5px;color:var(--tx);line-height:1.7">'+(d.warnings||[]).map(function(w){return '<li>'+esc(w)+'</li>';}).join('')+'</ul></div>';}
 var proMultiNote=((window.__mxYtAccs||[]).length>1&&!channelId)?'<p class=muted style="margin:0 0 14px;font-size:12px">Tienes varios canales — este panel muestra el primero. Usa el selector de canal de la barra superior para cambiarlo.</p>':'';
 box.innerHTML='<div class=mx-pro-section><h3>'+ICN('sparkles')+'YouTube PRO · '+esc(d.channelTitle||'Canal')+'</h3><p class=muted style="margin:0 0 14px">KPIs profesionales: visualizaciones por hora, top vídeos recientes y crecimiento de suscriptores.</p>'+proMultiNote+'</div>'+tiles+heatmap+vidCard+warnCard;
}
function mxPixelSnippet(name){var s=(name||'sitio').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-+|-+$/g,'')||'sitio';var B=location.origin+'/pv?p='+encodeURIComponent(s)+'&l='+encodeURIComponent(name||s);
 // Píxel COMPLETO v2 (paridad con pageviewSnippet del server): beacon de carga con UTM,
 // click-ids de ads y zona horaria + beacon de salida por nonce con tiempo, scroll máximo
 // y velocidad de carga. Los UTM persisten en sessionStorage para que la sesión entera
 // quede atribuida a su campaña al navegar. La ruta /pv procesa n/pa/lg/d/us/um/uc/ut/uo/ci/tz/sc/lt.
 return '<script>(function(){try{'
  +'var n=Math.random().toString(36).slice(2),t0=Date.now(),sent=false,sc=0;'
  +'var B='+JSON.stringify(B)+'+"&n="+n;'
  +'function q(x){try{var i=new Image();i.src=B+x;}catch(e){}}'
  +'var U="";try{var Q=new URLSearchParams(location.search),K=[["utm_source","us"],["utm_medium","um"],["utm_campaign","uc"],["utm_term","ut"],["utm_content","uo"]],P=[],i,v;'
  +'for(i=0;i<K.length;i++){v=Q.get(K[i][0]);if(v)P.push(K[i][1]+"="+encodeURIComponent(v.slice(0,120)));}'
  +'var C="";["gclid","fbclid","msclkid","ttclid","li_fat_id","twclid"].some(function(k){if(Q.get(k)){C=k;return true}return false});'
  +'if(C)P.push("ci="+C);'
  +'if(P.length){U="&"+P.join("&");try{sessionStorage.setItem("_lmU",U)}catch(e){}}else{try{U=sessionStorage.getItem("_lmU")||""}catch(e){}}}catch(e){}'
  +'var rf=document.referrer||"";try{if(rf&&new URL(rf).hostname===location.hostname)rf="";}catch(e){}'
  +'var tn="";try{tn=Intl.DateTimeFormat().resolvedOptions().timeZone||""}catch(e){}'
  +'q("&r="+encodeURIComponent(rf.slice(0,300))+"&pa="+encodeURIComponent(location.pathname)+"&lg="+encodeURIComponent(navigator.language||"")+"&tz="+(new Date().getTimezoneOffset())+"&tzn="+encodeURIComponent(tn)+U);'
  +'window.lmTrack=function(e){q("&e="+encodeURIComponent(e)+"&pa="+encodeURIComponent(location.pathname)+U);};'
  +'function m(){try{var d=document.documentElement,b=document.body,h=Math.max(d.scrollHeight,b?b.scrollHeight:0),y=(window.scrollY||d.scrollTop||0)+window.innerHeight,p=h>0?Math.round(y/h*100):0;if(p>sc)sc=p>100?100:p}catch(e){}}'
  +'window.addEventListener("scroll",m,{passive:true});m();'
  +'function d(){if(sent)return;sent=true;var lt=0;try{var pe=performance.getEntriesByType("navigation")[0];lt=pe&&pe.loadEventEnd?Math.round(pe.loadEventEnd):0}catch(e){}q("&d="+(Date.now()-t0)+"&sc="+sc+(lt?"&lt="+lt:""));}'
  +'document.addEventListener("visibilitychange",function(){if(document.visibilityState==="hidden")d();});'
  +'window.addEventListener("pagehide",d);'
  +'}catch(e){}})();'+'<'+'/script>';}
// Snippet OFICIAL desde el server: registra el slug→workspace (multi-tenant) y usa la URL
// pública configurada. El generado en cliente (mxPixelSnippet) queda como fallback visual
// inmediato mientras llega la respuesta.
// ROUTE-VIEW-2 · esto era un catch vacío: cuando la petición fallaba —y fallaba con 403
// porque la ruta no estaba en el mapa de secciones— la tarjeta se quedaba con el código de
// ejemplo que genera el navegador y nadie sabía que el bueno no había llegado. El usuario
// copiaba un código que no registra su web. Ahora se dice, aquí mismo.
function mxPixelAviso(e){
 if(e&&e.status===403) return 'Tu usuario no tiene permiso para preparar este código. Pídeselo a quien administre el panel.';
 return 'No hemos podido preparar el código de tu web: el que se ve es un ejemplo y todavía no mide nada. Vuelve a intentarlo en un momento.';
}
async function mxPixelFetch(name){
 var avi=document.getElementById('mx_snipavi');
 try{
  var r=await api('/admin/api/web/pixel-snippet?reg=0&name='+encodeURIComponent(name||'mi-sitio'),{nocache:true});
  if(r&&r.snippet){window.__mxSnip=r.snippet;var pre=document.getElementById('mx_snip');if(pre)pre.textContent=r.snippet;}
  window.__mxSnipErr=null;
  if(avi){avi.textContent='';avi.classList.add('hidden');}
 }catch(e){
  window.__mxSnipErr=e||{};
  if(avi){avi.textContent=mxPixelAviso(e);avi.classList.remove('hidden');}
 }
}
function mxPixelUpd(){var n=(document.getElementById('mx_sitename')||{}).value||'mi-sitio';window.__mxSnip=mxPixelSnippet(n);var pre=document.getElementById('mx_snip');if(pre)pre.textContent=window.__mxSnip;
 clearTimeout(window.__mxPixT);window.__mxPixT=setTimeout(function(){mxPixelFetch(n);},400);}
// Copiar REGISTRA el slug→workspace (reg=1): a partir de aquí la web existe en el catálogo.
// CONVERSION-WEB-2 · lleva al codigo de medicion SIN salir de la pantalla (regla 9) y lo
