  dec.push({ic:'alert',h:'Difusiones del rango con fallos de entrega comprobados: al menos uno y el 10 % o más de los mensajes con resultado. Los pendientes no cuentan.',txt:'En la difusión <b translate=no>«'+esc(x.text||'sin texto')+'»</b>, <b>'+mxFmt(x.fallos)+'</b> de <b>'+mxFmt(x.resueltos)+'</b> mensajes con resultado no llegaron. <button type=button class=linklike data-b="'+esc(String(x.id).replace(/[^A-Za-z0-9_-]/g,''))+'" onclick="bcDetalle(this.dataset.b)">Revisar entregas</button>'});
