// WA-RECO-1 (MET-WA-08) · recomendaciones que salen de resultados YA observados, cada una con la base
// en la que se apoya y sin prometer efectos: ni «se duplica la conversión» ni «mejorará». Se dice qué se
// vio, con cuántas personas, y se propone probar y comparar. Con pocos datos no se recomienda: se dice
// qué falta. Reglas (también en el title de cada línea): comparar difusiones exige al menos dos con 20 o
// más personas con seguimiento y 10 puntos de diferencia; los fallos de entrega son los de ENTREGA-WA-1;
// una plantilla se señala con al menos 20 envíos con seguimiento y un 10 % o más de fallidos; la hora
// punta, con al menos 50 mensajes en el rango y siempre dicha como «cuándo escriben», no como prueba.
function mxWaReco(o){
 var d=o.d||{},difs=o.difs||[],pico=o.pico,L=[];
 var nom=function(x){return '<b translate=no>«'+esc(x.text||'sin texto')+'»</b>';};
 var cmp=difs.filter(function(x){return x.respSeg>=20;}).map(function(x){return {x:x,p:Math.round((x.respondieron||0)/x.respSeg*1000)/10};}).sort(function(a,b){return b.p-a.p;});
 var rh='Fuente: respuestas de cada difusión del rango (escribieron o pulsaron un botón en las 72 h siguientes), sobre las personas con seguimiento. Regla: se compara con al menos dos difusiones de 20 o más personas con seguimiento y una diferencia de 10 puntos o más.';
 if(difs.length&&cmp.length<2)L.push({ic:'help',h:rh,txt:'Todavía son pocos datos para comparar tus difusiones: hacen falta al menos dos con 20 personas con seguimiento cada una.'});
 else if(cmp.length>=2){var best=cmp[0],worst=cmp[cmp.length-1];
  if(best.p-worst.p>=10)L.push({ic:'send',h:rh,txt:'La difusión '+nom(best.x)+' tuvo respuesta de <b>'+best.p+'%</b> ('+mxFmt(best.x.respondieron)+' de '+mxFmt(best.x.respSeg)+' personas), frente al <b>'+worst.p+'%</b> de '+nom(worst.x)+' ('+mxFmt(worst.x.respondieron)+' de '+mxFmt(worst.x.respSeg)+'). Puedes probar su texto o su momento en el próximo envío y comparar; con dos envíos no se puede asegurar qué lo causó.'});
  else L.push({ic:'send',h:rh,txt:'Tus difusiones con seguimiento respondieron de forma parecida (entre el '+worst.p+'% y el '+best.p+'%): con estos envíos no hay una diferencia que aconseje cambiar nada.'});}
 var al=(d.entregaAlertas||[])[0];
 if(al)L.push({ic:'alert',h:'Fuente: confirmaciones de entrega de WhatsApp. Regla: difusión con al menos un fallo y el 10 % o más de los mensajes con resultado; los pendientes no cuentan.',txt:'En la difusión '+nom(al)+', <b>'+mxFmt(al.fallos)+'</b> de <b>'+mxFmt(al.resueltos)+'</b> mensajes con resultado no llegaron. Antes de volver a enviarla, mira en su ficha el motivo de cada fallo. <button type=button class=linklike data-b="'+esc(String(al.id).replace(/[^A-Za-z0-9_-]/g,''))+'" onclick="bcDetalle(this.dataset.b)">Revisar entregas</button>'});
 var tp=(d.by_template||[]).filter(function(t){return t.tracked>=20&&t.failed_pct>=10;}).sort(function(a,b){return b.failed_pct-a.failed_pct;})[0];
 if(tp)L.push({ic:'alert',h:'Fuente: confirmaciones de entrega de WhatsApp. Regla: plantilla con al menos 20 envíos con seguimiento y un 10 % o más de fallidos.',txt:'La plantilla <b translate=no>'+esc(tp.name)+'</b> falló en el <b>'+tp.failed_pct+'%</b> de sus '+mxFmt(tp.tracked)+' envíos con seguimiento. Revisa por qué antes de seguir usándola.'});
 if(pico&&pico.total>=50)L.push({ic:'clock',h:'Fuente: mensajes que te escribieron las personas en el rango, en tu hora; tus envíos y difusiones no cuentan. Regla: se señala con al menos 50 mensajes recibidos. Dice cuándo escriben, no cuándo funciona mejor un envío.',txt:'La hora en que más te escribieron fue el <b>'+pico.dia.toLowerCase()+' a las '+pico.hora+'h</b> (tu hora): <b>'+mxFmt(pico.n)+'</b> de '+mxFmt(pico.total)+' mensajes recibidos ('+Math.round(pico.n/pico.total*100)+'%). Conviene tener a alguien atendiendo a esa hora.'});
 return '<div class="card mx-insights"><h3>Recomendaciones según lo observado · '+mxWinLbl()+'</h3><p class=ap-help style="margin:0 0 12px">Salen de resultados que ya han pasado, con las personas en las que se apoyan. No prometen qué ocurrirá si las sigues.</p>'
  +(L.length?'<div class=mx-ins-list>'+L.map(function(x){return '<div class=mx-ins-row><span class=mx-ins-ic>'+ICN(x.ic)+'</span><span class=mx-ins-tx>'+x.txt+'<details class=mx-ins-calc><summary>Ver cómo se calculó</summary>'+esc(x.h)+' Periodo: '+esc(mxWinLbl())+'.</details></span></div>';}).join('')+'</div>'
   :empty({ic:'help',title:'Aún no hay resultados para recomendar',body:'Las recomendaciones salen de lo que ya pasó: las respuestas de tus difusiones y las entregas con fallos. Cuando envíes más difusiones con seguimiento aparecerán aquí.'}))+'</div>';
}
