 var pico=null;
 if(maxCnt>0){var pk=0,pkIdx=0,pkTot=0;for(var pi=0;pi<168;pi++){var pv2=src[pi].count_in||0;pkTot+=pv2;if(pv2>pk){pk=pv2;pkIdx=pi;}}var pkLoc=((pkIdx+_waOff)%168+168)%168;pico={dia:dowFull[Math.floor(pkLoc/24)],hora:pkLoc%24,n:pk,total:pkTot};}
