  +(window.__mxWaSegCam!=null?'&campana='+encodeURIComponent(window.__mxWaSegCam):'');
 var d;try{d=await api('/admin/api/analytics/whatsapp/seguimiento?'+q);}catch(e){
  box.innerHTML='<div class=card>'+empty({ic:'alert',title:'No se pudo cargar el seguimiento',body:'Vuelve a intentarlo en un momento.'})+'</div>';return;}
 box=document.getElementById('mxwaseg');if(!box)return;
