// ===== CORREO · aperturas por cuenta systeme.io =====
function mxCorreoTypeLabel(t){var m={newsletter:'Newsletter',automation:'Automatización',campaign:'Campaña'};return m[t]||(t?(t.charAt(0).toUpperCase()+t.slice(1)):'Correo');}
// CORREO-USO-1 (MET-CORREO-02) · dos usos que no se comparan entre sí: las CAMPAÑAS que el negocio
// manda a su base cuando quiere (newsletter) y los correos que salen SOLOS dentro de un recorrido
// (automatizaciones, secuencias, embudos). Cada correo cae en un solo grupo, así que las dos sumas
// dan el total sin contar nada dos veces. El objetivo y a quién va los declara el negocio en la
// ficha del correo (el proveedor no lo sabe); sin declarar, un aviso o una confirmación se reconoce
// por el asunto y no compite con las promociones, y el resto de un recorrido se da por seguimiento.
var CO_OBJ={periodico:'Contenido periódico',promo:'Lanzamiento o promoción',reactivacion:'Reactivación',seguimiento:'Seguimiento',operativo:'Aviso o confirmación',otro:'Otro'};
var CO_DISP={Workflow:'Se envía al entrar en el flujo',Campaña:'Se envía al apuntarse a la secuencia',Embudo:'Se envía al registrarse en el embudo',Reglas:'Lo envía una regla automática'};
var CO_OPER=/confirma|factura|recibo|contraseña|tus? accesos?\\b|tu (reserva|cita|pedido|compra|registro|inscripci)/i;
function coUsoGrupo(e){return String((e&&e.emailType)||'').toLowerCase()==='newsletter'?'base':'rec';}
function coUsoNom(g){return g==='base'?'Campañas a tu base':(g==='rec'?'Correos de un recorrido':'Todos los correos');}
function coUsoNom1(g){return g==='base'?'Campaña a tu base':'Correo de un recorrido';}
function coUsoKey(e){return (e&&e.acc?(e.acc+':'):'')+String((e&&e.mailingId)||'');}
function coUsoDecl(e){var u=window.__coUsos||{};return (e&&e.mailingId&&u[coUsoKey(e)])||{};}
function coUsoObj(e){var dc=coUsoDecl(e);if(dc.o&&CO_OBJ[dc.o])return {k:dc.o,t:CO_OBJ[dc.o],decl:true};
 if(CO_OPER.test(String((e&&e.subject)||'')))return {k:'operativo',t:CO_OBJ.operativo,decl:false};
 if(coUsoGrupo(e)==='rec')return {k:'seguimiento',t:CO_OBJ.seguimiento,decl:false};
 return {k:'',t:'Objetivo sin declarar',decl:false};}
function coUsoFlujo(e){return (window.__coFlowOf||{})[coUsoKey(e)]||null;}
function coUsoKindLbl(k){return ({Workflow:'Flujo','Campaña':'Secuencia',Embudo:'Embudo',Reglas:'Regla automática'})[k]||'Flujo';}
function coUsoAudTxt(e){var dc=coUsoDecl(e);if(dc.a)return dc.a;if(coUsoGrupo(e)!=='rec')return '';var f=coUsoFlujo(e);
 return f?({Workflow:'Quien entra en el flujo','Campaña':'Quien se apunta a la secuencia',Embudo:'Quien se registra en el embudo',Reglas:'Quien cumple la regla'})[f.kind]||'Quien entra en el recorrido':'Quien entra en el recorrido';}
function coUsoLinea(e){var o=coUsoObj(e),f=coUsoFlujo(e),dc=coUsoDecl(e),a=coUsoAudTxt(e);
 var p=['<span class=co-uso-o'+(o.k?'':' data-sin=1')+(o.decl?'':' title="Supuesto: fíjalo en el detalle del correo"')+'>'+esc(o.t)+'</span>'];
 p.push('Para: '+(a?(dc.a?('<span translate=no>'+esc(a)+'</span>'):esc(a.charAt(0).toLowerCase()+a.slice(1))):'sin declarar'));
 if(f)p.push('<span title="'+esc(CO_DISP[f.kind]||'')+'">'+esc(coUsoKindLbl(f.kind))+': <span translate=no>'+esc(f.name)+'</span></span>');
 return p.join(' · ');}
// MUESTRA-CORREO-1 (MET-CORREO-07 · MET-CORREO-08) · UN solo umbral de muestra para toda la pestaña Correo. Un destacado, un
// ranking o una comparación solo se hacen con envíos de al menos CO_MUESTRA.min personas, y dos públicos solo se comparan si
// ninguno es más de CO_MUESTRA.razon veces mayor que el otro. Por debajo se dice «aún no hay muestra suficiente»: nunca un
// 100 % con 12 envíos ni un «la automatización abre mejor» con 44 correos frente a 34.881. La apertura es solo contexto.
var CO_MUESTRA={min:100,razon:10};
function coMuestraOk(e){return (Number(e&&e.sent)||0)>=CO_MUESTRA.min;}
function coMuestraAviso(n){n=Number(n)||0;return 'Aún no hay muestra suficiente: '+(n===1?'1 persona lo recibió':mxFmt(n)+' personas lo recibieron')+' y hacen falta '+mxFmt(CO_MUESTRA.min)+' o más.';}
function coPct(a,b){return (b>0&&a!=null)?(String(Math.round(a/b*1000)/10).replace('.',',')+'%'):'—';}
function coPulsaron(e){if(!e)return null;if(e.clicked!=null)return Number(e.clicked)||0;return e.clickRatePct!=null?Math.round((Number(e.sent)||0)*(Number(e.clickRatePct)||0)/100):null;}
function coComparables(arr){
 var ok=(arr||[]).filter(coMuestraOk);
 if(ok.length<2)return {ok:false,n:ok.length,motivo:'Aún no hay muestra suficiente para comparar: hacen falta al menos dos con '+mxFmt(CO_MUESTRA.min)+' personas o más cada uno.'};
 var mn=Infinity,mx=0;
 ok.forEach(function(e){var s=Number(e.sent)||0;if(s<mn)mn=s;if(s>mx)mx=s;});
 if(mx>mn*CO_MUESTRA.razon)return {ok:false,n:ok.length,mn:mn,mx:mx,motivo:'Sus públicos son de tamaño muy distinto (de '+mxFmt(mn)+' a '+mxFmt(mx)+' personas): compararlos por porcentaje daría una lectura engañosa.'};
 return {ok:true,n:ok.length,mn:mn,mx:mx,motivo:''};
}
// Dos grupos (o dos objetivos) a comparar: cada uno con su suma de envíos; comparables si ambos llegan al mínimo y no se llevan más de «razon» veces.
function coGruposComparables(sa,sb){
 var a=Number(sa)||0,b=Number(sb)||0;
 if(a<CO_MUESTRA.min||b<CO_MUESTRA.min)return {ok:false,motivo:'Aún no hay muestra suficiente para compararlos: '+(a<CO_MUESTRA.min&&b<CO_MUESTRA.min?'ninguno llega':'uno no llega')+' a '+mxFmt(CO_MUESTRA.min)+' personas.'};
 if(Math.max(a,b)>Math.min(a,b)*CO_MUESTRA.razon)return {ok:false,motivo:'Sus públicos son de tamaño muy distinto ('+mxFmt(Math.min(a,b))+' frente a '+mxFmt(Math.max(a,b))+' personas): compararlos por porcentaje daría una lectura engañosa.'};
 return {ok:true,motivo:''};
}
// /MUESTRA-CORREO-1
function mxCorreoSel(v){window.__mxSiAcc=v;mxStateSave();
 var w=document.getElementById('mx_cosel_wrap');
 if(w&&window.__mxCoAccs&&window.__mxCoAccs.length)w.innerHTML=mxDD('mxCorreoSel',ICN('mail'),mxCoDDOpts(v),v,'Cuentas de correo de este negocio');
 mxRender();}
// CUENTAS-CORREO-1 (MET-CORREO-01) · una, varias o todas las cuentas de correo del negocio.
// La selección viaja como lista separada por comas; vacía = todas.
function mxCoDDOpts(v){var o=(window.__mxCoAccs||[]).slice();if(v&&String(v).indexOf(',')>0)o.splice(1,0,{v:v,t:'Varias cuentas ('+String(v).split(',').length+')'});return o;}
function mxCoToggle(id){var all=window.__mxCoAllIds||[];if(!all.length)return;
 var cur=window.__mxSiAcc?String(window.__mxSiAcc).split(',').filter(function(x){return all.indexOf(x)>=0;}):[];
 if(!cur.length)cur=all.slice();
 var i=cur.indexOf(id);
 if(i>=0){if(cur.length===1){toast('Deja al menos una cuenta elegida','warn');return;}cur.splice(i,1);}else cur.push(id);
 cur=all.filter(function(x){return cur.indexOf(x)>=0;});
 mxCorreoSel(cur.length===all.length?'':cur.join(','));}
// CUENTAS-CORREO-1 · la tabla en CSV, con el negocio y el remitente en CADA fila.
function mxCoCsv(){var rows=window.__mxCoTbl||[];var neg=window.__mxCoNeg||window.__mxWsLabel||'';
 var esc2=function(v){var num=typeof v==='number'&&isFinite(v);v=String(v==null?'':v);if(!num&&/^[=+@\\t\\r-]/.test(v))v="'"+v;return (v.indexOf(',')>=0||v.indexOf('"')>=0||v.indexOf('\\n')>=0||v.indexOf('\\r')>=0)?'"'+v.replace(/"/g,'""')+'"':v;};
 var NV=function(v){return v==null?'':v;};
 // CIFRAS-CORREO-1 · el período va en cada fila y las cifras dicen que son PERSONAS por correo.
 var per=(typeof mxRangeLabel==='function')?mxRangeLabel():'';
 var L=[['negocio','periodo','remitente','asunto','fecha','tipo','grupo','objetivo','audiencia','flujo','enviados','personas_que_abrieron','personas_que_pulsaron','abrieron_pct','pulsaron_sobre_enviados_pct','pulsaron_de_quienes_abrieron_pct','rebotes_pct'].join(',')];
 rows.forEach(function(e){L.push([neg,per,e.account||'',e.subject||'',e.scheduledAt?String(e.scheduledAt).slice(0,10):'',mxCorreoTypeLabel(e.emailType),coUsoNom1(coUsoGrupo(e)),coUsoObj(e).t,coUsoAudTxt(e),(coUsoFlujo(e)||{}).name||'',NV(e.sent),NV(e.opened),NV(e.clicked),NV(e.openRatePct),NV(e.clickRatePct),NV(e.clickThroughOpenRatePct),NV(e.bounceRatePct)].map(esc2).join(','));});
 var blob=new Blob(['\ufeff'+L.join('\\r\\n')],{type:'text/csv;charset=utf-8'});
 var slugx=function(x){return String(x||'').toLowerCase().normalize('NFD').replace(/[\\u0300-\\u036f]/g,'').replace(/[^a-z0-9]+/g,'-').replace(/^-+|-+$/g,'');};
 var el=document.createElement('a');el.href=URL.createObjectURL(blob);el.download='correo-'+(slugx(neg)||'negocio')+'.csv';document.body.appendChild(el);el.click();setTimeout(function(){URL.revokeObjectURL(el.href);el.remove();},1500);}
function mxCorreoQ(){var q='days='+window.__mxDays;if(window.__mxFrom&&window.__mxTo){q+='&from='+window.__mxFrom+'&to='+window.__mxTo;
 // RANGO-CORREO-2 · y el dia YA RESUELTO en la zona del usuario, para que el servidor no lo
 // recalcule en la suya. Sin esto, elegir «1-12 sep» desde España pedia desde el 31 de agosto.
 q+='&dfrom='+mxISODia(window.__mxFrom)+'&dto='+mxISODia(window.__mxTo);}if(window.__mxSiAcc){q+='&si_acc='+encodeURIComponent(window.__mxSiAcc);}return q;}
