 var filas=fila('Grupo',esc(coUsoNom1(g)))+fila('Tipo',esc(mxCorreoTypeLabel(e.emailType)));
 if(g==='rec')filas+=fila('Pertenece a',f?(esc(coUsoKindLbl(f.kind))+' <span translate=no>«'+esc(f.name)+'»</span>'):'<span class=muted>Sin flujo identificado</span>')+fila('Cuándo sale',esc(f?(CO_DISP[f.kind]||'Se envía al entrar en el recorrido'):'Se envía al entrar en el recorrido'));
