  var notaT=(r.nota||'')+(r.acum!=null?(' Seguidores que tienes hoy en cada red: '+r.acum+' (no se suman: no son personas distintas).'):'');
 return '<div class=card>'+cab+big+grid+'<p class="ap-help or-pie">'+base+(notaT?(' <span class=or-mas title="'+esc(notaT)+'">ⓘ Cómo se cuenta</span>'):'')+'</p></div>';
