// AUTO-MEDICION-B-1 (MET-AUTO-11) · destacados y avisos verificables: base mínima, comparación entre flujos del mismo objetivo y enlace para comprobarlo.
// MET-AUTO-11-FIN · la finalización solo se juzga en flujos cuyo final ES el objetivo (vender, agendar,
// captar, entregar). Los de espera o traspaso (recordatorio de cita, cualificar y derivar, conversar) o
// sin clasificar terminan bien sin llegar al último paso: un porcentaje bajo ahí no es una incidencia.
function mxFinMide(f){return !!f&&f.inicio!=='cita'&&['vender','agendar','captar','entregar'].indexOf(f.funcion)>=0;}
function mxAutoB11(m,d,fLnk){
 var tit='Descubrimientos verificables';
 var per=' · últimos '+(window.__mxDays||30)+' días';
 var fx={};(d.flows||[]).forEach(function(f){fx[f.id]=f;});
 var MIN=20;var out=[];var fl=(m&&m.flujos)||[];
 var base=fl.filter(function(f){return f.entradas>=MIN;});
 var NOM={compra:'que compren',respuesta:'que respondan',persona:'pasar a una persona'};
 var logr=function(f){return f.objetivo==='compra'?f.compraron:(f.objetivo==='respuesta'?f.respondieron:f.derivadas);};
 var tasa=function(f){return logr(f)/f.entradas;};
 ['compra','respuesta','persona'].forEach(function(t){
  var g=base.filter(function(f){return f.objetivo===t;}).sort(function(a,b){return tasa(b)-tasa(a);});
  if(g.length<2)return;
  var a=g[0],b=g[g.length-1];var pa=Math.round(tasa(a)*100),pb=Math.round(tasa(b)*100);
  if(pa-pb<10)return;
  out.push({ic:'check',txt:'Entre los flujos que buscan '+NOM[t]+', '+fLnk({id:a.id,name:a.name})+' lo consigue más: <b>'+pa+'%</b> ('+mxFmt(logr(a))+' de '+mxFmt(a.entradas)+') frente a <b>'+pb+'%</b> de '+fLnk({id:b.id,name:b.name})+' ('+mxFmt(logr(b))+' de '+mxFmt(b.entradas)+')'+per+'.'});
 });
 base.forEach(function(f){
  var p=(f.pasos||[]).slice().sort(function(a,b){return b.abandonan-a.abandonan;})[0];
  if(p&&mxFinMide(fx[f.id])&&p.abandonan>=5&&p.abandonan/f.entradas>=0.2)out.push({ic:'alert',txt:'En '+fLnk({id:f.id,name:f.name})+' abandonan <b>'+mxFmt(p.abandonan)+'</b> de '+mxFmt(f.entradas)+' ('+Math.round(p.abandonan/f.entradas*100)+'%) justo en «'+esc(p.txt)+'»'+per+'.'});
 });
 (d.flows||[]).forEach(function(f){
  if((f.sinEntregar||0)>=3)out.push({ic:'alert',txt:'En '+fLnk({id:f.id,name:f.name})+' un mensaje no llegó a <b>'+mxFmt(f.sinEntregar)+'</b> personas: no es falta de interés, hay que revisar el envío.'});
 });
 var rc=d.recaudado||{};var comp=rc.compradores||0;
 var nota='Solo se destaca un flujo con al menos '+MIN+' entradas, comparándolo con otro que busque lo mismo y con una diferencia de 10 puntos o más. Tener muchas entradas, o una venta suelta, no destaca nada por sí solo.'
  +(comp>0&&comp<3?(' Ahora mismo hay '+mxFmt(comp)+' compra'+(comp===1?'':'s')+' atribuida'+(comp===1?'':'s')+' a los flujos: aún es poco para señalar un ganador.'):'');
 if(!out.length)return '<div class=card><h3>'+tit+'</h3>'+empty({ic:'sparkles',title:'Nada que destacar con garantías',body:nota})+'</div>';
 return '<div class="card mx-insights"><h3>'+tit+'</h3><p class=ap-help style="margin:0 0 10px">'+nota+'</p><div class=mx-ins-list>'+out.map(function(x){return '<div class=mx-ins-row><span class=mx-ins-ic>'+ICN(x.ic)+'</span><span class=mx-ins-tx>'+x.txt+'</span></div>';}).join('')+'</div></div>';
}
