  +'<div class=card><div class=row style="justify-content:space-between;gap:8px;flex-wrap:wrap"><b>Flujos del recorrido</b><span class=muted id=mxCampCnt style="font-size:12.5px">'+mxCuenta(def.flowIds.length,'elegido','elegidos')+'</span></div>'
  +'<input id=mxCampQ placeholder="Buscar flujo" oninput="mxCampBuscar(this.value)" style="width:100%;margin:8px 0">'
