function mxCampObj(b){window.__mxCampEd.obj=b.getAttribute('data-obj');b.parentNode.querySelectorAll('button').forEach(function(x){x.classList.toggle('primary',x===b);x.classList.toggle('sec',x!==b);});}
function mxCampFlujo(cb){var l=window.__mxCampEd.flows;var k=l.indexOf(cb.value);if(cb.checked&&k<0)l.push(cb.value);if(!cb.checked&&k>=0)l.splice(k,1);var e=document.getElementById('mxCampCnt');if(e)e.innerHTML=mxCuenta(l.length,'elegido','elegidos');}
