 try{await api('/admin/api/campanas/borrar',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:E.id})});}catch(e){toast((e&&e.message)||'No se ha podido quitar la campaña.','err');return;}
