async function ytAutoTest(){var b=document.getElementById('ytTestBtn');var _h=b?b.innerHTML:'';
 if(b){b.disabled=true;b.textContent='Probando…';}
 var r=await post('/admin/api/yt-autoreply/test',{dryRun:1}).catch(function(e){return {ok:false,error:(e&&e.message)||'sin conexión'};});
 if(b){b.disabled=false;b.innerHTML=_h;}
 if(!r||!r.ok){toast('No se pudo probar|'+((r&&r.error)||'reintenta'),'err');return;}
 var res=Number(r.leidos||0)+' leídos · '+Number(r.frescos||0)+' nuevos · '+Number(r.yaVistos||0)+' ya vistos · '+Number(r.casados||0)+' encajan';
 var mot=(r.motivos||[]).join(' ');
 toast('Prueba hecha (no se ha publicado nada)|'+res+(mot?' — '+mot:''),mot?'warn':'ok');}
// Tarjeta de canales conectados, espejo de loadIgAcc: quién responde de verdad,
// con sus cifras reales, dentro de la propia pestaña (nadie va a Conexiones a
