function fbTrigShort(t){if(!t)return'';if(t.type==='ig_comment')return'Comentario';if(t.type==='ig_story')return'Historia';if(t.type==='ig_dm')return'DM directo';if(t.type==='yt_comment')return'Comentario';if(t.type==='li_comment')return'Comentario';if(t.type==='wa_any')return'Cualquier mensaje';if(t.type==='booking')return'Nueva reserva';if(t.type==='typeform')return'Typeform';if(t.type==='formulario')return'Formulario';if(t.type==='recordatorio')return'Aviso de reunión';if(t.type==='email')return t.emEvent==='clicked'?'Clic en correo':'Correo abierto';return'Palabra clave';}
// RECORDATORIO-FLOW-1 · antelación legible de un aviso (1440 → «1 día»).
function mtAntesLbl(min){min=Number(min)||1440;return min%1440===0?(min/1440)+(min===1440?' día':' días'):min%60===0?(min/60)+' h':min+' min';}
