 var lbl=ig?'Cuenta de Instagram':fb?'Página de Facebook':yt?'Canal de YouTube':li?'Página de LinkedIn':'Número de WhatsApp';var allLbl=ig?'Todas las cuentas':fb?'Todas las Páginas':yt?'Todos los canales':li?'Todas las Páginas':'Todos los números';
