   +(bApp&&!bHit?'<option value="'+esc(bApp)+'" selected>No disponible ('+esc(bApp)+')</option>':'');
  var bTv=String(trb.tplVars||'');if(bTv&&bTv!=='dia_hora'){bTv=mtTrgHuecos(bTv).join(',');if(bTv==='cita,cuando')bTv='';else if(bTv==='fecha,hora')bTv='dia_hora';}
  var bVs=[['',mtTrgHuecosLbl('')],['dia_hora',mtTrgHuecosLbl('dia_hora')],['nombre,fecha,hora',mtTrgHuecosLbl('nombre,fecha,hora')]];
  if(!bVs.some(function(x){return x[0]===bTv;}))bVs.push([bTv,mtTrgHuecosLbl(bTv)]);
  return '<div style="flex:1 1 100%;min-width:280px" id=ftmediawrap>'
