// ---- Drag & drop: reordenar pasos arrastrándolos a un punto "+" ----
// Encuentra la arista (padre,clave,índice) que apunta a este nodo.
function fbFindParentEdge(id){var f=window.__f;if(f.start===id)return{p:null,k:'start',oi:null};var res=null;Object.keys(f.nodes).forEach(function(pid){var o=f.nodes[pid];if(!o)return;if(o.next===id)res={p:pid,k:'next',oi:null};if(o.yes===id)res={p:pid,k:'yes',oi:null};if(o.no===id)res={p:pid,k:'no',oi:null};if(o.options)o.options.forEach(function(op,ix){if(op&&op.next===id)res={p:pid,k:'opt',oi:ix};});});return res;}
// Mueve el nodo a la arista destino (p2,k2,oi2): lo descuelga de su sitio
// (el padre salta a su forward) y lo inserta en el destino. Solo nodos lineales.
function fbMoveNode(id,p2,k2,oi2){var f=window.__f;var o=f.nodes[id];if(!o)return;if(p2===id)return;var pe=fbFindParentEdge(id);if(!pe)return;if(pe.p===p2&&pe.k===k2&&pe.oi===oi2)return;var fwd=o.next||'';setEdge(pe.p,pe.k,pe.oi,fwd);var target=getEdge(p2,k2,oi2);o.next=target||'';setEdge(p2,k2,oi2,id);window.__fbtab='preview';fbRenderTree();toast('Paso movido','ok');}
