 Object.keys(f.nodes).forEach(function(kk){var n=f.nodes[kk];if(n.next===id)n.next=fwd;if(n.yes===id)n.yes=fwd;if(n.no===id)n.no=fwd;if(n.options)n.options.forEach(function(op){if(op.next===id)op.next=fwd;});});
 delete f.nodes[id];document.querySelectorAll('.ovl').forEach(function(x){x.remove();});fbRenderTree();
