 var ok=await confirmAct({title:'¿Mover «'+wsLabel+'» a '+destLbl+'?',
  body:'El negocio y todos sus datos pasan a pertenecer a ese grupo. Los usuarios del grupo actual dejarán de verlo.',
  ok:'Mover',cancel:'Cancelar',kind:'primary'});
 if(!ok)return;
 var r=await post('/admin/api/workspaces/'+encodeURIComponent(wsId)+'/group',{group_id:destGid}).catch(function(){return {ok:false,error:'fallo de red'};});
