 if(lstErr){
  if(!viewAlive(_gen))return;
  v.innerHTML=H('Negocios','Cada negocio tiene sus propios contactos, conversaciones, métricas y ajustes, separados del resto.')
   +'<div class=card>'+empty({ic:'alert',title:(lstErr.status===403?'Sin permiso para ver los negocios':'No se pudieron cargar los negocios'),body:(lstErr.status===403?'Tu usuario no tiene acceso a esta sección.':'Comprueba la conexión e inténtalo de nuevo.'),ctaLabel:'Reintentar',ctaAction:'rWorkspaces()'})+'</div>';
  return;
 }
 var allWss=(lst&&lst.workspaces)||[];
 // Separar activos y archivados (env-admin); user DB nunca recibe archivados.
 var wss = allWss.filter(function(w){return !w.archived;});
 var archivedWss = allWss.filter(function(w){return !!w.archived;});
 var curId=(window.__currentWs&&window.__currentWs.id)||'default';
 var curWs=wss.find(function(w){return w.id===curId;})||window.__currentWs;
 var headerBtn = isEnvAdmin ? '<button class=primary type=button onclick=wsCreateOpen()>'+ICN('plus')+'Nuevo negocio</button>' : '';
 // DISENO-1 · «Cambiar» abre su propio desplegable bajo el botón (el estándar del panel, mx-wfdd).
