 // ESTADO-CONEXION-1 (CON-04) · con páginas nace «Comprobando…»: lo resuelve fbPermCheck.
 window.__cnFbPages=fbPages;
 var fbCard = '<div class="cn-card cn-card-fb"'+(fbPages.length?cnEstA('load','',0,'','fb'):cnEstA(stackReady?'sin':'pend'))+'>'
  +'<div class=cn-head><span class=cn-ic-fb>'+netIcoColor('facebook','fff')+'</span><div class=cn-title><h3>Facebook</h3><span class=cn-sub>'+esc(fbHeadSub)+'</span></div></div>'
  +(fbPages.length?'<div class=cn-fb-list>'+fbList+'</div>':'<p class=cn-desc>Conecta tus páginas de Facebook. Si ya conectaste Instagram, su página de Facebook queda conectada automáticamente. <b>Nota:</b> solo se pueden conectar páginas, no perfiles personales.</p>')
