  var accOpts = (ads.accounts||[]).map(function(a){return '<option value="'+esc(a.id)+'"'+(String(a.id)===String(ads.selectedId)?' selected':'')+'>'+esc(a.name)+(a.currency?(' · '+esc(a.currency)):'')+'</option>';}).join('');
