    var metaInner=waCard+igCard+(FUERA_MVP.has('facebook')?'':fbCard)+(FUERA_MVP.has('ads')?'':adsCard);
    // CONEXIONES-PEND-1 · las cuatro tarjetas de Meta están pendientes exactamente cuando
