 // === Tarjeta "Redes sociales" (presenta los 3 grupos como UNA integración) ===
 var social=(apCfg&&apCfg.social)||{platforms:[],groups:[],ready:{}};
 var zKeySet=!!apCfg.hasZernioKey;
 var zNets=(social.platforms&&social.platforms.length)?social.platforms:['facebook','instagram','linkedin','tiktok','youtube'];
 var zReady=social.ready||{};
 window.__socialReady=zReady; // lo usa cnZConnect para avisar si falta la credencial del grupo
 var zGroups=(social.groups&&social.groups.length)?social.groups:[{platforms:['facebook','instagram']},{platforms:['linkedin','tiktok']},{platforms:['youtube','linkedin_pagina']}];
 var zernioCard='<div class="cn-card cn-card-pz'+(zKeySet?' cn-configured':'')+'" id=cn_z'+(zKeySet?cnEstA('load','',0,'','z'):cnEstA('sin'))+'>'
  +'<div class=cn-head><span class=cn-ic-pz>'+ICN('link')+'</span><div class=cn-title><h3>Redes sociales</h3><span class=cn-sub>'+(zKeySet?'Conecta tus redes y publica con un clic':'Conéctalo para publicar en tus redes')+'</span></div></div>'
  // RECONECTAR-RED-1 · una fila por red con su estado y UNA acción: Conectar, o Reconectar si la
