 var subs=d.wabaSubscriptions||[]; var subsHtml='';
 if(subs.length){
  var allSub=subs.every(function(s){return s.subscribed;});
  subsHtml='<div class="cn-diag-row '+(allSub?'ok':'warn')+'"><div class=cn-diag-h><b>'+ICN('inbox')+' Recepción de mensajes (suscripción a la app)</b><span>'+(allSub?'OK':'acción requerida')+'</span></div>'
   +subs.map(function(s){return '<div class=cn-diag-sub style="margin-top:5px">WABA '+esc(s.wabaId)+' · '+(s.subscribed?ICN('check')+' suscrita — recibe mensajes':ICN('x')+' NO suscrita — Meta no entrega sus mensajes'+(s.error?' ('+esc(s.error)+')':''))+'</div>';}).join('')
   +(allSub?'':'<div class=cn-diag-fix>'+ICN('alert')+'Una o más cuentas de WhatsApp Business no están suscritas a esta app: por eso solo entran los mensajes del principal. Pulsa «Suscribir webhooks» para arreglarlo en 1 clic.</div>')
  +'</div>';
 }
 // ECOS-APP-VERDE-1 · ¿lo que se escribe desde la app verde / WhatsApp Web llega a la Bandeja?
