 var eco=d.ecosAppVerde||null; var ecoHtml='';
 if(eco&&eco.estado!=='desconocido'){var okE=eco.estado==='ok';
  ecoHtml='<div class="cn-diag-row '+(okE?'ok':'warn')+'"><div class=cn-diag-h><b>'+ICN('phone')+' Lo que escribes desde la app de WhatsApp</b><span>'+(okE?'llega a la Bandeja':'NO llega a la Bandeja')+'</span></div>'
   +'<div class=cn-diag-sub style="margin-top:5px">'+(okE?ICN('check')+' Meta avisa al panel de cada mensaje que mandas desde el móvil o desde WhatsApp Web: la conversación se ve entera aquí.':ICN('x')+' Meta no avisa al panel de los mensajes que mandas desde el móvil o desde WhatsApp Web: esas respuestas no aparecen en la Bandeja y no se pueden recuperar después.')+'</div>'
   +(okE?'':'<div class=cn-diag-fix>'+ICN('alert')+'Avisa al administrador del panel para que lo active.'+(window.__isEnv?' <span class=muted>Detalle para el operador: en la app de Meta → WhatsApp → Webhooks, suscribe el campo <code>smb_message_echoes</code> (hoy: '+esc((eco.campos||[]).join(', ')||'ninguno')+').</span>':'')+'</div>')
  +'</div>';}
 box.innerHTML='<div class=cn-diag>'+numsHtml+subsHtml+ecoHtml+hitsHtml+'</div>'
