 var r=await post('/admin/api/wa-numbers/discover',body);
 if(!r||!r.ok){if(pick)pick.innerHTML='';toast('Error|'+((r&&r.error)||'no se pudieron buscar'),'err');return;}
 window.__waDisc={reuse:!!reuse,token:token};
