function waPicPick(inp){var f=inp.files&&inp.files[0];if(!f)return;var rd=new FileReader();
 rd.onload=function(){var img=new Image();img.onload=function(){var S=720,c=document.createElement('canvas');c.width=S;c.height=S;var x=c.getContext('2d');var s=Math.min(img.width,img.height),sx=(img.width-s)/2,sy=(img.height-s)/2;x.drawImage(img,sx,sy,s,s,0,0,S,S);var durl=c.toDataURL('image/jpeg',0.9);window.__waPic=durl.split(',')[1];var pv=document.getElementById('wapic_prev');if(pv){pv.src=durl;pv.style.display='block';}};img.src=rd.result;};
 rd.readAsDataURL(f);}
