// Pinta el estado de una ficha a partir de MENU_OCULTAS (nunca del DOM).
function mvPintar(b){var on=!MENU_OCULTAS.has(b.dataset.k);
 b.classList.toggle('on',on);b.setAttribute('aria-checked',String(on));
 b.title=on?'Se ve en el menú · pulsa para ocultarla':'Oculta en el menú · pulsa para volver a mostrarla';
}
// Cada pulsación cambia el menú al momento y guarda la lista ENTERA. Los guardados van
// en fila y cada uno lee la lista al salir: el último lleva el estado final aunque se
// pulse deprisa. Si uno falla, esa ficha vuelve a como estaba.
function mvToggle(b){
 var k=b.dataset.k;if(!k||MENU_FIJAS.indexOf(k)>=0)return;
 // Sin guardados en vuelo, lo que se ve es lo que tiene el servidor: es el punto al que volver.
 if(!window.__mvPend)window.__mvSrv=Array.from(MENU_OCULTAS);
 if(MENU_OCULTAS.has(k))MENU_OCULTAS.delete(k);else MENU_OCULTAS.add(k);
 mvPintar(b);navAplicar();
 window.__mvPend=(window.__mvPend||0)+1;stStatus('menu','Guardando…');
 // La fila guarda la cadena YA con su catch: un fallo de red no puede dejarla rechazada
 // (los .then siguientes no correrían y nada volvería a guardarse).
 var enviado;
 window.__mvCola=(window.__mvCola||Promise.resolve()).then(function(){
  enviado=Array.from(MENU_OCULTAS);
  return post('/admin/api/settings',{key:'menu.ocultas',value:JSON.stringify(enviado)});
 }).then(function(r){if(!r||!r.ok)throw {srv:(r&&r.error)||''};window.__mvSrv=enviado;}).catch(function(e){
  // Si hay más clics en la fila, el siguiente guardado ya lleva el estado entero que se ve:
  // deshacer aquí pisaría ese último clic. Sólo el último fallido vuelve a lo del servidor.
  if(window.__mvPend>1)return;
  MENU_OCULTAS=new Set(window.__mvSrv||[]);
  document.querySelectorAll('.mv-op').forEach(mvPintar);navAplicar();
  // Sólo el mensaje del servidor es para el cliente; un corte de red trae «Failed to fetch».
  toast((e&&e.srv)||'No se pudo guardar el menú. Vuelve a pulsar en unos segundos.','err');
  window.__mvKo=true;
 }).then(function(){
  window.__mvPend--;if(window.__mvPend>0)return;
  stStatus('menu',window.__mvKo?'':'Guardado',!window.__mvKo);window.__mvKo=false;
 });
}
