function apStep(n,t,b){return '<div class=ap-step><div class=n>'+n+'</div><h4>'+t+'</h4><p>'+b+'</p></div>';}
function apPlatforms(){return [...document.querySelectorAll('.appl:checked')].map(c=>c.value);}
// Combobox premium del Nicho: input libre + menú de presets filtrable (sustituye
// al <datalist> nativo, que no se puede estilar y se ve inconsistente).
function apComboOpen(){var c=document.getElementById('ap_niche_combo');if(c){c.classList.add('open');apComboFilter();}}
function apComboClose(){var c=document.getElementById('ap_niche_combo');if(c)c.classList.remove('open');}
function apComboToggle(){var c=document.getElementById('ap_niche_combo');if(!c)return;if(c.classList.contains('open'))apComboClose();else{var i=document.getElementById('ap_niche');if(i)i.focus();apComboOpen();}}
function apComboFilter(){var i=document.getElementById('ap_niche');if(!i)return;var q=(i.value||'').toLowerCase();var any=false;[].forEach.call(document.querySelectorAll('#ap_niche_menu .ap-combo-opt'),function(o){var m=o.textContent.toLowerCase().indexOf(q)>=0;o.style.display=m?'':'none';if(m)any=true;});var menu=document.getElementById('ap_niche_menu');if(menu)menu.classList.toggle('ap-combo-empty',!any);}
function apComboPick(el){var i=document.getElementById('ap_niche');if(i)i.value=el.textContent;apComboClose();if(i)i.focus();}
function apComboKey(e){if(e.key==='Escape'||e.key==='Enter')apComboClose();}
document.addEventListener('click',function(e){var c=document.getElementById('ap_niche_combo');if(c&&!e.target.closest('#ap_niche_combo'))c.classList.remove('open');});
