 // mismo icono y el mismo gesto que la de la cabecera de los modales.
 el.innerHTML='<span class=toast-ic>'+ic+'</span><div class=toast-tx>'+body+(acc?('<button type=button class=toast-acc onclick="'+esc(acc.js)+'">'+esc(acc.t)+'</button>'):'')+'</div>'+'<button type=button class=toast-x aria-label="Cerrar aviso" title="Cerrar">'+ICN('x')+'</button>';
 w.appendChild(el);
 var ms=(kind==='err'||kind==='warn')?7000:2600;
 // Una sola salida: la llamen la cuenta atras, la cruz o el boton de accion, el
