 el.addEventListener('mouseleave',function(){if(ido)return;clearTimeout(_t);_t=setTimeout(_hide,1500);});
 var _x=el.querySelector('.toast-x');if(_x)_x.addEventListener('click',function(e){e.preventDefault();e.stopPropagation();_hide();});
 // Si usas el boton de accion, el aviso ya ha cumplido: se aparta solo en vez de
