function refreshInboxUnread(){if(document.hidden)return;var now=Date.now();if(window.__navUnreadAt&&now-window.__navUnreadAt<5000)return;window.__navUnreadAt=now;Promise.resolve(window.__navGateP).then(function(){if(!dhCan('inbox'))return;var __sq=ixSelQsMenu();return api('/admin/api/inbox/unread'+(__sq?'?'+__sq:''),{nocache:true}).then(function(d){if(d&&d.ventana!=null&&!__sq)window.__navUnreadWin=Number(d.ventana)||0;if(d&&d.unread!=null)ixNavUnread(d.unread);});}).catch(function(){});}
