 var acts=document.querySelector('.topbar .tb-acts');
 if(acts){var busc=acts.querySelector('.tb-btn');if(busc&&busc.nextSibling)acts.insertBefore(fab,busc.nextSibling);else acts.appendChild(fab);}
 else document.body.appendChild(fab);
 // Un div, jamas un <aside>: el CSS global del panel viste los <aside> a pelo
